def installed() -> bool:
    """Convenience: re-export ``_singular.is_installed()``."""
    return _singular.is_installed()

def _require_singular() -> None:
    if not _singular.is_installed():
        raise ValueError(_INSTALL_MSG)

def _ring_decl(variables: Sequence[str], order: str = "lp", char: int = 0) -> str:
    """Build a ``ring R = char,(vars),order;`` declaration."""
    if not variables:
        raise ValueError("at least one variable required")
    vs = ",".join(variables)
    return f"ring R = {char},({vs}),{order};"

def _ideal_decl(name: str, generators: Sequence[str]) -> str:
    """Build ``ideal name = g1, g2, ...;``."""
    if not generators:
        return f"ideal {name};"
    body = ", ".join(generators)
    return f"ideal {name} = {body};"

def _normalize_polynomials(polys: Sequence[str]) -> list[str]:
    """Convert Python ``**`` syntax to Singular ``^`` syntax."""
    out = []
    for p in polys:
        if not isinstance(p, str):
            raise ValueError(f"polynomials must be strings, got {type(p).__name__}")
        out.append(p.replace("**", "^"))
    return out

def _resolve_order(name):
    """Map a textual order name (or pass-through SymPy order) to a
    SymPy monomial order object. Defaults to grevlex for HP work."""
    if name in _ORDER_MAP:
        return _ORDER_MAP[name]
    if name in (lex, grlex, grevlex):
        return name
    raise ValueError(f"unknown monomial order: {name!r}")

def _coerce_vars(ring_vars: Sequence) -> list:
    """Coerce ring_vars to list of SymPy Symbols."""
    out = []
    for v in ring_vars:
        if isinstance(v, Symbol):
            out.append(v)
        elif isinstance(v, str):
            out.append(symbols(v))
        else:
            raise ValueError(f"ring var must be Symbol or str, got {type(v).__name__}")
    if not out:
        raise ValueError("ring_vars must be non-empty")
    return out

def _coerce_generator(g: PolyLike, ring_vars: list) -> sympy.Expr:
    """Coerce a generator to a SymPy expression in the given ring vars."""
    if isinstance(g, Poly):
        return g.as_expr()
    if isinstance(g, str):
        # Allow the Singular-style `^` for power as well as Python `**`.
        s = g.replace("^", "**")
        return sympify(s)
    return sympify(g)

def _coerce_ideal(generators: Sequence[PolyLike], ring_vars: list) -> list:
    """Return list of SymPy expressions for the ideal generators."""
    return [_coerce_generator(g, ring_vars) for g in generators]

def _is_homogeneous_poly(expr: sympy.Expr, ring_vars: list) -> bool:
    """Test whether ``expr`` is homogeneous in ``ring_vars``."""
    expr = sympify(expr)
    if expr.is_zero:
        return True
    p = Poly(expr, *ring_vars)
    monoms = p.monoms()
    if not monoms:
        return True
    degs = {sum(m) for m in monoms}
    return len(degs) == 1

def _is_homogeneous_ideal(generators: list, ring_vars: list) -> bool:
    """Ideal is homogeneous iff every generator is homogeneous."""
    return all(_is_homogeneous_poly(g, ring_vars) for g in generators)

def _leading_monomial_exponents(gb: list, ring_vars: list, order) -> list:
    """Return the list of leading-monomial exponent tuples (one per GB
    element) under the given monomial order."""
    lms = []
    for poly in gb:
        # poly may already be a Poly; if not, wrap.
        if not isinstance(poly, Poly):
            poly = Poly(poly, *ring_vars)
        lm = poly.LM(order=order)
        # In SymPy >=1.13, LM returns a Monomial; coerce to tuple.
        if hasattr(lm, "exponents"):
            exp = tuple(lm.exponents)
        else:
            exp = tuple(lm)
        lms.append(exp)
    return lms

def _is_standard(exp: tuple, lms: list) -> bool:
    """Return True iff ``exp`` is NOT divisible by any leading monomial
    in ``lms``."""
    for lm in lms:
        if all(a <= b for a, b in zip(lm, exp)):
            return False
    return True

def _count_standard_monomials_at_degree(
    lms: list,
    n_vars: int,
    d: int,
) -> int:
    """Count standard monomials of total degree exactly ``d`` in ``n``
    variables, given the list of leading-monomial exponent tuples.

    For the trivial ideal (lms == []) and large d this is the binomial
    ``C(n + d - 1, n - 1)`` (number of monomials of degree d in n vars).
    """
    if d < 0:
        return 0
    # Generate all monomial exponents of total degree d.
    return sum(
        1
        for exp in _monomials_of_degree(n_vars, d)
        if _is_standard(exp, lms)
    )

def _monomials_of_degree(n: int, d: int):
    """Yield all exponent tuples ``(a_1, ..., a_n)`` with sum d."""
    if n == 0:
        if d == 0:
            yield ()
        return
    if n == 1:
        yield (d,)
        return
    for k in range(d + 1):
        for tail in _monomials_of_degree(n - 1, d - k):
            yield (k,) + tail

def _binomial_polynomial_C(k: int, t: Symbol) -> Poly:
    """Return the polynomial ``C(t + k, k) = (t+1)(t+2)...(t+k) / k!``.

    Identity:
      * ``k = 0``: returns the constant polynomial ``1``.
      * ``k < 0``: returns the zero polynomial.

    Used for the trivial-ideal cases:
      * Affine HP of ``(0) ⊂ k[x_1,...,x_n]``: ``C(t + n, n)``.
      * Graded HP of ``(0) ⊂ k[x_1,...,x_n]``: ``C(t + n - 1, n - 1)``.
    """
    if k < 0:
        return Poly(0, t)
    if k == 0:
        return Poly(1, t)
    poly = Integer(1)
    factorial = Integer(1)
    for i in range(1, k + 1):
        poly = poly * (t + i)
        factorial = factorial * i
    poly = sympy.expand(poly / factorial)
    return Poly(poly, t)

def krull_dimension(
    ideal_generators: Sequence[PolyLike],
    ring_vars: Sequence,
) -> int:
    """Krull dimension of ``k[x]/I``.

    Equals the degree of the affine Hilbert polynomial. By convention,
    if ``I`` contains a unit (the quotient is the zero ring) the
    dimension is reported as ``-1``.
    """
    vs = _coerce_vars(ring_vars)
    gens = _coerce_ideal(ideal_generators, vs)
    if not gens:
        return len(vs)
    # Detect unit ideal.
    for g in gens:
        gp = Poly(g, *vs)
        if gp.is_ground and not gp.is_zero:
            return -1
    hp = hilbert_polynomial(gens, vs)
    if hp.is_zero:
        return -1
    return hp.degree()

def is_zero_dimensional(
    ideal_generators: Sequence[PolyLike],
    ring_vars: Sequence,
) -> bool:
    """True iff ``V(I)`` is finite (Krull dim 0)."""
    return krull_dimension(ideal_generators, ring_vars) == 0

def _validate_ring_vars(ring_vars: Sequence) -> tuple[Symbol, ...]:
    """Coerce ``ring_vars`` to a tuple of sympy Symbols."""
    if ring_vars is None:
        raise ValueError("ring_vars must not be None")
    if not isinstance(ring_vars, (list, tuple)):
        # Allow a single string or symbol too.
        ring_vars = [ring_vars]
    if len(ring_vars) == 0:
        raise ValueError("ring_vars must contain at least one variable")
    out: list[Symbol] = []
    for v in ring_vars:
        if isinstance(v, Symbol):
            out.append(v)
        elif isinstance(v, str):
            out.append(sympy.Symbol(v))
        else:
            raise ValueError(
                f"ring_vars entries must be sympy Symbols or strings, "
                f"got {type(v).__name__}"
            )
    return tuple(out)

def _validate_order(monomial_order: str) -> str:
    if monomial_order not in _VALID_ORDERS:
        raise ValueError(
            f"unknown monomial_order {monomial_order!r}; "
            f"expected one of {sorted(_VALID_ORDERS)}"
        )
    return monomial_order

def _to_poly(f: PolyLike, ring_vars: tuple[Symbol, ...], order: str) -> Poly:
    """Convert ``f`` to ``sympy.Poly`` in the given ring.

    Note: SymPy's ``Poly()`` constructor does not accept a monomial-order
    keyword (the order lives on the ``Poly.rep`` ring or is supplied by
    ``sympy.groebner`` / ``sympy.reduced``). We therefore build the Poly
    in the default order; downstream calls pass ``order`` to those
    functions explicitly.
    """
    if isinstance(f, Poly):
        # Re-cast to ensure the generators match.
        try:
            return Poly(f.as_expr(), *ring_vars)
        except (GeneratorsError, PolynomialError) as exc:
            raise ValueError(
                f"polynomial {f!r} contains generators outside ring_vars "
                f"{ring_vars}: {exc}"
            ) from exc
    expr = sympify(f)
    # Reject expressions whose free symbols escape the ring.
    extra = set(expr.free_symbols) - set(ring_vars)
    if extra:
        raise ValueError(
            f"polynomial {f!r} contains generators {sorted(map(str, extra))} "
            f"outside ring_vars {[str(v) for v in ring_vars]}"
        )
    try:
        return Poly(expr, *ring_vars)
    except (GeneratorsError, PolynomialError) as exc:
        raise ValueError(f"failed to coerce {f!r} into ring: {exc}") from exc

def _to_polys(
    fs: Iterable[PolyLike],
    ring_vars: tuple[Symbol, ...],
    order: str,
) -> list[Poly]:
    return [_to_poly(f, ring_vars, order) for f in fs]

def _validate(type_: str, rank: int) -> None:
    """Validate (type, rank) lies in the Cartan-Killing classification.

    Raises ValueError otherwise.
    """
    if not isinstance(type_, str) or len(type_) != 1 or type_ not in _VALID_TYPES:
        raise ValueError(
            f"unknown root-system type {type_!r}; expected one of "
            f"{_VALID_TYPES}"
        )
    if not isinstance(rank, (int, np.integer)) or rank < 1:
        raise ValueError(f"rank must be a positive integer, got {rank!r}")
    if type_ == "A" and rank < 1:
        raise ValueError("A_n requires n >= 1")
    if type_ in ("B", "C") and rank < 2:
        raise ValueError(f"{type_}_n requires n >= 2 (rank=1 collapses to A_1)")
    if type_ == "D" and rank < 3:
        raise ValueError(
            "D_n requires n >= 3 (D_1 is trivial, D_2 = A_1 x A_1 is reducible)"
        )
    if type_ == "E" and rank not in (6, 7, 8):
        raise ValueError(f"E_n only exists for n in (6, 7, 8); got n={rank}")
    if type_ == "F" and rank != 4:
        raise ValueError(f"F_n only exists for n=4; got n={rank}")
    if type_ == "G" and rank != 2:
        raise ValueError(f"G_n only exists for n=2; got n={rank}")

def simple_roots(type_: str, rank: int) -> np.ndarray:
    """Simple roots as rows in standard Euclidean coordinates.

    Reference: Bourbaki Lie IV-VI Plates I-IX.
    """
    _validate(type_, rank)
    return _simple_roots_matrix(type_, rank).copy()

def _round_vec(v: np.ndarray) -> Tuple[float, ...]:
    """Round to 8 decimals, used as dict key for set membership."""
    return tuple(round(float(x), 8) for x in v)

def _all_roots_closure(simple: np.ndarray) -> List[np.ndarray]:
    """Compute all roots by closing simple roots under simple reflections.

    Returns the full set Phi (positive + negative) as a list of
    numpy vectors.
    """
    n_simple = simple.shape[0]
    seen = {_round_vec(a): a.copy() for a in simple}
    # Also include negatives of simple roots for completeness of closure.
    for a in simple:
        na = -a
        seen[_round_vec(na)] = na.copy()
    queue: List[np.ndarray] = [a.copy() for a in simple] + [-a.copy() for a in simple]
    while queue:
        v = queue.pop()
        for i in range(n_simple):
            w = _reflect(v, simple[i])
            key = _round_vec(w)
            if key not in seen:
                # Skip zero (not a root)
                if np.linalg.norm(w) < 1e-9:
                    continue
                seen[key] = w
                queue.append(w)
    return list(seen.values())

def weyl_group_order(type_: str, rank: int) -> int:
    """Order of the Weyl group W.

    Reference: Humphreys 2.10, Bourbaki Lie IV-VI Plates.
    """
    _validate(type_, rank)
    n = rank
    if type_ == "A":
        return factorial(n + 1)
    if type_ in ("B", "C"):
        return (2 ** n) * factorial(n)
    if type_ == "D":
        return (2 ** (n - 1)) * factorial(n)
    return _EXCEPTIONAL_W[(type_, rank)]

def _coxeter_number(type_: str, rank: int) -> int:
    """Coxeter number h.

    Reference: Humphreys 12.2 / Bourbaki Plates.
    """
    n = rank
    if type_ == "A":
        return n + 1
    if type_ in ("B", "C"):
        return 2 * n
    if type_ == "D":
        return 2 * n - 2
    if type_ == "E":
        return {6: 12, 7: 18, 8: 30}[n]
    if type_ == "F":
        return 12
    if type_ == "G":
        return 6
    raise ValueError(type_)  # pragma: no cover

def dynkin_diagram_string(type_: str, rank: int) -> str:
    """ASCII Dynkin diagram for the irreducible type.

    Each ``o`` is a node, each ``-`` a single bond, ``=>`` and ``<=`` are
    double bonds with arrows pointing toward the short root, ``=>=`` is
    the triple bond used for G_2.

    Reference: Humphreys 11.4, Bourbaki Plates.
    """
    _validate(type_, rank)
    n = rank
    if type_ == "A":
        nodes = "---".join(["o"] * n)
        return f"A_{n}: " + nodes
    if type_ == "B":
        # o---o---...---o=>=o (last two with arrow toward short root)
        if n == 1:
            return f"B_1: o"  # pragma: no cover (validated out)
        prefix = "---".join(["o"] * (n - 1))
        return f"B_{n}: {prefix}=>=o"
    if type_ == "C":
        prefix = "---".join(["o"] * (n - 1))
        return f"C_{n}: {prefix}=<=o"
    if type_ == "D":
        if n < 3:
            return f"D_{n}: o"  # pragma: no cover
        # D_n: chain of n-2 nodes branching to two on the right
        chain = "---".join(["o"] * (n - 2))
        return f"D_{n}: {chain}---o\n          \\\n           o"
    if type_ == "E":
        # E_n: chain o-o-o-... with a branch at the third node
        if n == 6:
            return "E_6: o---o---o---o---o\n             |\n             o"
        if n == 7:
            return "E_7: o---o---o---o---o---o\n             |\n             o"
        if n == 8:
            return "E_8: o---o---o---o---o---o---o\n             |\n             o"
    if type_ == "F":
        return "F_4: o---o=>=o---o"
    if type_ == "G":
        return "G_2: o#=#o"  # triple bond
    raise ValueError(type_)  # pragma: no cover

def is_dominant_weight(weight: Sequence[int], type_: str, rank: int) -> bool:
    """A weight given by its Dynkin labels (coefficients in the
    fundamental-weight basis) is dominant iff all labels are >= 0.

    Reference: Humphreys 13.1.

    Edge: empty or wrong-length input -> ValueError.
    """
    _validate(type_, rank)
    if not isinstance(weight, (list, tuple, np.ndarray)) or len(weight) == 0:
        raise ValueError("weight must be a non-empty sequence")
    if len(weight) != rank:
        raise ValueError(
            f"weight has {len(weight)} components; expected {rank}"
        )
    return all(int(w) >= 0 for w in weight)

def load_anchors(store_path: Path) -> List[CalibrationAnchor]:
    """Load CalibrationAnchors from the JSONL store. Returns empty list
    if the file doesn't exist (treat absent store as zero anchors).
    Raises ValueError on malformed JSON within an existing file."""
    if not store_path.exists():
        return []
    out: List[CalibrationAnchor] = []
    with open(store_path, encoding="utf-8") as f:
        for i, line in enumerate(f, start=1):
            if not line.strip():
                continue
            try:
                d = json.loads(line)
            except json.JSONDecodeError as e:
                raise ValueError(
                    f"malformed JSON in anchor store {store_path} at line {i}: {e}"
                ) from e
            if not isinstance(d, dict):
                raise ValueError(
                    f"anchor at {store_path}:{i} is not a JSON object; "
                    f"got {type(d).__name__}"
                )
            out.append(CalibrationAnchor.from_dict(d))
    return out

def from_dict(cls, d: Dict[str, Any]) -> "CalibrationAnchor":
    return cls(
        anchor_id=str(d.get("anchor_id", "")),
        label=str(d.get("label", "")),
        structural_signature=str(d.get("structural_signature", "")),
        tag_set=tuple(str(t) for t in (d.get("tag_set") or [])),
        raw=dict(d),
    )

def get_meta(callable_ref_or_fn: Any) -> Optional[ArsenalMeta]:
    """Look up metadata by ``"module:qualname"`` string or by the callable."""
    if isinstance(callable_ref_or_fn, str):
        return ARSENAL_REGISTRY.get(callable_ref_or_fn)
    if callable(callable_ref_or_fn):
        ref = f"{callable_ref_or_fn.__module__}:{callable_ref_or_fn.__qualname__}"
        return ARSENAL_REGISTRY.get(ref)
    return None

def registry_summary() -> Dict[str, Any]:
    """Aggregate stats for tooling."""
    by_cat: Dict[str, int] = {}
    by_eq: Dict[str, int] = {}
    n_with_cost = 0
    n_with_post = 0
    n_with_auth = 0
    for meta in ARSENAL_REGISTRY.values():
        cat = meta.category or "uncategorized"
        by_cat[cat] = by_cat.get(cat, 0) + 1
        eq = meta.equivalence_class or "untagged"
        by_eq[eq] = by_eq.get(eq, 0) + 1
        if meta.cost:
            n_with_cost += 1
        if meta.postconditions:
            n_with_post += 1
        if meta.authority_refs:
            n_with_auth += 1
    return {
        "total": len(ARSENAL_REGISTRY),
        "by_category": dict(sorted(by_cat.items())),
        "by_equivalence_class": dict(sorted(by_eq.items())),
        "with_cost_model": n_with_cost,
        "with_postconditions": n_with_post,
        "with_authority_refs": n_with_auth,
    }

def to_dict(self) -> Dict[str, Any]:
    return {
        "callable_ref": self.callable_ref,
        "cost": dict(self.cost),
        "postconditions": list(self.postconditions),
        "authority_refs": list(self.authority_refs),
        "equivalence_class": self.equivalence_class,
        "category": self.category,
        "notes": self.notes,
    }

def _format_per_entry_row(res: ProbeResult, catalog_names: List[str]) -> str:
    deg = len(res.entry.coeffs) - 1
    short_id = res.entry.paper_arxiv_id
    cells = []
    for c in catalog_names:
        actual = res.actual_hits.get(c, False)
        err = c in res.errors
        if err:
            cells.append("skip")
        elif actual:
            label = res.actual_results[c].match_label or "?"
            # Cap label length so the row doesn't blow out terminal width.
            label = label if len(label) <= 18 else label[:15] + "..."
            cells.append(f"HIT[{label}]")
        else:
            cells.append("miss")
    n_hits = sum(1 for v in res.actual_hits.values() if v)
    return (
        f"deg={deg:>3}  M={res.entry.mahler_measure:.6f}  "
        f"{short_id:<10}  hits={n_hits}  | "
        + " | ".join(f"{c:>17}: {v:<24}" for c, v in zip(catalog_names, cells))
    )

def format_per_entry_table(results: List[ProbeResult]) -> str:
    if not results:
        return "(empty)"
    catalog_names = list(results[0].actual_hits.keys())
    lines = [
        "Per-entry catalog cross-check results",
        "-" * 72,
    ]
    for res in results:
        lines.append(_format_per_entry_row(res, catalog_names))
        # Show surprises in a sub-line for readability.
        if res.surprises:
            sur = ", ".join(
                f"{c}({res.agreement[c]})" for c in res.surprises
            )
            lines.append(f"      surprises: {sur}")
    return "\n".join(lines)

def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Run the catalog cross-check on the recent-arXiv polynomial "
            "corpus and report results."
        )
    )
    parser.add_argument(
        "--offline",
        action="store_true",
        help=(
            "Use only the offline catalogs (Mossinghoff + lehmer_literature). "
            "Skips LMFDB / OEIS / arXiv live calls."
        ),
    )
    parser.add_argument(
        "--tol", type=float, default=1e-5, help="Catalog M-value tolerance."
    )
    args = parser.parse_args(argv)

    catalogs: Dict[str, Any]
    if args.offline:
        catalogs = {
            "Mossinghoff": DEFAULT_CATALOGS["Mossinghoff"],
            "lehmer_literature": DEFAULT_CATALOGS["lehmer_literature"],
        }
    else:
        catalogs = dict(DEFAULT_CATALOGS)

    results = probe_recent_polynomials(catalogs=catalogs, tol=args.tol)
    print(format_per_entry_table(results))
    summary = summarize_probe(results)
    print(format_summary(summary))
    return 0

def _identity_predictor(rank: int) -> int:
    """Trivial callable bound by the env: receives the predicted rank,
    returns it unchanged. The substrate uses this as the EVAL hook so
    each prediction generates one (binding, evaluation) row pair."""
    return int(rank)

def register_with_gymnasium() -> Optional[str]:
    """Register the env with gymnasium if available; return its id or None."""
    try:
        import gymnasium as gym
    except ImportError:
        return None
    env_id = "prometheus/BSDRank-v0"
    try:
        gym.register(
            id=env_id,
            entry_point="prometheus_math.bsd_rank_env:BSDRankEnv",
        )
    except Exception:
        # Already registered or signature changed; treat as soft success.
        pass
    return env_id

def __init__(self, shape: Tuple[int, ...]):
    self.shape = tuple(shape)
    self.dtype = np.float64

def close(self) -> None:
    if self._kernel is not None:
        try:
            self._kernel.conn.close()
        except Exception:  # pragma: no cover -- best-effort close
            pass
    self._kernel = None
    self._ext = None

def _obs(self) -> np.ndarray:
    if self._current is None:
        # Pre-reset zeros (some baselines call _obs after construction).
        return np.zeros(_obs_dim(self._n_ap), dtype=np.float64)
    ap = np.asarray(self._current.a_p, dtype=np.float64)
    log_n = math.log10(max(1, self._current.conductor))
    history = np.array([
        log_n,
        self.running_accuracy(),
        self._state.last_reward / REWARD_HIT,  # in [0, 1]
        float(self._state.n_episodes_seen),
        float(self._state.last_pred_rank),
        float(self._state.last_true_rank),
    ], dtype=np.float64)
    return np.concatenate([ap, history])

def running_accuracy(self) -> float:
    n = self._state.n_episodes_seen
    if n <= 0:
        return 0.0
    return float(self._state.n_correct) / float(n)

def kernel(self) -> SigmaKernel:
    if self._kernel is None:
        raise RuntimeError("env not reset yet")
    return self._kernel

def _require_torch() -> None:
    if not _HAVE_TORCH:
        raise RuntimeError(
            "PyTorch is required for the MLP backend. Install with "
            "`pip install torch` or skip-with-message."
        )

def welch_one_sided(a: np.ndarray, b: np.ndarray) -> float:
    """One-sided Welch t-test p-value: H1 = mean(a) > mean(b).

    Falls back to a normal approximation if scipy is unavailable.
    Mirrors ``_run_bsd_rank_pilot.py::_welch_one_sided``.
    """
    a = np.asarray(a, dtype=np.float64)
    b = np.asarray(b, dtype=np.float64)
    if a.size < 2 or b.size < 2:
        return float("nan")
    ma, mb = float(a.mean()), float(b.mean())
    va, vb = float(a.var(ddof=1)), float(b.var(ddof=1))
    se = math.sqrt(va / a.size + vb / b.size) if (va > 0 or vb > 0) else 1e-12
    t = (ma - mb) / max(se, 1e-12)
    df_num = (va / a.size + vb / b.size) ** 2
    df_den = (
        (va / a.size) ** 2 / max(a.size - 1, 1)
        + (vb / b.size) ** 2 / max(b.size - 1, 1)
    )
    df = df_num / max(df_den, 1e-30)
    try:
        from scipy.stats import t as student_t
        return float(1.0 - student_t.cdf(t, df=df))
    except Exception:
        return float(0.5 * (1.0 - math.erf(max(t, 0.0) / math.sqrt(2.0))))

def forward(self, obs):  # noqa: D401
    """Run MLP forward pass; returns raw logits, shape [B, n_actions].

    Accepts a torch tensor of shape [B, obs_dim] or [obs_dim]. The
    latter is unsqueezed to [1, obs_dim] then squeezed back.
    """
    if obs.ndim == 1:
        return self.net(obs.unsqueeze(0)).squeeze(0)
    return self.net(obs)

def close(self) -> None:
    if self._kernel is not None:
        try:
            self._kernel.conn.close()
        except Exception:
            pass
    self._kernel = None
    self._ext = None

def _obs(self) -> np.ndarray:
    if self._current is None:
        return np.zeros(rich_obs_dim(self._n_ap), dtype=np.float64)
    rich_vec = vectorize_rich(self._current, n_ap=self._n_ap)
    history = np.array([
        self.running_accuracy(),
        self._state.last_reward / REWARD_HIT,
        float(self._state.n_episodes_seen),
        float(self._state.last_pred_rank),
        float(self._state.last_true_rank),
    ], dtype=np.float64)
    return np.concatenate([rich_vec, history])

def _onehot(idx: int, n: int) -> np.ndarray:
    """Return an (n,) one-hot vector with a 1 at ``idx`` (clamped to [0, n))."""
    v = np.zeros(n, dtype=np.float64)
    if idx < 0:
        idx = 0
    if idx >= n:
        idx = n - 1
    v[idx] = 1.0
    return v

def _bucket_idx(value: int, buckets: Sequence[int]) -> int:
    """Bucket index for an integer ``value`` w.r.t. an exact-match list,
    with an implicit "above" bucket = ``len(buckets)``."""
    for i, b in enumerate(buckets):
        if value == b:
            return i
    return len(buckets)

def _torsion_structure_idx(ts: Sequence[int]) -> int:
    n = len(ts)
    if n == 0:
        return 0
    if n == 1:
        if int(ts[0]) == 2:
            return 2
        return 1
    if n == 2:
        a, b = int(ts[0]), int(ts[1])
        if a == 2 and b == 2:
            return 4
        if a == 2 and b % 2 == 0 and b > 2:
            return 3
    return 5

def _signD_idx(sd: int) -> int:
    if sd > 0:
        return 0
    if sd == 0:
        return 1
    return 2

def _radical_idx(rad: int) -> int:
    """5-bin log-scaled bucket for the conductor radical."""
    rad = max(int(rad), 1)
    log_rad = math.log10(rad)
    if log_rad < 1.0:
        return 0
    if log_rad < 2.0:
        return 1
    if log_rad < 3.0:
        return 2
    if log_rad < 4.0:
        return 3
    return 4

def dominant_canonicalizer(
    distribution: Mapping[str, float],
) -> Optional[tuple]:
    """Return (name, fraction) of the highest-fraction canonicalizer.
    Returns None on empty distribution."""
    if not distribution:
        return None
    name = max(distribution, key=distribution.get)
    return (name, distribution[name])

def to_dict(self) -> Dict[str, Any]:
    return {
        "ts": self.timestamp,
        "canonicalizer": self.canonicalizer,
        "claim_id": self.claim_id,
        "context": dict(self.context),
    }

def from_dict(cls, d: Mapping[str, Any]) -> "CanonicalizerObservation":
    return cls(
        timestamp=float(d["ts"]),
        canonicalizer=str(d["canonicalizer"]),
        claim_id=d.get("claim_id"),
        context=dict(d.get("context", {})),
    )

def read_all(self) -> Iterable[CanonicalizerObservation]:
    """Stream all logged observations from disk. Reads in append order."""
    if not self.log_path.exists():
        return
    with open(self.log_path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                yield CanonicalizerObservation.from_dict(json.loads(line))

def _validate_inputs(coeffs: List[int], m_value: float) -> None:
    """Shared input validation for all adapters."""
    if not coeffs:
        raise ValueError("coeffs must be a non-empty list of integers")
    if not isinstance(m_value, (int, float)):
        raise ValueError(f"m_value must be a number, got {type(m_value).__name__}")
    if m_value < 0:
        raise ValueError(f"m_value must be >= 0, got {m_value}")
    if not math.isfinite(m_value):
        raise ValueError(f"m_value must be finite, got {m_value}")

def _arxiv_wrapper(
    coeffs: List[int], m_value: float, tol: float = 1e-3
) -> CatalogResult:
    """Adapter signature wrapper around arxiv_title_fuzzy_check."""
    return arxiv_title_fuzzy_check(coeffs, m_value, m_tol=tol)

def run(self, coeffs: List[int], m_value: float) -> Dict[str, Any]:
    """Run the check; return the aggregated result."""
    return run_consistency_check(
        coeffs, m_value, catalogs=self.catalogs, tol=self.tol
    )

def _sample_from_prior(rng: np.random.Generator,
                       prior: np.ndarray) -> int:
    """Sample an action index from a categorical prior."""
    p = np.asarray(prior, dtype=np.float64)
    p = np.clip(p, 0.0, None)
    s = p.sum()
    if s <= 0.0:
        # Defensive fallback: uniform.
        return int(rng.integers(0, len(p)))
    p = p / s
    return int(rng.choice(len(p), p=p))

def _uniform_priors(degree: int, n_actions: int) -> Dict[int, np.ndarray]:
    half_len = degree // 2 + 1
    return {s: np.ones(n_actions, dtype=np.float64) / n_actions
            for s in range(half_len)}

def _summarize_seed_pool(seed_polys: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not seed_polys:
        return {"size": 0, "degree_dist": {}, "max_abs_coef_dist": {},
                "M_min": None, "M_max": None}
    deg_dist: Dict[int, int] = {}
    mac_dist: Dict[int, int] = {}
    Ms: List[float] = []
    for e in seed_polys:
        d = int(e["degree"])
        deg_dist[d] = deg_dist.get(d, 0) + 1
        mc = max(abs(int(c)) for c in e["coeffs"])
        mac_dist[mc] = mac_dist.get(mc, 0) + 1
        Ms.append(float(e["mahler_measure"]))
    return {
        "size": len(seed_polys),
        "degree_dist": dict(sorted(deg_dist.items())),
        "max_abs_coef_dist": dict(sorted(mac_dist.items())),
        "M_min": float(min(Ms)),
        "M_max": float(max(Ms)),
    }

def _summarize_priors(priors: Dict[int, np.ndarray],
                      coefficient_choices: Tuple[int, ...]) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = []
    for s in sorted(priors.keys()):
        p = priors[s]
        row = {
            "step": int(s),
            "top_coef": int(coefficient_choices[int(np.argmax(p))]),
            "top_prob": float(p.max()),
            "entropy": float(-(p * np.log(np.clip(p, 1e-12, None))).sum()),
            "by_coef": {
                int(coefficient_choices[i]): float(p[i])
                for i in range(len(p))
            },
        }
        rows.append(row)
    return {"per_step": rows}

def _welch(a_lbl: str, b_lbl: str) -> float:
    a = np.array(per_arm[a_lbl]["promote_rates"])
    b = np.array(per_arm[b_lbl]["promote_rates"])
    return _welch_t_test_one_sided(a, b)

def _welch_salem(a_lbl: str, b_lbl: str) -> float:
    a = np.array(per_arm[a_lbl]["salem_rates"])
    b = np.array(per_arm[b_lbl]["salem_rates"])
    return _welch_t_test_one_sided(a, b)

def _require_galois() -> None:
    if not _HAS_GALOIS:
        raise ImportError(
            "prometheus_math.coding_linear requires the `galois` "
            "package. Install with `pip install galois`."
        )

def bch_decode(
    received: Sequence[int],
    n: int,
    k: int,
    t: int,
) -> tuple[list[int], int]:
    """Decode a (possibly corrupted) BCH received word.

    Returns (decoded_message_bits, num_errors_corrected).
    """
    _require_galois()
    if len(received) != n:
        raise ValueError(
            f"received word must have length n={n}, got {len(received)}"
        )
    for b in received:
        if int(b) not in (0, 1):
            raise ValueError(f"received bit {b} must be 0 or 1")
    bch = _galois.BCH(n, d=2 * t + 1)
    if bch.k != k:
        raise ValueError(
            f"BCH(n={n}, t={t}) has k={bch.k}, not the requested k={k}"
        )
    GF2 = bch.field
    r_arr = GF2([int(b) for b in received])
    decoded, n_err = bch.decode(r_arr, errors=True)
    return [int(x) for x in decoded], int(n_err)

def _partitions_iter(
    n: int, max_part: int, distinct: bool
) -> Iterator[Partition]:
    """Yield partitions of n with parts <= max_part."""
    if n == 0:
        yield ()
        return
    for first in range(min(n, max_part), 0, -1):
        nxt_max = first - 1 if distinct else first
        for tail in _partitions_iter(n - first, nxt_max, distinct):
            yield (first,) + tail

def num_partitions(n: int, k: int | None = None) -> int:
    """Count the integer partitions of ``n``.

    With no ``k``, uses Euler's pentagonal number recurrence (Andrews
    1976, Cor. 1.8). With ``k`` given, uses the standard p(n, k)
    recurrence p(n, k) = p(n-1, k-1) + p(n-k, k).
    """
    if n < 0:
        return 0
    if k is None:
        return _p_total(n)
    return _p_with_parts(n, k)

def _p_with_parts(n: int, k: int) -> int:
    if n == 0 and k == 0:
        return 1
    if n <= 0 or k <= 0:
        return 0
    if k > n:
        return 0
    return _p_with_parts(n - 1, k - 1) + _p_with_parts(n - k, k)

def conjugate(partition: Sequence[int]) -> Partition:
    """Conjugate (transpose) partition.

    lambda'_i = #{j : lambda_j >= i}.
    """
    if not partition:
        return ()
    m = max(partition)
    return tuple(sum(1 for x in partition if x >= i) for i in range(1, m + 1))

def hook_length_array(partition: Sequence[int]) -> List[List[int]]:
    """Hook lengths for all cells, as a row-major list of lists."""
    return [
        [hook_length(partition, i, j) for j in range(partition[i])]
        for i in range(len(partition))
    ]

def _row_insert(P: List[List[int]], x: int) -> Tuple[int, int]:
    """Schensted row-insertion of ``x`` into tableau ``P`` (modifies P).

    Returns the (row, col) coordinates of the cell where the bumping
    cascade finally settles.
    """
    r = 0
    while True:
        if r == len(P):
            P.append([x])
            return (r, 0)
        row = P[r]
        # Find the leftmost element in row strictly greater than x.
        idx = None
        for k, val in enumerate(row):
            if val > x:
                idx = k
                break
        if idx is None:
            row.append(x)
            return (r, len(row) - 1)
        # Bump.
        bumped = row[idx]
        row[idx] = x
        x = bumped
        r += 1

def inverse_rsk(
    P: Sequence[Sequence[int]], Q: Sequence[Sequence[int]]
) -> List[int]:
    """Inverse RSK: recover the permutation from (P, Q)."""
    if len(P) != len(Q):
        raise ValueError("P and Q have different number of rows")
    if any(len(p) != len(q) for p, q in zip(P, Q)):
        raise ValueError("P and Q have different shapes")
    # Mutable working copies.
    Pw: List[List[int]] = [list(row) for row in P]
    n = sum(len(row) for row in P)
    out: List[int] = []
    for step in range(n, 0, -1):
        # Find cell containing `step` in Q (uniquely determined).
        cell = None
        for i, row in enumerate(Q):
            for j, val in enumerate(row):
                if val == step:
                    cell = (i, j)
                    break
            if cell is not None:
                break
        if cell is None:
            raise ValueError(f"step {step} missing in Q")
        i, _ = cell
        # Pop the rightmost cell of row i in Pw (which must be at column j).
        j = len(Pw[i]) - 1
        x = Pw[i].pop(j)
        # Reverse-bump x up through rows 0..i-1.
        for r in range(i - 1, -1, -1):
            row = Pw[r]
            # Find rightmost val < x to swap with.
            idx = None
            for k in range(len(row) - 1, -1, -1):
                if row[k] < x:
                    idx = k
                    break
            if idx is None:
                # Shouldn't happen for a valid (P, Q) pair, but be safe.
                raise ValueError("inverse_rsk: invalid tableau pair")
            row[idx], x = x, row[idx]
        out.append(x)
        # Strip empty trailing row from Pw if any.
        if not Pw[i] and i == len(Pw) - 1:
            Pw.pop()
    out.reverse()
    return out

def schur_polynomial(partition: Sequence[int], max_var: int):
    """Schur polynomial s_lambda(x_1, ..., x_{max_var}) via the
    bialternant formula:

        s_lambda = a_{lambda + delta} / a_delta,

    where delta = (n-1, n-2, ..., 0) and a_alpha = det(x_i^{alpha_j}).

    Reference: Macdonald (1995), I.3, eqn 3.1.
    """
    # Empty partition: s_() = 1 always.
    if not partition or all(p == 0 for p in partition):
        return sympy.Integer(1)
    if max_var <= 0:
        return sympy.Integer(0)
    # Pad partition to length max_var with zeros.
    lam = list(partition)
    if len(lam) > max_var:
        # Schur polynomial in fewer variables than parts is 0.
        if any(lam[i] > 0 for i in range(max_var, len(lam))):
            return sympy.Integer(0)
        lam = lam[:max_var]
    while len(lam) < max_var:
        lam.append(0)
    n = max_var
    xs = sympy.symbols(f"x_1:{n + 1}")
    delta = list(range(n - 1, -1, -1))
    alpha = [lam[i] + delta[i] for i in range(n)]
    # Numerator: det(x_i^{alpha_j})
    num = sympy.Matrix(
        [[xs[i] ** alpha[j] for j in range(n)] for i in range(n)]
    ).det()
    # Denominator: det(x_i^{delta_j}) = Vandermonde = prod_{i<j} (x_i - x_j)
    den = sympy.Matrix(
        [[xs[i] ** delta[j] for j in range(n)] for i in range(n)]
    ).det()
    quotient = sympy.simplify(num / den)
    return sympy.expand(quotient)

def bulgey(partition: Sequence[int]) -> Tuple[int, int]:
    """Return a (n, length) summary of a partition: (sum, len)."""
    return (sum(partition), len(partition))

def _to_tuple(w: Sequence[int]) -> Permutation:
    """Coerce ``w`` to an immutable tuple, validating it is a permutation
    of ``{1, ..., n}``."""
    t = tuple(int(x) for x in w)
    n = len(t)
    if n == 0:
        return t
    if sorted(t) != list(range(1, n + 1)):
        raise ValueError(
            f"not a permutation of (1..{n}): got {t}"
        )
    return t

def _check_same_size(w: Permutation, v: Permutation) -> None:
    if len(w) != len(v):
        raise ValueError(
            f"permutations have different sizes: {len(w)} vs {len(v)}"
        )

def _multiply(u: Permutation, v: Permutation) -> Permutation:
    """Composition (u . v)(k) = u(v(k))."""
    return tuple(u[v[k] - 1] for k in range(len(v)))

def _inverse(w: Permutation) -> Permutation:
    n = len(w)
    inv = [0] * n
    for i, x in enumerate(w):
        inv[x - 1] = i + 1
    return tuple(inv)

def num_inversions(w: Sequence[int]) -> int:
    """Return ``inv(w) = l(w)``, the Coxeter length."""
    return len(inversions(w))

def longest_element(n: int) -> Permutation:
    """``w_0 = (n, n-1, ..., 1)`` in S_n.

    Length is ``n*(n-1)/2``.
    """
    if n < 0:
        raise ValueError(f"n must be non-negative, got {n}")
    return tuple(range(n, 0, -1))

def _pattern_validate(p: Sequence[int]) -> Permutation:
    t = tuple(int(x) for x in p)
    if len(t) == 0:
        raise ValueError("pattern must be non-empty")
    if sorted(t) != list(range(1, len(t) + 1)):
        raise ValueError(
            f"pattern must be a permutation of (1..{len(t)}): got {t}"
        )
    return t

def is_pattern_avoiding(
    w: Sequence[int], patterns: Iterable[Sequence[int]]
) -> bool:
    """Return ``True`` iff ``w`` contains none of the given patterns.

    Reference: Bona, "Combinatorics of Permutations" (2nd ed. 2012),
    Ch. 4. Famous example: ``Av(132)`` in ``S_n`` has size ``C_n``,
    the n-th Catalan number.
    """
    pats = list(patterns)
    if len(pats) == 0:
        return True
    for p in pats:
        if permutation_pattern_count(w, p) > 0:
            return False
    return True

def rsk_shape(w: Sequence[int]) -> Tuple[int, ...]:
    """Shape of the insertion tableau ``P`` from RSK.

    Calls into ``prometheus_math.combinatorics_partitions.rsk`` and
    returns the row-length partition of ``P``.

    For a permutation of ``n``, this is a partition of ``n`` (a
    weakly-decreasing tuple of positive integers summing to n).

    Reference: Sagan (2001), Sec. 3.5; Stanley EC2 Sec. 7.11.
    """
    t = _to_tuple(w)
    if len(t) == 0:
        return ()
    P, _Q = _rsk(t)
    return tuple(len(row) for row in P)

def _all_permutations(n: int) -> List[Permutation]:
    """All permutations of (1..n) — brute, for small n."""
    if n == 0:
        return [()]
    from itertools import permutations as _it_perms

    return [tuple(p) for p in _it_perms(range(1, n + 1))]

def antichain_poset(n: int) -> Poset:
    """The antichain on ``n`` elements (no nontrivial relations)."""
    if n < 0:
        raise ValueError("n must be non-negative")
    return Poset(list(range(1, n + 1)), [])

def boolean_lattice(n: int) -> Poset:
    """``B_n`` — the lattice of subsets of ``{0, ..., n-1}`` ordered
    by inclusion."""
    if n < 0:
        raise ValueError("n must be non-negative")
    base = list(range(n))
    elements: List[frozenset] = []
    for mask in range(1 << n):
        s = frozenset(b for b in base if (mask >> b) & 1)
        elements.append(s)
    relations: List[Tuple[frozenset, frozenset]] = []
    for a in elements:
        for b in elements:
            if a < b:
                relations.append((a, b))
    return Poset(elements, relations)

def divisor_poset(n: int) -> Poset:
    """The divisor lattice ``D_n``: positive divisors of ``n`` ordered
    by divisibility."""
    if n < 1:
        raise ValueError("n must be a positive integer")
    divisors = [d for d in range(1, n + 1) if n % d == 0]
    relations: List[Tuple[int, int]] = []
    for a in divisors:
        for b in divisors:
            if a != b and b % a == 0:
                relations.append((a, b))
    return Poset(divisors, relations)

def product_poset(P: Poset, Q: Poset) -> Poset:
    """Coordinate-wise product ``P x Q``: ``(p,q) <= (p',q')`` iff
    ``p <= p'`` in ``P`` and ``q <= q'`` in ``Q``."""
    elements: List[Tuple[Element, Element]] = [
        (p, q) for p in P.elements for q in Q.elements
    ]
    relations: List[Tuple[Tuple, Tuple]] = []
    for (p1, q1) in elements:
        for (p2, q2) in elements:
            if (p1, q1) == (p2, q2):
                continue
            if P.le(p1, p2) and Q.le(q1, q2):
                relations.append(((p1, q1), (p2, q2)))
    return Poset(elements, relations)

def dual_poset(P: Poset) -> Poset:
    """The opposite poset ``P^op``: same underlying set, reversed
    order."""
    relations = [(b, a) for (a, b) in P.cover_relations()]
    return Poset(list(P.elements), relations)

def _check(self, a: Element, b: Element) -> None:
    if a not in self._element_set:
        raise KeyError(f"unknown element: {a!r}")
    if b not in self._element_set:
        raise KeyError(f"unknown element: {b!r}")

def lt(self, a: Element, b: Element) -> bool:
    """``a < b`` in the poset (strict)."""
    return a != b and self.le(a, b)

def cover_relations(self) -> List[Tuple[Element, Element]]:
    """All pairs ``(a, b)`` such that ``a < b`` with no ``c`` strictly
    between them.

    Returns
    -------
    list[tuple[Element, Element]]
        The cover relations of the poset.
    """
    if self._covers is not None:
        return list(self._covers)
    covers: List[Tuple[Element, Element]] = []
    for a in self.elements:
        for b in self.elements:
            if not self.lt(a, b):
                continue
            # b covers a iff there is no c strictly between
            between = False
            for c in self.elements:
                if c == a or c == b:
                    continue
                if self.lt(a, c) and self.lt(c, b):
                    between = True
                    break
            if not between:
                covers.append((a, b))
    self._covers = covers
    return list(covers)

def hasse_diagram(self) -> dict:
    """Hasse diagram as adjacency dict ``{a: [b1, b2, ...]}``
    listing the upper covers of each element."""
    adj: dict = {a: [] for a in self.elements}
    for a, b in self.cover_relations():
        adj[a].append(b)
    return adj

def principal_order_ideal(self, a: Element) -> Set[Element]:
    """``{x : x <= a}``."""
    self._check(a, a)
    return {x for x in self.elements if self.le(x, a)}

def principal_order_filter(self, a: Element) -> Set[Element]:
    """``{x : x >= a}``."""
    self._check(a, a)
    return {x for x in self.elements if self.le(a, x)}

def interval(self, a: Element, b: Element) -> Set[Element]:
    """``[a, b] = {x : a <= x <= b}``."""
    self._check(a, b)
    return {
        x for x in self.elements if self.le(a, x) and self.le(x, b)
    }

def chain(self, elts: Sequence[Element]) -> bool:
    """``True`` iff ``elts`` are pairwise comparable."""
    for x in elts:
        self._check(x, x)
    for i, x in enumerate(elts):
        for y in elts[i + 1:]:
            if not (self.le(x, y) or self.le(y, x)):
                return False
    return True

def antichain(self, elts: Sequence[Element]) -> bool:
    """``True`` iff ``elts`` are pairwise incomparable."""
    for x in elts:
        self._check(x, x)
    for i, x in enumerate(elts):
        for y in elts[i + 1:]:
            if x == y:
                return False
            if self.le(x, y) or self.le(y, x):
                return False
    return True

def _dag_for_linear_extension(self) -> nx.DiGraph:
    G = nx.DiGraph()
    G.add_nodes_from(self.elements)
    for a, b in self.cover_relations():
        G.add_edge(a, b)
    return G

def linear_extensions(self) -> List[List[Element]]:
    """All linear extensions of the poset."""
    if not self.elements:
        return [[]]
    G = self._dag_for_linear_extension()
    return [list(t) for t in nx.algorithms.dag.all_topological_sorts(G)]

def num_linear_extensions(self) -> int:
    """Number of linear extensions."""
    if not self.elements:
        return 1
    # Counting topological sorts is #P-hard in general but the
    # poset sizes shipped here are tiny.
    return sum(1 for _ in nx.algorithms.dag.all_topological_sorts(
        self._dag_for_linear_extension()
    ))

def zeta(self, a: Element, b: Element) -> int:
    """Zeta function: 1 if ``a <= b`` else 0."""
    return 1 if self.le(a, b) else 0

def _mobius_cached(self, a: Element, b: Element) -> int:
    if a == b:
        return 1
    if not self.le(a, b):
        return 0
    total = 0
    for c in self.interval(a, b):
        if c == b:
            continue
        total += self._mobius_cached(a, c)
    return -total

def join(self, a: Element, b: Element) -> Optional[Element]:
    """``a v b`` (least upper bound) or ``None`` if it does not
    exist or is not unique."""
    self._check(a, b)
    upper = [
        x for x in self.elements if self.le(a, x) and self.le(b, x)
    ]
    if not upper:
        return None
    # Find a minimum among the upper bounds (one that is <= every
    # other upper bound).
    for u in upper:
        if all(self.le(u, v) for v in upper):
            return u
    return None

def meet(self, a: Element, b: Element) -> Optional[Element]:
    """``a ^ b`` (greatest lower bound) or ``None``."""
    self._check(a, b)
    lower = [
        x for x in self.elements if self.le(x, a) and self.le(x, b)
    ]
    if not lower:
        return None
    for u in lower:
        if all(self.le(v, u) for v in lower):
            return u
    return None

def is_lattice(self) -> bool:
    """``True`` iff every pair has a join and a meet."""
    for a in self.elements:
        for b in self.elements:
            if self.join(a, b) is None:
                return False
            if self.meet(a, b) is None:
                return False
    return True

def is_distributive(self) -> bool:
    """``True`` iff the poset is a lattice satisfying the
    distributive law ``a ^ (b v c) = (a ^ b) v (a ^ c)``."""
    if not self.is_lattice():
        return False
    for a in self.elements:
        for b in self.elements:
            for c in self.elements:
                bc = self.join(b, c)
                ab = self.meet(a, b)
                ac = self.meet(a, c)
                lhs = self.meet(a, bc)
                rhs = self.join(ab, ac)
                if lhs != rhs:
                    return False
    return True

def is_isomorphic_to(self, other: "Poset") -> bool:
    """``True`` iff there is an order-preserving bijection
    between ``self`` and ``other``."""
    if len(self.elements) != len(other.elements):
        return False
    # Use networkx digraph isomorphism on cover-relation DAGs.
    G = nx.DiGraph()
    H = nx.DiGraph()
    G.add_nodes_from(self.elements)
    H.add_nodes_from(other.elements)
    for a, b in self.cover_relations():
        G.add_edge(a, b)
    for a, b in other.cover_relations():
        H.add_edge(a, b)
    return nx.is_isomorphic(G, H)

def __repr__(self) -> str:
    return (
        f"Poset(|elements|={len(self.elements)}, "
        f"|covers|={len(self.cover_relations())})"
    )

def _dilog_probe(size: int):
    # size is irrelevant for scalar dilog beyond mpmath's internal series;
    # vary the argument's distance from singularity instead.
    z = 1.0 - 1.0 / size if size > 1 else 0.5
    return [z], {}

def _lehmer_poly(n: int) -> List[int]:
    # Reciprocal polynomial of degree n; pads Lehmer's classic to n.
    base = [1, 1, 0, -1, -1, -1, -1, -1, 0, 1, 1]
    if n <= len(base):
        return base[:n + 1] if n + 1 <= len(base) else base
    pad = (n + 1 - len(base)) // 2
    return [1] * pad + base + [1] * (n + 1 - len(base) - pad)

def _hnf_matrix(n: int) -> List[List[int]]:
    # Construct a small invertible integer matrix sized n x n.
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        M[i][i] = i + 2
        if i + 1 < n:
            M[i][i + 1] = 1
        if i > 0:
            M[i][i - 1] = -1
    return M

def _resolve_callable(ref: str) -> Callable:
    """Resolve ``module:qualname`` into a callable (mirrors arsenal_meta)."""
    if ":" not in ref:
        raise ValueError(f"bad ref {ref!r}")
    modpath, qualname = ref.split(":", 1)
    mod = importlib.import_module(modpath)
    obj: Any = mod
    for part in qualname.split("."):
        obj = getattr(obj, part)
    if not callable(obj):
        raise TypeError(f"{ref!r} resolves to non-callable")
    return obj

