def predict_us(calibrated_cost: Dict[str, Any], size: int) -> float:
    """Predict op cost in microseconds at a given input size, using the
    structured ``calibrated_cost`` payload. Returns 0.0 if the payload is
    malformed or absent.
    """
    if not calibrated_cost:
        return 0.0
    cls = calibrated_cost.get("complexity", "unknown")
    coef = float(calibrated_cost.get("coefficient_us", 0.0))
    if size <= 0 or coef <= 0:
        return coef
    if cls == "O(1)":
        return coef
    if cls == "O(log n)":
        return coef * (1.0 + math.log(max(size, 1)))
    if cls == "O(n)":
        return coef * size
    if cls == "O(n log n)":
        return coef * size * (1.0 + math.log(max(size, 1)))
    if cls == "O(n^2)":
        return coef * size * size
    if cls == "O(n^3)":
        return coef * size * size * size
    if cls == "O(2^n)":
        return coef * (2.0 ** min(size, 30))  # cap to avoid overflow
    return coef

def canonical_hash_corpus(
    inputs: Sequence[CanonicalHashInput],
) -> Dict[str, str]:
    """Compute canonical hashes for a corpus of records, keyed by each
    record's ``candidate_hash`` field. Used to produce the local report
    that gets compared against the remote machine's report.
    """
    out: Dict[str, str] = {}
    for inp in inputs:
        out[inp.kill_record.candidate_hash] = canonical_hash(inp)
    return out

