def welch_t_test_one_sided(a: np.ndarray, b: np.ndarray) -> float:
    if len(a) < 2 or len(b) < 2:
        return float("nan")
    ma, mb = float(np.mean(a)), float(np.mean(b))
    va, vb = float(np.var(a, ddof=1)), float(np.var(b, ddof=1))
    na, nb = len(a), len(b)
    if (va / na + vb / nb) <= 0:
        return 0.0 if ma > mb else 1.0
    se = math.sqrt(va / na + vb / nb)
    t = (ma - mb) / se
    df = (
        (va / na + vb / nb) ** 2
        / ((va / na) ** 2 / (na - 1) + (vb / nb) ** 2 / (nb - 1))
    )
    try:
        from scipy.stats import t as student_t
        return float(1.0 - student_t.cdf(t, df=df))
    except Exception:
        return float(0.5 * (1.0 - math.erf(t / math.sqrt(2.0))))

def _pm_root() -> Path:
    """Return the directory that contains prometheus_math/ (i.e. repo root)."""
    return Path(__file__).resolve().parent.parent

def _pm_module_path(modname: str) -> Path:
    """Return the source file for ``prometheus_math.<modname>``.

    Raises FileNotFoundError if the module file does not exist.
    """
    if not modname or not isinstance(modname, str):
        raise ValueError(f"modname must be a non-empty string, got {modname!r}")
    candidate = _pm_root() / "prometheus_math" / f"{modname}.py"
    if not candidate.exists():
        # try as a package
        package = _pm_root() / "prometheus_math" / modname / "__init__.py"
        if package.exists():
            return package
        raise FileNotFoundError(
            f"prometheus_math.{modname} not found at {candidate}"
        )
    return candidate

def _ast_imports(source: str) -> list[tuple[str, list[str]]]:
    """Parse ``source`` and return (module, imported_names) pairs.

    For ``import a.b`` -> ('a.b', []).
    For ``from a.b import c, d`` -> ('a.b', ['c', 'd']).
    """
    tree = ast.parse(source)
    out: list[tuple[str, list[str]]] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                out.append((alias.name, []))
        elif isinstance(node, ast.ImportFrom):
            if node.module is None:
                continue
            names = [alias.name for alias in node.names]
            out.append((node.module, names))
    return out

def _techne_op_to_pm_module() -> dict[str, str]:
    """Map each techne.lib op-name -> the pm.<module> that owns it.

    Built by scanning every PM categorical module's import graph. If two
    PM modules pull from the same op, the first one wins (the name is
    canonical to its first export site).
    """
    mapping: dict[str, str] = {}
    for cat in PM_CATEGORIES:
        try:
            ops = _imported_techne_ops(cat)
        except (FileNotFoundError, OSError, SyntaxError):
            continue
        for op in ops:
            mapping.setdefault(op, cat)
    return mapping

def operation_dependencies(category: str, op_name: str) -> set[str]:
    """Approximate per-operation dependencies.

    Walks the source file of the techne.lib op (if it exists) and
    extracts the names of other PM-known operations called inside the
    function body of ``op_name``. Match-by-name within scope.

    Returns the set of PM op names referenced.

    Parameters
    ----------
    category : str
        PM categorical module (e.g. "elliptic_curves"). Used only as
        a sanity-check that the op belongs to that category.
    op_name : str
        Name of the operation (e.g. "analytic_sha").

    Notes
    -----
    Approximate: a name match within the function body counts as a
    dependency, even if it's a local binding shadowing a PM op. The
    bonus signal is fine for the graph; for hard correctness use
    ``module_imports``.
    """
    if not category or not op_name:
        raise ValueError("category and op_name must be non-empty strings")
    if category not in PM_CATEGORIES:
        # Soft-fail: still try to resolve, but warn caller via empty result
        pass
    op_path = _techne_lib_path(op_name)
    if op_path is None:
        return set()
    src = op_path.read_text(encoding="utf-8")

    # Collect known PM op names from every category's __all__
    known_ops: set[str] = set()
    for cat in PM_CATEGORIES:
        try:
            mod = importlib.import_module(f"prometheus_math.{cat}")
            for name in getattr(mod, "__all__", []) or []:
                known_ops.add(name)
        except Exception:
            continue

    tree = ast.parse(src)

    # Build module-level alias map: local_name -> pm_op_name. Catches
    # `from .regulator import regulator as _regulator` (alias _regulator
    # tracks back to the pm op `regulator`).
    alias_map: dict[str, str] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            mod = node.module or ""
            for alias in node.names:
                bound_name = alias.asname or alias.name
                # Two flavours:
                #   from .regulator import regulator as _regulator
                #     -> mod=='regulator' (relative), alias.name='regulator'
                #     -> bound_name='_regulator'
                #   from techne.lib.regulator import regulator
                #     -> mod=='techne.lib.regulator'
                head = ""
                if node.level and node.level > 0 and mod:
                    head = mod.split(".", 1)[0]
                elif mod.startswith("techne.lib."):
                    head = mod[len("techne.lib."):].split(".", 1)[0]
                elif mod.startswith("prometheus_math."):
                    head = mod[len("prometheus_math."):].split(".", 1)[0]
                # Both the imported name and the head module name are
                # candidate PM op names.
                for cand in (alias.name, head):
                    if cand and cand in known_ops:
                        alias_map[bound_name] = cand
                        break

    deps: set[str] = set()
    for node in ast.walk(tree):
        if not isinstance(node, ast.FunctionDef):
            continue
        if node.name != op_name:
            continue
        # Walk inside this function's body
        for sub in ast.walk(node):
            if isinstance(sub, ast.Name):
                if sub.id in known_ops and sub.id != op_name:
                    deps.add(sub.id)
                elif sub.id in alias_map and alias_map[sub.id] != op_name:
                    deps.add(alias_map[sub.id])
            elif isinstance(sub, ast.Attribute) and isinstance(sub.attr, str):
                if sub.attr in known_ops and sub.attr != op_name:
                    deps.add(sub.attr)
        break
    return deps

def build_dependency_graph() -> dict[str, set[str]]:
    """Return ``{pm_module: set_of_pm_modules_it_depends_on}``.

    The keys are exactly ``PM_CATEGORIES``. Modules with no detectable
    dependencies map to an empty set. Self-loops are not produced.
    """
    graph: dict[str, set[str]] = {}
    for cat in PM_CATEGORIES:
        try:
            graph[cat] = module_imports(cat)
        except FileNotFoundError:
            graph[cat] = set()
    return graph

def to_dot(graph: dict[str, set[str]]) -> str:
    """Render ``graph`` in Graphviz DOT format."""
    lines = ["digraph prometheus_math {", "  rankdir=LR;"]
    for n in sorted(graph.keys()):
        lines.append(f'  "{n}";')
    for src in sorted(graph.keys()):
        for dst in sorted(graph.get(src, ())):
            lines.append(f'  "{src}" -> "{dst}";')
    lines.append("}")
    return "\n".join(lines)

def cycle_detection(graph: dict[str, set[str]]) -> list[list[str]]:
    """Return a list of cycles in ``graph``. Empty list iff acyclic.

    Uses Tarjan's strongly-connected-components algorithm. Each SCC of
    size > 1 is reported as a single cycle (the nodes of the SCC, sorted).
    Self-loops (size-1 SCCs with a self-edge) are also reported.
    """
    # Tarjan's SCC
    index_counter = [0]
    stack: list[str] = []
    on_stack: set[str] = set()
    indices: dict[str, int] = {}
    lowlinks: dict[str, int] = {}
    sccs: list[list[str]] = []

    def strongconnect(v: str) -> None:
        indices[v] = index_counter[0]
        lowlinks[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack.add(v)
        for w in graph.get(v, ()):
            if w not in indices:
                strongconnect(w)
                lowlinks[v] = min(lowlinks[v], lowlinks[w])
            elif w in on_stack:
                lowlinks[v] = min(lowlinks[v], indices[w])
        if lowlinks[v] == indices[v]:
            comp: list[str] = []
            while True:
                w = stack.pop()
                on_stack.discard(w)
                comp.append(w)
                if w == v:
                    break
            sccs.append(comp)

    for v in graph:
        if v not in indices:
            strongconnect(v)

    cycles: list[list[str]] = []
    for comp in sccs:
        if len(comp) > 1:
            cycles.append(sorted(comp))
        elif len(comp) == 1:
            v = comp[0]
            if v in graph.get(v, set()):
                cycles.append([v])
    return cycles

def composition_opportunities(
    graph: dict[str, set[str]] | None = None,
) -> list[tuple[str, str]]:
    """Pairs of PM modules that aren't yet composed but plausibly could be.

    Heuristic: a pair (A, B) is reported when:
      - A and B are in PM_CATEGORIES,
      - neither A->B nor B->A is in the graph,
      - A != B,
      - and at least one is in the "Tier 1" mathematical core
        (number_theory / elliptic_curves / number_fields / topology).

    Output is sorted lexicographically by (A, B).
    """
    if graph is None:
        graph = build_dependency_graph()
    core = {"number_theory", "elliptic_curves", "number_fields", "topology"}
    pairs: list[tuple[str, str]] = []
    cats = sorted(PM_CATEGORIES)
    for i, a in enumerate(cats):
        for b in cats[i + 1:]:
            if a == b:
                continue
            if b in graph.get(a, set()):
                continue
            if a in graph.get(b, set()):
                continue
            if a in core or b in core:
                pairs.append((a, b))
    return pairs

def strongconnect(v: str) -> None:
    indices[v] = index_counter[0]
    lowlinks[v] = index_counter[0]
    index_counter[0] += 1
    stack.append(v)
    on_stack.add(v)
    for w in graph.get(v, ()):
        if w not in indices:
            strongconnect(w)
            lowlinks[v] = min(lowlinks[v], lowlinks[w])
        elif w in on_stack:
            lowlinks[v] = min(lowlinks[v], indices[w])
    if lowlinks[v] == indices[v]:
        comp: list[str] = []
        while True:
            w = stack.pop()
            on_stack.discard(w)
            comp.append(w)
            if w == v:
                break
        sccs.append(comp)

def _compute_reward_shaped(m_value: float) -> Tuple[float, str]:
    """Continuous reward variant: smooth gradient toward low M.

    Reward = max(0, 50 * (5 - M) / 4) for M in [1.001, 5];
    plus a +50 bonus if M in (1.001, 1.18) (sub-Lehmer);
    cyclotomics (M ≈ 1) still score 0 (sparse anchor).

    The continuous gradient gives the agent a learning signal across
    the entire M-range, not just at band boundaries. This addresses
    the local-optimum trap that the step-reward shape produces.
    """
    if not math.isfinite(m_value):
        return 0.0, "non_finite"
    if m_value < 1.0 - 1e-9:
        return 0.0, "numerical_artifact"
    if m_value < 1.001:
        return 0.0, "cyclotomic"  # sparse anchor stays
    if m_value < 1.18:
        # Sub-Lehmer: large bonus on top of continuous gradient.
        return 50.0 + 50.0 * (5.0 - m_value) / 4.0, "sub_lehmer"
    if m_value < 5.0:
        return 50.0 * (5.0 - m_value) / 4.0, "shaped_continuous"
    return 0.0, "large_m"

def _is_reciprocal(coeffs: List[int]) -> bool:
    """Palindromic check.  Trivially true for our generator output, but
    kept for downstream auditing (a future env variant might allow
    non-palindromic actions)."""
    n = len(coeffs)
    return all(coeffs[i] == coeffs[n - 1 - i] for i in range(n // 2))

def _check_mossinghoff(
    coeffs: List[int], m_value: float
) -> Tuple[Optional[bool], Optional[str]]:
    """Return (is_known, label).  ``is_known=True`` if the polynomial
    matches a Mossinghoff entry by Mahler measure within 1e-5; ``False``
    if it doesn't; ``None`` if the snapshot is unavailable."""
    try:
        from prometheus_math.databases import mahler as _mahler_db
    except Exception:
        return None, None
    # Mossinghoff snapshot is keyed by M-value; do a tolerance check.
    snapshot = getattr(_mahler_db, "MAHLER_TABLE", None)
    if snapshot is None:
        return None, None
    for entry in snapshot:
        try:
            entry_m = float(entry.get("mahler_measure", float("inf")))
        except (TypeError, ValueError):
            continue
        if abs(entry_m - m_value) < 1e-5:
            return True, entry.get("label") or entry.get("name") or "unknown"
    return False, None

def discoveries(self) -> List[EpisodeRecord]:
    """Return all rewarded episodes (sub-Lehmer + Salem cluster)."""
    return list(self._discoveries)

def pipeline_records(self) -> List[Any]:
    """Return all DiscoveryRecord results from the discovery pipeline.

    Empty if enable_pipeline=False or no DISCOVERY_CANDIDATE fired.
    """
    return list(self._pipeline_records)

def sub_lehmer_candidates(self) -> List[EpisodeRecord]:
    """Return only sub-Lehmer-candidate episodes that are NOT in the
    Mossinghoff snapshot.  Each one is a hand-verification target."""
    return list(self._sub_lehmer_candidates)

def known_salem_hits(self) -> int:
    """How many episodes hit a polynomial already in Mossinghoff."""
    return self._known_salem_hits

def _mutate_two_coefs(
    half: List[int], rng: np.random.Generator, alphabet: Tuple[int, ...]
) -> List[int]:
    """Flip two half-coefficients independently."""
    out = _mutate_single_coef(half, rng, alphabet)
    return _mutate_single_coef(out, rng, alphabet)

def _swap_palindromic_pairs(
    half: List[int], rng: np.random.Generator, alphabet: Tuple[int, ...]
) -> List[int]:
    """Swap two half-coefficients (the mirrored pair swaps automatically)."""
    out = list(half)
    if len(out) < 2:
        return out
    i, j = rng.choice(len(out), size=2, replace=False)
    out[int(i)], out[int(j)] = out[int(j)], out[int(i)]
    return out

def _zero_at_index(
    half: List[int], rng: np.random.Generator, alphabet: Tuple[int, ...]
) -> List[int]:
    """Set one half-coefficient to 0."""
    out = list(half)
    if not out:
        return out
    idx = int(rng.integers(0, len(out)))
    out[idx] = 0
    return out

def _identity(
    half: List[int], rng: np.random.Generator, alphabet: Tuple[int, ...]
) -> List[int]:
    """No-op (used when mutation_rate == 0; documents the agent state).

    Returns an exact copy.  Useful as a property anchor: agent that
    only ever picks identity gets identity reward (0 improvement).
    """
    return list(half)

def _half_centroid(population: List["PopulationMember"]) -> np.ndarray:
    """Centroid of the half-coefficient space (NaN-safe; returns zeros on empty)."""
    if not population:
        return np.zeros(0, dtype=np.float64)
    arr = np.asarray([m.half for m in population], dtype=np.float64)
    return arr.mean(axis=0)

def _half_distance_to_centroid(
    half: List[int], centroid: np.ndarray
) -> float:
    """Euclidean distance from a half-vector to a centroid; 0 if centroid empty."""
    if centroid.size == 0:
        return 0.0
    v = np.asarray(half, dtype=np.float64)
    if v.shape != centroid.shape:
        return 0.0
    return float(np.linalg.norm(v - centroid))

def _population_m_variance(population: List["PopulationMember"]) -> float:
    """Variance of finite M values in the population.  Inf if all members
    are non-finite (degenerate case) so the collapse-trigger does NOT
    treat all-inf as collapsed."""
    ms = [m.m_value for m in population if math.isfinite(m.m_value)]
    if len(ms) < 2:
        return float("inf")
    return float(np.var(ms))

def _is_reciprocal(coeffs: List[int]) -> bool:
    n = len(coeffs)
    return all(coeffs[i] == coeffs[n - 1 - i] for i in range(n // 2))

def _evaluate_m(self, member: PopulationMember) -> float:
    """EVAL the Mahler measure of a member through the substrate."""
    if self._kernel is None or self._ext is None:
        raise RuntimeError("env not reset; cannot eval")
    full = member.full(self.degree)
    if all(c == 0 for c in full):
        return float("inf")
    cap = self._kernel.mint_capability("EvalCap")
    try:
        ev = self._ext.EVAL(
            binding_name=self._mm_binding_name,
            binding_version=self._mm_binding_version,
            args=[full],
            cap=cap,
            eval_version=self._n_evals + 1,
        )
        self._n_evals += 1
    except BudgetExceeded:
        return float("inf")
    if not ev.success:
        return float("inf")
    try:
        return float(ev.output_repr)
    except (TypeError, ValueError):
        return float("inf")

def _maybe_replace_worst(self, child: PopulationMember) -> Dict[str, Any]:
    """Strategy-dispatched replacement.  Returns a per-step diagnostic
    dict (always populated) so callers can inspect the decision."""
    strat = self.selection_strategy
    if strat == "elitist":
        return self._select_elitist(child)
    if strat == "tournament_novelty":
        return self._select_tournament_novelty(child)
    if strat == "crowding":
        return self._select_crowding(child)
    if strat == "restart_collapse":
        return self._select_restart_collapse(child)
    # Defensive — constructor validated; reraising would be more
    # informative than silently falling back.
    raise RuntimeError(
        f"unknown selection_strategy at runtime: {strat!r}"
    )

def _select_elitist(self, child: PopulationMember) -> Dict[str, Any]:
    """Original V2 rule: child displaces worst iff child.M < worst.M."""
    if not self._population:
        self._population.append(child)
        return {"strategy": "elitist", "replaced": True, "reason": "empty_pop"}
    worst = self._population[-1]
    if math.isfinite(child.m_value) and child.m_value < worst.m_value:
        self._population[-1] = child
        return {
            "strategy": "elitist",
            "replaced": True,
            "reason": "child_better_than_worst",
        }
    return {
        "strategy": "elitist",
        "replaced": False,
        "reason": "child_not_better",
    }

def _trigger_restart_half(self) -> None:
    """Randomly reinitialize half the population (rounded down).
    The elite half is preserved (population is sorted ascending by
    M), so the best polys we've found are kept while the bottom
    half gets reseeded."""
    if self._rng is None or not self._population:
        return
    n = len(self._population)
    k = max(1, n // 2)
    # Sort first so we keep the elite half.
    self._sort_population()
    for j in range(n - k, n):
        new_half = [
            int(self.coefficient_choices[
                int(self._rng.integers(0, len(self.coefficient_choices)))
            ])
            for _ in range(self.half_len)
        ]
        new_member = PopulationMember(half=new_half)
        new_member.m_value = self._evaluate_m(new_member)
        self._population[j] = new_member
    self._restart_count += 1
    self._strategy_event_log.append(
        {
            "event": "restart_half",
            "step": self._step_count,
            "restart_count": self._restart_count,
            "members_replaced": k,
        }
    )

def _sort_population(self) -> None:
    """Keep population sorted ascending by M (population[0] = elite)."""
    self._population.sort(key=lambda m: m.m_value)

def population_snapshot(self) -> List[Tuple[List[int], float]]:
    """Return a copy of the current population as (half, M) tuples."""
    return [(list(m.half), float(m.m_value)) for m in self._population]

def population_diversity(self) -> Dict[str, float]:
    """Diagnostic: variance of M values + mean pairwise half-vector
    distance + cyclotomic fraction.  Used by the anti-elitist
    comparison harness to monitor mode-collapse."""
    if not self._population:
        return {
            "m_variance": float("inf"),
            "mean_pairwise_dist": 0.0,
            "cyclotomic_fraction": 0.0,
            "n_members": 0,
        }
    ms = [m.m_value for m in self._population if math.isfinite(m.m_value)]
    m_var = float(np.var(ms)) if len(ms) >= 2 else float("inf")
    # Mean pairwise distance in half-coefficient space.
    halves = np.asarray(
        [m.half for m in self._population], dtype=np.float64
    )
    n = len(halves)
    if n >= 2:
        d = 0.0
        cnt = 0
        for i in range(n):
            for j in range(i + 1, n):
                d += float(np.linalg.norm(halves[i] - halves[j]))
                cnt += 1
        mean_d = d / cnt if cnt else 0.0
    else:
        mean_d = 0.0
    # Cyclotomic fraction: members with M = 1.0 ± 1e-9.
    cyclo = sum(
        1
        for m in self._population
        if math.isfinite(m.m_value) and abs(m.m_value - 1.0) < 1e-9
    )
    return {
        "m_variance": float(m_var) if math.isfinite(m_var) else float("inf"),
        "mean_pairwise_dist": float(mean_d),
        "cyclotomic_fraction": float(cyclo) / float(n),
        "n_members": int(n),
    }

def restart_count(self) -> int:
    """How many times restart-on-collapse fired in this env's lifetime."""
    return int(self._restart_count)

def strategy_event_log(self) -> List[Dict[str, Any]]:
    """Copy of the strategy event log (restart events, etc.)."""
    return list(self._strategy_event_log)

def _crowding(values: np.ndarray) -> np.ndarray:
    order = np.argsort(values)
    cd = np.zeros_like(values)
    rng_v = float(values[order[-1]] - values[order[0]])
    if rng_v <= 0.0:
        return cd
    cd[order[0]] = float("inf")
    cd[order[-1]] = float("inf")
    for k in range(1, len(values) - 1):
        cd[order[k]] = (
            float(values[order[k + 1]] - values[order[k - 1]]) / rng_v
        )
    return cd

def _config_to_coeffs_real(cfg: RootConfig) -> np.ndarray:
    """RootConfig -> real coefficient vector (ascending power order, to
    match the V1/V2 convention used elsewhere in prometheus_math)."""
    roots = _config_to_root_multiset(cfg)
    desc = _expand_roots_to_real_coeffs(roots)
    return np.asarray(list(desc[::-1]), dtype=np.float64)

def degree(self) -> int:
    d = 2 * len(self.unit_thetas)
    if self.salem_pair is not None:
        d += 4
    if self.real_pair_rho is not None:
        d += 2
    return d

def run_pilot(
    self, n_samples: int, log_every: int = 1000
) -> Dict[str, Any]:
    """Run a pilot of ``n_samples`` direct samples.  Returns a
    summary dict suitable for the results doc."""
    if self._rng is None:
        self.reset()
    n_integer = 0
    n_sub_lehmer = 0
    n_signal = 0
    m_values: List[float] = []
    for i in range(n_samples):
        rec = self.sample_one()
        if rec.coeffs_int is not None:
            n_integer += 1
            if math.isfinite(rec.mahler_measure):
                m_values.append(rec.mahler_measure)
        if rec.is_sub_lehmer:
            n_sub_lehmer += 1
        if rec.is_signal_class:
            n_signal += 1
    return {
        "n_samples": n_samples,
        "n_integer_coeffs": n_integer,
        "n_sub_lehmer": n_sub_lehmer,
        "n_signal_class": n_signal,
        "fraction_integer": n_integer / max(1, n_samples),
        "best_m_overall": self._best_m_overall,
        "m_distribution_summary": (
            {
                "min": float(min(m_values)) if m_values else None,
                "median": float(np.median(m_values)) if m_values else None,
                "max": float(max(m_values)) if m_values else None,
            }
        ),
    }

def _evaluate_m(self, coeffs_int: List[int]) -> float:
    if self._kernel is None or self._ext is None:
        raise RuntimeError("env not reset; cannot eval")
    if all(c == 0 for c in coeffs_int):
        return float("inf")
    cap = self._kernel.mint_capability("EvalCap")
    try:
        ev = self._ext.EVAL(
            binding_name=self._mm_binding_name,
            binding_version=self._mm_binding_version,
            args=[coeffs_int],
            cap=cap,
            eval_version=self._n_evals + 1,
        )
        self._n_evals += 1
    except BudgetExceeded:
        return float("inf")
    if not ev.success:
        return float("inf")
    try:
        return float(ev.output_repr)
    except (TypeError, ValueError):
        return float("inf")

def _is_reciprocal(coeffs: List[int]) -> bool:
    """Palindromic check. Trivial for env-generated polys; included so
    the pipeline catches any future env that loosens the constraint."""
    n = len(coeffs)
    return all(coeffs[i] == coeffs[n - 1 - i] for i in range(n // 2))

def _f6_base_rate(coeffs: List[int], m_value: float) -> Tuple[bool, str]:
    """F6 falsification: base-rate check.

    Trivial polys (all-equal-magnitude coefficients) yield Salem-band M
    by accident; F6 rejects them as base-rate hits. Real signal has
    non-trivial coefficient structure.
    """
    if all(c == 0 for c in coeffs):
        return False, "F6: zero polynomial"
    nz = [c for c in coeffs if c != 0]
    if not nz:
        return False, "F6: all-zero coefficients"
    # Count distinct nonzero coefficient values (signed). Lehmer has +1
    # and -1, giving 2 distinct values; Φ_5 has only +1 giving 1 distinct.
    distinct_values = len(set(nz))
    if distinct_values < 2:
        return (
            False,
            f"F6: trivial coefficient structure ({distinct_values} distinct nonzero value)",
        )
    return True, f"F6: {distinct_values} distinct nonzero coefficient values"

def _f11_cross_validation(
    coeffs: List[int], m_value: float
) -> Tuple[bool, str]:
    """F11 falsification: cross-validation against an independent
    M-computation.

    MVP: re-compute M via two independent paths and check agreement.
    """
    try:
        from techne.lib.mahler_measure import mahler_measure as _mm

        v_a = float(_mm(coeffs))
        v_b = float(_mm(list(reversed(coeffs))))  # reciprocal: should give same M
        if not (math.isfinite(v_a) and math.isfinite(v_b)):
            return False, "F11: non-finite M in cross-val"
        if abs(v_a - v_b) > 1e-6:
            return False, f"F11: cross-val mismatch {v_a:.6f} vs {v_b:.6f}"
        if abs(v_a - m_value) > 1e-6:
            return False, f"F11: M drift {v_a:.6f} vs reported {m_value:.6f}"
        return True, f"F11: cross-val agrees within 1e-6 ({v_a:.6f})"
    except Exception as e:  # pragma: no cover
        return False, f"F11: error {type(e).__name__}: {e!r}"[:200]

def is_signal_class(self) -> bool:
    """True iff the candidate survived to PROMOTED or SHADOW_CATALOG."""
    return self.terminal_state in ("PROMOTED", "SHADOW_CATALOG")

def _candidate_hash(coeffs: List[int], m_value: float) -> str:
    blob = json.dumps(
        {"coeffs": list(coeffs), "M": float(m_value)},
        sort_keys=True,
    )
    return hashlib.sha256(blob.encode("utf-8")).hexdigest()

def list_shadow_catalog(self) -> List[Dict[str, Any]]:
    """Return all SHADOW_CATALOG entries currently in the substrate."""
    rows = self.kernel.conn.execute(
        "SELECT name, version, def_hash, def_blob, tier "
        "FROM symbols WHERE name LIKE ? ORDER BY created_at",
        ("discovery_candidate_%",),
    ).fetchall()
    out: List[Dict[str, Any]] = []
    for r in rows:
        try:
            blob = json.loads(r[3])
        except Exception:
            blob = {}
        out.append(
            {
                "name": r[0],
                "version": r[1],
                "def_hash": r[2],
                "tier": r[4],
                "blob": blob,
            }
        )
    return out

def _short_repr(v: Any, maxlen: int = 30) -> str:
    """Compact repr for hypothesis text. Truncates long strings/lists."""
    s = repr(v)
    if len(s) > maxlen:
        return s[: maxlen - 3] + "..."
    return s

def _enumerate_module(modname: str) -> list[tuple[str, str]]:
    """Return [(funcname, one-line summary), ...] for everything in module's __all__."""
    full = f"prometheus_math.{modname}"
    try:
        m = importlib.import_module(full)
    except Exception as e:
        return [("(import failed)", str(e))]
    names = getattr(m, "__all__", None) or [
        n for n in dir(m) if not n.startswith("_")
    ]
    out = []
    for name in names:
        obj = getattr(m, name, None)
        if obj is None:
            continue
        if not callable(obj):
            continue
        doc = (inspect.getdoc(obj) or "").splitlines()
        first = doc[0].strip() if doc else ""
        try:
            sig = str(inspect.signature(obj))
        except (TypeError, ValueError):
            sig = "(...)"
        out.append((f"{name}{sig}", first))
    return out

def installed_table() -> dict:
    """Return the raw `installed()` registry dict (caller-friendly summary)."""
    return installed()

def logistic_step(x: float, r: float) -> float:
    """f(x) = r x (1 - x).  Maps [0,1] -> [0,1] when r in [0,4]."""
    return r * x * (1.0 - x)

def logistic_derivative(x: float, r: float) -> float:
    """f'(x) = r (1 - 2x)."""
    return r * (1.0 - 2.0 * x)

def tent_step(x: float, _params=None) -> float:
    """Symmetric tent map on [0,1].

    f(x) = 2x          if x < 0.5
         = 2(1 - x)    otherwise.
    """
    return 2.0 * x if x < 0.5 else 2.0 * (1.0 - x)

def sine_step(x: float, r: float) -> float:
    """f(x) = r sin(pi x).  Conjugate to logistic on [0, 1]."""
    return r * math.sin(math.pi * x)

def sine_derivative(x: float, r: float) -> float:
    """f'(x) = r pi cos(pi x)."""
    return r * math.pi * math.cos(math.pi * x)

def _check_n_iter(n_iter: int, transient: int) -> None:
    if n_iter < 0:
        raise ValueError(f"n_iter must be >= 0, got {n_iter}")
    if transient < 0:
        raise ValueError(f"transient must be >= 0, got {transient}")

def _check_unit_interval(name: str, x: float) -> None:
    if not (0.0 <= x <= 1.0):
        raise ValueError(
            f"{name} must lie in [0, 1] for this map; got {x}"
        )

def _iterate_step(step: Callable[[float], float], x: float, k: int) -> float:
    """Apply ``step`` ``k`` times."""
    for _ in range(k):
        x = step(x)
    return x

def _validate_t_span(t_span):
    """Coerce ``t_span`` to (t0, t1) with t1 > t0; else ValueError."""
    if t_span is None:
        raise ValueError("t_span must be a (t0, t1) pair, got None")
    try:
        t_list = list(t_span)
    except TypeError as exc:
        raise ValueError(
            "t_span must be a 2-tuple of floats"
        ) from exc
    if len(t_list) != 2:
        raise ValueError(
            f"t_span must contain exactly two endpoints, got {len(t_list)}"
        )
    t0, t1 = float(t_list[0]), float(t_list[1])
    if not (t1 > t0):
        raise ValueError(
            f"t_span must satisfy t1 > t0; got t0={t0}, t1={t1}"
        )
    return t0, t1

def _validate_rhs_shape(rhs, t0, y0):
    """Call rhs once and check the output dimension matches y0."""
    y0_arr = np.asarray(y0, dtype=float).ravel()
    test = np.asarray(rhs(t0, y0_arr), dtype=float).ravel()
    if test.shape != y0_arr.shape:
        raise ValueError(
            f"rhs returned shape {test.shape} but y0 has shape "
            f"{y0_arr.shape}; dimensions must match"
        )
    return y0_arr

def dop853(
    rhs: Callable,
    t_span: Tuple[float, float],
    y0: Sequence[float],
    rtol: float = 1e-12,
    atol: float = 1e-15,
    prec: Optional[int] = None,
) -> dict:
    """8th-order Dormand-Prince adaptive integrator.

    Backed by scipy's DOP853 (a Python re-implementation of Hairer's
    Fortran code).  When ``prec`` is set, falls back to
    ``mpmath_odefun`` at that precision (mpmath uses Taylor methods,
    which are higher-order than DOP853 anyway).
    """
    if prec is not None:
        if not isinstance(prec, int) or prec <= 0:
            raise ValueError(f"prec must be a positive int, got {prec!r}")
        return solve_ivp(rhs, t_span, y0, prec=prec)
    return solve_ivp(rhs, t_span, y0, method="DOP853",
                     rtol=rtol, atol=atol)

def mpmath_odefun(
    rhs: Callable,
    t_span: Tuple[float, float],
    y0: Sequence[float],
    prec: int = 53,
    h: Optional[float] = None,
) -> Callable:
    """Return an arbitrary-precision callable ``f(t)`` solving
    dy/dt = rhs(t, y) on t_span starting from y0.  Backed by
    ``mpmath.mp.odefun`` (Taylor-series IVP solver, Bulirsch-Stoer-
    style internally).

    Parameters
    ----------
    rhs   : (t, y) -> dy/dt — should accept floats and return a list
    t_span: (t0, t1)
    y0    : initial state
    prec  : mantissa bits (mpmath ``mp.prec``); default 53
    h     : ignored (kept for API compatibility)

    Returns
    -------
    callable f: float -> tuple of mpf, defined on [t0, t1].
    """
    if not _HAS_MPMATH:  # pragma: no cover
        raise ImportError("mpmath is required for mpmath_odefun")
    if not isinstance(prec, int) or prec <= 0:
        raise ValueError(f"prec must be a positive int, got {prec!r}")
    t0, t1 = _validate_t_span(t_span)

    # Switch precision and KEEP it raised — odefun computes Taylor
    # coefficients lazily on each call.
    _mp.mp.prec = max(int(prec), _mp.mp.prec)
    y0_list = [_mp.mpf(v) for v in y0]
    n_dim = len(y0_list)

    if n_dim == 1:
        # mpmath odefun for a single equation: F(t, y) -> scalar.  y is
        # an mpf scalar.  We try calling rhs in mpf-native mode first
        # (so duck-typed expressions like ``-y`` retain full precision);
        # if that fails (rhs requires numpy/floats), we fall back to
        # float64 evaluation, which loses precision but still works.
        _mp_state = {"native": True}

        def F_scalar(t, y):
            if _mp_state["native"]:
                try:
                    out = rhs(t, y)
                    if hasattr(out, "__iter__") and not isinstance(out, str):
                        out = list(out)[0]
                    return _mp.mpf(out)
                except Exception:
                    _mp_state["native"] = False
            yarr = np.asarray([float(y)], dtype=float)
            out = rhs(float(t), yarr)
            try:
                v = float(out[0])
            except (TypeError, IndexError):
                v = float(out)
            return _mp.mpf(v)

        f_inner = _mp.odefun(F_scalar, _mp.mpf(t0), y0_list[0])

        def f(t):
            v = f_inner(_mp.mpf(t))
            return (v,)
        return f

    # Multi-equation: F(t, y) -> tuple/list of mpf, y is a tuple.
    _mp_state_v = {"native": True}

    def F_vec(t, y):
        if _mp_state_v["native"]:
            try:
                out = rhs(t, list(y))
                out_list = list(out) if hasattr(out, "__iter__") else [out]
                return [_mp.mpf(v) for v in out_list]
            except Exception:
                _mp_state_v["native"] = False
        yarr = np.asarray([float(v) for v in y], dtype=float)
        out = rhs(float(t), yarr)
        out_list = list(out) if hasattr(out, "__iter__") else [out]
        return [_mp.mpf(float(v)) for v in out_list]

    f_inner = _mp.odefun(F_vec, _mp.mpf(t0), y0_list)

    def f(t):
        v = f_inner(_mp.mpf(t))
        return tuple(v) if hasattr(v, "__iter__") else (v,)
    return f

def _grad(f, x, idx, eps=1e-7):
    """Central difference on f at x in coordinate idx."""
    x_p = list(x); x_p[idx] = x_p[idx] + eps
    x_m = list(x); x_m[idx] = x_m[idx] - eps
    return (f(x_p) - f(x_m)) / (2 * eps)

def F_vec(t, y):
    if _mp_state_v["native"]:
        try:
            out = rhs(t, list(y))
            out_list = list(out) if hasattr(out, "__iter__") else [out]
            return [_mp.mpf(v) for v in out_list]
        except Exception:
            _mp_state_v["native"] = False
    yarr = np.asarray([float(v) for v in y], dtype=float)
    out = rhs(float(t), yarr)
    out_list = list(out) if hasattr(out, "__iter__") else [out]
    return [_mp.mpf(float(v)) for v in out_list]

def f(t):
    v = f_inner(_mp.mpf(t))
    return tuple(v) if hasattr(v, "__iter__") else (v,)

def F_scalar(t, y):
    if _mp_state["native"]:
        try:
            out = rhs(t, y)
            if hasattr(out, "__iter__") and not isinstance(out, str):
                out = list(out)[0]
            return _mp.mpf(out)
        except Exception:
            _mp_state["native"] = False
    yarr = np.asarray([float(y)], dtype=float)
    out = rhs(float(t), yarr)
    try:
        v = float(out[0])
    except (TypeError, IndexError):
        v = float(out)
    return _mp.mpf(v)

def f(t):
    v = f_inner(_mp.mpf(t))
    return (v,)

def _build_distance_to_target(
    kill_vector: Optional[Any],
    target_band_name: str,
) -> DistanceToTarget:
    """Find the named target-band component in kill_vector and extract margin."""
    if kill_vector is None:
        return DistanceToTarget(value=None, unit=None)
    components = getattr(kill_vector, "components", None)
    if not components:
        return DistanceToTarget(value=None, unit=None)
    for c in components:
        if getattr(c, "falsifier_name", None) == target_band_name:
            margin = getattr(c, "margin", None)
            triggered = getattr(c, "triggered", False)
            # Convention: triggered (in band) → 0.0; not triggered (out of band) → margin
            value = 0.0 if triggered else (None if margin is None else float(margin))
            return DistanceToTarget(
                value=value,
                unit=getattr(c, "margin_unit", None),
                computed_at_dps=getattr(c, "precision_dps", None),
            )
    return DistanceToTarget(value=None, unit=None)

def _build_battery_survival_depth(kill_vector: Optional[Any]) -> BatterySurvivalDepth:
    if kill_vector is None:
        return BatterySurvivalDepth(n_passed=0, n_total=0)
    components = getattr(kill_vector, "components", None)
    if not components:
        return BatterySurvivalDepth(n_passed=0, n_total=0)
    passed: List[str] = []
    failed: List[str] = []
    for c in components:
        name = getattr(c, "falsifier_name", "?")
        if getattr(c, "triggered", False):
            failed.append(name)
        else:
            passed.append(name)
    return BatterySurvivalDepth(
        n_passed=len(passed),
        n_total=len(passed) + len(failed),
        falsifiers_passed=tuple(passed),
        falsifiers_failed=tuple(failed),
    )

def _build_verification_depth(
    *,
    precision_metadata: Optional[Mapping[str, Any]],
    methods_used: Sequence[str],
    stability_aggregate: Optional[Mapping[str, Any]],
    kill_vector: Optional[Any],
) -> VerificationDepth:
    # min_precision_dps from precision_metadata or aggregated from kill_vector
    min_dps: Optional[int] = None
    if precision_metadata and precision_metadata.get("dps") is not None:
        min_dps = int(precision_metadata["dps"])
    elif kill_vector is not None:
        components = getattr(kill_vector, "components", None) or ()
        dps_values = [
            getattr(c, "precision_dps", None)
            for c in components
            if getattr(c, "precision_dps", None) is not None
        ]
        if dps_values:
            min_dps = int(min(dps_values))

    # methods_used: prefer explicit param; fall back to kill_vector aggregation
    methods: Tuple[str, ...] = tuple(sorted(set(methods_used)))
    if not methods and kill_vector is not None:
        components = getattr(kill_vector, "components", None) or ()
        method_set = {
            str(getattr(c, "method", "unknown"))
            for c in components
            if getattr(c, "method", None)
        }
        methods = tuple(sorted(method_set))

    # convergence_summary
    if precision_metadata and precision_metadata.get("convergence"):
        conv_summary = str(precision_metadata["convergence"])
    elif kill_vector is not None:
        components = getattr(kill_vector, "components", None) or ()
        conv_set = {
            str(getattr(c, "convergence_status", "n/a"))
            for c in components
            if getattr(c, "convergence_status", None)
        }
        if not conv_set:
            conv_summary = "n/a"
        elif conv_set == {"converged"}:
            conv_summary = "all_converged"
        elif "failed_max_steps" in conv_set or "nan_returned" in conv_set:
            conv_summary = "some_failed" if "converged" in conv_set else "all_failed"
        else:
            conv_summary = "mixed"
    else:
        conv_summary = "n/a"

    return VerificationDepth(
        min_precision_dps=min_dps,
        methods_used=methods,
        convergence_summary=conv_summary,
        stability_aggregate=dict(stability_aggregate) if stability_aggregate else None,
    )

def _build_exclusion_distance(
    *,
    coordinate_chart_id: Optional[str],
    nearest_certificate_ref: Optional[str],
    value: Optional[float],
) -> ExclusionDistance:
    """Populated only when chart + cert + value all supplied. Otherwise
    NULL with an explanatory reason — anti-fake-topology.

    Order of checks: structural prerequisites first (chart + cert),
    then computed value. The reason_unpopulated message names the
    most-upstream missing piece so consumers know whether to wait for
    P0 / P4 / a real distance computation.
    """
    if coordinate_chart_id is None and nearest_certificate_ref is None:
        reason = (
            "no CoordinateChart registered for region AND no "
            "ExclusionCertificate available (P0 + P4 both not landed for this domain)"
        )
    elif coordinate_chart_id is None:
        reason = "no CoordinateChart registered for region (P0 not landed for this domain)"
    elif nearest_certificate_ref is None:
        reason = "no ExclusionCertificate registered nearby (P4 not landed)"
    elif value is None:
        reason = (
            "chart and certificate both registered but no exclusion distance "
            "value computed yet"
        )
    else:
        return ExclusionDistance(
            value=float(value),
            chart_id=coordinate_chart_id,
            nearest_certificate_ref=nearest_certificate_ref,
            metric_id="chart_native_metric",
        )

    return ExclusionDistance(
        value=None,
        chart_id=coordinate_chart_id,
        nearest_certificate_ref=nearest_certificate_ref,
        reason_unpopulated=reason,
    )

def _build_assumption_load(
    *,
    caveats: Sequence[str],
    precision_metadata: Optional[Mapping[str, Any]],
    methods_used: Sequence[str],
) -> AssumptionLoad:
    """Heuristic mapping from caveats / method / precision to assumption-load
    sub-dimensions. Each ∈ [0, 1]. Conservative defaults; tune as data
    accumulates.
    """
    cv = set(caveats or ())
    catalog_dep = 0.0
    if "catalog_completeness_partial" in cv or "catalog_lookup_only" in cv:
        catalog_dep = 0.7
    if any("catalog" in c.lower() for c in cv):
        catalog_dep = max(catalog_dep, 0.5)

    numeric_dep = 0.0
    if precision_metadata:
        dps = precision_metadata.get("dps")
        expected_min = precision_metadata.get("expected_min_dps")
        if dps is not None and expected_min is not None and dps < expected_min:
            numeric_dep = 0.8
        elif dps is not None and dps < 30:
            numeric_dep = 0.5
        elif "precision_below_expected" in cv:
            numeric_dep = max(numeric_dep, 0.6)

    heuristic_dep = 0.0
    if "heuristic" in str(methods_used).lower():
        heuristic_dep = 0.6
    if any("heuristic" in c.lower() for c in cv):
        heuristic_dep = max(heuristic_dep, 0.5)

    normalization_dep = 0.0
    if "canonicalization_undecidable" in cv or "canonical_form_choice" in cv:
        normalization_dep = 0.7
    if any("normaliz" in c.lower() or "canonical" in c.lower() for c in cv):
        normalization_dep = max(normalization_dep, 0.4)

    theorem_dep = 0.0
    # The KillVector +8 component `requires_unproven_conjecture` would
    # surface here once the kill_vector v2 lands; for now use caveat-text.
    if "requires_unproven_conjecture" in cv or "assumes_rh" in cv or "assumes_bsd" in cv:
        theorem_dep = 0.9

    return AssumptionLoad(
        catalog_dependence=catalog_dep,
        numeric_dependence=numeric_dep,
        heuristic_dependence=heuristic_dep,
        normalization_dependence=normalization_dep,
        theorem_import_dependence=theorem_dep,
    )

def survival_fraction(self) -> Optional[float]:
    if self.n_total == 0:
        return None
    return self.n_passed / self.n_total

def magnitude(self) -> float:
    """L2 over sub-dimensions. Higher = more assumption load."""
    return math.sqrt(
        self.catalog_dependence**2
        + self.numeric_dependence**2
        + self.heuristic_dependence**2
        + self.normalization_dependence**2
        + self.theorem_import_dependence**2
    )

def max_dimension(self) -> Tuple[str, float]:
    """Returns (name, value) of the highest sub-dimension."""
    items = [
        ("catalog_dependence", self.catalog_dependence),
        ("numeric_dependence", self.numeric_dependence),
        ("heuristic_dependence", self.heuristic_dependence),
        ("normalization_dependence", self.normalization_dependence),
        ("theorem_import_dependence", self.theorem_import_dependence),
    ]
    return max(items, key=lambda x: x[1])

def populated_axes(self) -> Tuple[str, ...]:
    """Names of axes whose primary value is not None.
    Useful for downstream filtering."""
    out: List[str] = []
    if self.distance_to_target.value is not None:
        out.append("distance_to_target")
    if self.battery_survival_depth.n_total > 0:
        out.append("battery_survival_depth")
    if self.verification_depth.min_precision_dps is not None or self.verification_depth.methods_used:
        out.append("verification_depth")
    if self.exclusion_distance.value is not None:
        out.append("exclusion_distance")
    if self.assumption_load.magnitude() > 0:
        out.append("assumption_load")
    if (
        self.computational_friction.elapsed_seconds is not None
        or self.computational_friction.oracle_calls is not None
    ):
        out.append("computational_friction")
    return tuple(out)

def has_metric_axes(self) -> Tuple[str, ...]:
    """Names of axes that are AxisType.METRIC AND populated. For
    consumers (e.g., ExclusionCertificate distance queries) that
    require a metric axis."""
    return tuple(
        name
        for name in self.populated_axes()
        if self.all_axis_types()[name] == AxisType.METRIC
    )

def reset(self, *, seed=None, options=None):
    obs, info = self._base.reset(seed=seed)
    return np.asarray(obs, dtype=np.float32), info

def step(self, action):
    obs, r, term, trunc, info = self._base.step(int(action))
    obs = np.asarray(obs, dtype=np.float32)
    if (term or trunc) and not self._stop:
        ep_idx = episodes_completed["value"]
        M = info.get("mahler_measure", float("inf"))
        M = float(M) if M is not None else float("inf")
        coeffs = info.get("coeffs_full") or [0] * (self._base.degree + 1)
        is_known = info.get("is_known_in_mossinghoff")

        margin = _band_margin(M)
        if margin is not None and math.isfinite(margin):
            margins.append(margin)
        else:
            # Use a large positive sentinel for non-finite (rare).
            margins.append(99.0)

        # Buckets.
        if margin is not None:
            if margin <= 0:
                counts["n_band_touch"] += 1
                if firsts["first_band_touch_episode"] is None:
                    firsts["first_band_touch_episode"] = ep_idx
                    firsts["first_band_touch_margin"] = float(margin)
            if margin < 0:
                counts["n_band_cross"] += 1
                if firsts["first_band_cross_episode"] is None:
                    firsts["first_band_cross_episode"] = ep_idx
                    firsts["first_band_cross_margin"] = float(margin)
        if M < 1.001:
            counts["n_cyclotomic"] += 1
        elif 1.001 < M < 1.18:
            counts["n_sub_lehmer"] += 1
            if firsts["first_sub_lehmer_episode"] is None:
                firsts["first_sub_lehmer_episode"] = ep_idx
                firsts["first_sub_lehmer_M"] = float(M)
        elif M >= 1.18:
            counts["n_above_band"] += 1

        # Capture all band touches as trajectory samples.
        if margin is not None and margin <= 0 and len(band_touch_samples) < 1000:
            band_touch_samples.append((ep_idx, float(margin), float(M)))

        # Mossinghoff cross-check + pipeline check.
        if 1.001 < M < 1.18:
            # Sub-Lehmer hit. is_known is the env's Mossinghoff
            # cross-check at the M level.
            if is_known:
                counts["n_known_in_mossinghoff"] += 1
            else:
                counts["n_novel_in_band"] += 1
                # Pull the pipeline record (this is the SAME
                # env we constructed; the pipeline ran when env
                # detected sub-Lehmer + not-known).
                recs = self._base.pipeline_records()
                rec = None
                if len(recs) > pipeline_len_holder["value"]:
                    rec = recs[-1]
                    pipeline_len_holder["value"] = len(recs)
                if rec is not None:
                    counts["n_pipeline_routed"] += 1
                    ts = getattr(rec, "terminal_state", None)
                    if ts == "PROMOTED":
                        counts["n_promoted"] += 1
                        if firsts["first_promote_episode"] is None:
                            firsts["first_promote_episode"] = ep_idx
                    elif ts == "SHADOW_CATALOG":
                        counts["n_shadow_catalog"] += 1
                        if firsts["first_shadow_catalog_episode"] is None:
                            firsts["first_shadow_catalog_episode"] = ep_idx
                    else:
                        counts["n_rejected_post_pipeline"] += 1
                    if len(novel_candidates) < 20:
                        novel_candidates.append({
                            "episode_idx": ep_idx,
                            "coeffs": list(coeffs),
                            "M": float(M),
                            "terminal_state": ts,
                            "kill_pattern": getattr(rec, "kill_pattern", None),
                            "candidate_hash": getattr(
                                rec, "candidate_hash", None
                            ),
                        })

        episodes_completed["value"] += 1
        if (
            progress_every > 0
            and episodes_completed["value"] >= progress_holder["next"]
        ):
            print(
                f"  [seed={seed}] {episodes_completed['value']}/{n_episodes} eps "
                f"| best={min(margins) if margins else float('nan'):.4f} "
                f"| band_touch={counts['n_band_touch']} "
                f"| sub_lehmer={counts['n_sub_lehmer']} "
                f"| novel={counts['n_novel_in_band']}",
                flush=True,
            )
            progress_holder["next"] += progress_every
        if episodes_completed["value"] >= self._n_max:
            self._stop = True
    return obs, float(r), bool(term), bool(trunc), info

def __init__(self, target):
    super().__init__()
    self._target = target

def _welch_t_test_one_sided(
    a: np.ndarray, b: np.ndarray
) -> float:
    """Welch one-sided t-test: H1 = mean(a) > mean(b).  Returns NaN if
    either array has < 2 samples (variance undefined)."""
    a = np.asarray(a, dtype=np.float64)
    b = np.asarray(b, dtype=np.float64)
    if a.size < 2 or b.size < 2:
        return float("nan")
    ma, mb = float(a.mean()), float(b.mean())
    va, vb = float(a.var(ddof=1)), float(b.var(ddof=1))
    se_sq = va / a.size + vb / b.size
    if se_sq <= 0.0:
        return 0.0 if ma > mb else 1.0
    se = math.sqrt(se_sq)
    t = (ma - mb) / se
    df = (
        se_sq ** 2
        / ((va / a.size) ** 2 / (a.size - 1) + (vb / b.size) ** 2 / (b.size - 1))
    )
    try:
        from scipy.stats import t as student_t

        return float(1.0 - student_t.cdf(t, df=df))
    except Exception:
        # Normal approximation fallback.
        return float(0.5 * (1.0 - math.erf(t / math.sqrt(2.0))))

def compare_conditions(
    env_factory: Callable[[], Any],
    n_episodes: int,
    seeds: List[int],
    condition_callables: Dict[str, Callable[..., FourCountsResult]],
) -> Dict[str, Any]:
    """Run each (condition, seed) cell, aggregate per-condition stats,
    and emit pairwise Welch t-tests on PROMOTE rates.

    Args:
        env_factory: zero-arg callable producing a fresh env per cell.
        n_episodes: episodes per cell.
        seeds: list of seeds to run each condition over.
        condition_callables: dict mapping condition_label ->
            callable(env_factory, n_episodes, seed) -> FourCountsResult.

    Returns:
        {
            "per_condition": {
                <label>: {
                    "promote_rate_mean": float,
                    "promote_rate_std": float,
                    "promote_rates": list[float],
                    "catalog_hit_rate_mean": float,
                    "claim_rate_mean": float,
                    "results": list[FourCountsResult],
                },
                ...
            },
            "pairwise": {
                (a, b): {"p_value": float, "lift": float,
                         "winner": str | None},
                ...
            },
            "n_episodes": int,
            "n_seeds": int,
            "annotation": str | None,
        }

    Raises:
        ValueError: if condition_callables is empty.
    """
    if not condition_callables:
        raise ValueError("condition_callables must be non-empty")
    n_seeds = len(seeds)

    # Per-condition results.
    per_condition: Dict[str, Dict[str, Any]] = {}
    for label, fn in condition_callables.items():
        results: List[FourCountsResult] = []
        for s in seeds:
            res = fn(env_factory, n_episodes, int(s))
            results.append(res)
        promote_rates = np.array(
            [r.promote_rate for r in results], dtype=np.float64
        )
        catalog_hit_rates = np.array(
            [r.catalog_hit_rate for r in results], dtype=np.float64
        )
        claim_rates = np.array(
            [r.claim_rate for r in results], dtype=np.float64
        )
        per_condition[label] = {
            "promote_rate_mean": float(promote_rates.mean()) if promote_rates.size else 0.0,
            "promote_rate_std": (
                float(promote_rates.std(ddof=1)) if promote_rates.size > 1 else 0.0
            ),
            "promote_rates": promote_rates.tolist(),
            "catalog_hit_rate_mean": (
                float(catalog_hit_rates.mean()) if catalog_hit_rates.size else 0.0
            ),
            "claim_rate_mean": (
                float(claim_rates.mean()) if claim_rates.size else 0.0
            ),
            "results": results,
        }

    # Pairwise Welch t-tests on per-seed PROMOTE rates.
    pairwise: Dict[Tuple[str, str], Dict[str, Any]] = {}
    labels = list(condition_callables.keys())
    for a, b in itertools.combinations(labels, 2):
        rates_a = np.array(per_condition[a]["promote_rates"], dtype=np.float64)
        rates_b = np.array(per_condition[b]["promote_rates"], dtype=np.float64)
        ma = float(rates_a.mean()) if rates_a.size else 0.0
        mb = float(rates_b.mean()) if rates_b.size else 0.0
        # Two one-sided tests; report the directional one.
        if ma >= mb:
            p = _welch_t_test_one_sided(rates_a, rates_b)
            winner = a if (not math.isnan(p)) and p < 0.05 else None
            lift_dir = (ma - mb) / max(mb, 1e-12) if mb > 0 else (
                float("inf") if ma > 0 else 0.0
            )
        else:
            p = _welch_t_test_one_sided(rates_b, rates_a)
            winner = b if (not math.isnan(p)) and p < 0.05 else None
            lift_dir = (mb - ma) / max(ma, 1e-12) if ma > 0 else (
                float("inf") if mb > 0 else 0.0
            )
        pairwise[(a, b)] = {
            "p_value": p,
            "lift": lift_dir,
            "winner": winner,
            "mean_a": ma,
            "mean_b": mb,
        }

    annotation: Optional[str] = None
    if n_seeds < 2:
        annotation = (
            f"n_seeds={n_seeds}: Welch t-test undefined (variance requires "
            f">=2 samples).  All p-values reported as NaN."
        )

    return {
        "per_condition": per_condition,
        "pairwise": pairwise,
        "n_episodes": int(n_episodes),
        "n_seeds": int(n_seeds),
        "annotation": annotation,
    }

def promote_rate(self) -> float:
    """PROMOTE rate -- fraction of episodes that produced a
    signal-class survivor (PROMOTED or SHADOW_CATALOG)."""
    if self.total_episodes == 0:
        return 0.0
    return (
        self.promote_count + self.shadow_catalog_count
    ) / self.total_episodes

def catalog_hit_rate(self) -> float:
    if self.total_episodes == 0:
        return 0.0
    return self.catalog_hit_count / self.total_episodes

def claim_rate(self) -> float:
    if self.total_episodes == 0:
        return 0.0
    return self.claim_into_kernel_count / self.total_episodes

def reset(self, *, seed: Optional[int] = None, options: Optional[Dict] = None):
    obs, info = self._base.reset(seed=seed)
    return np.asarray(obs, dtype=np.float32), info

def __init__(self, n_episodes_target: int):
