def _clog(v: float) -> float:
    s = 1.0 if v > 0 else (-1.0 if v < 0 else 0.0)
    return s * math.log10(1.0 + abs(float(v)))

def _welch_one_sided(a: np.ndarray, b: np.ndarray) -> float:
    """One-sided Welch t-test p-value: H1 = mean(a) > mean(b)."""
    if a.size < 2 or b.size < 2:
        return float("nan")
    ma, mb = float(a.mean()), float(b.mean())
    va, vb = float(a.var(ddof=1)), float(b.var(ddof=1))
    se = math.sqrt(va / a.size + vb / b.size) if (va > 0 or vb > 0) else 1e-12
    t = (ma - mb) / max(se, 1e-12)
    df = (
        (va / a.size + vb / b.size) ** 2
        / max(
            (va / a.size) ** 2 / max(a.size - 1, 1)
            + (vb / b.size) ** 2 / max(b.size - 1, 1),
            1e-30,
        )
    )
    try:
        from scipy.stats import t as student_t
        return float(1.0 - student_t.cdf(t, df=df))
    except Exception:
        return float(0.5 * (1.0 - math.erf(max(t, 0.0) / math.sqrt(2.0))))

def main() -> int:
    out = run_pilot()
    return 0 if "error" not in out else 2

def _as_points(points) -> np.ndarray:
    """Coerce ``points`` to a 2-D float array (n_points, n_dim).

    1-D inputs are interpreted as a list of 1-D points and reshaped to
    ``(n, 1)``.  Empty input raises ``ValueError``.
    """
    arr = np.asarray(points, dtype=float)
    if arr.size == 0:
        raise ValueError("convex_hull: empty point set")
    if arr.ndim == 1:
        arr = arr.reshape(-1, 1)
    if arr.ndim != 2:
        raise ValueError(
            f"convex_hull: expected (n_points, n_dim) array, got shape {arr.shape}"
        )
    return arr

def delaunay_triangulation_count(points) -> int:
    """Number of simplices in the Delaunay triangulation of ``points``.

    Note: the full Delaunay API (simplex coordinates, neighbors,
    circumradii, …) is project #72.  This stub returns just the count,
    which is a useful invariant on its own (e.g. Euler-style formulas
    relating |triangulation| to hull facets).
    """
    arr = _as_points(points)
    n, d = arr.shape
    if n < d + 1:
        return 0
    try:
        tri = _Delaunay(arr)
    except _QhullError:
        return 0
    return int(len(tri.simplices))

def _as_2d_array(points) -> np.ndarray:
    """Coerce input to a 2D float ndarray and validate the basic shape."""
    arr = np.asarray(points, dtype=float)
    if arr.ndim != 2:
        raise ValueError(
            f"points must be a 2D array of shape (n, d); got ndim={arr.ndim}"
        )
    if arr.size == 0 or arr.shape[0] == 0:
        raise ValueError("points must be a non-empty 2D array")
    return arr

def circumradius(simplex_points) -> float:
    """Circumradius: distance from the circumcenter to any vertex."""
    pts = np.asarray(simplex_points, dtype=float)
    c = circumcenter(pts)
    return float(np.linalg.norm(pts[0] - c))

def delaunay_alpha_complex(points, alpha: float) -> List[List[int]]:
    """Subset of Delaunay simplices whose circumradius is <= alpha.

    The alpha complex is a standard tool in topological data analysis
    (Edelsbrunner & Mucke 1994).
    """
    tri = delaunay_triangulation(points)
    pts = tri["points"]
    out: List[List[int]] = []
    for simplex in tri["simplices"]:
        try:
            r = circumradius(pts[simplex])
        except ValueError:
            continue
        if r <= alpha:
            out.append([int(v) for v in simplex])
    return out

def _triangle_angles(p1, p2, p3) -> List[float]:
    """Three interior angles (radians) of triangle (p1, p2, p3)."""
    def ang(a, b, c):
        # angle at vertex a, between edges a->b and a->c
        u = b - a
        v = c - a
        cosv = float(np.dot(u, v) / (np.linalg.norm(u) * np.linalg.norm(v)))
        cosv = max(-1.0, min(1.0, cosv))
        return float(np.arccos(cosv))

    return [ang(p1, p2, p3), ang(p2, p1, p3), ang(p3, p1, p2)]

def _require_shapely(op: str) -> None:
    if not _HAS_SHAPELY:
        raise ImportError(
            f"prometheus_math.geometry_voronoi.{op} requires shapely>=2.0; "
            f"install with `pip install shapely`."
        )

def _as_2d_array(points) -> np.ndarray:
    arr = np.asarray(points, dtype=float)
    if arr.ndim != 2:
        raise ValueError(
            f"points must be a 2D array of shape (n, d); got ndim={arr.ndim}"
        )
    if arr.size == 0 or arr.shape[0] == 0:
        raise ValueError("points must be a non-empty 2D array")
    return arr

def _check_bbox(bbox) -> Tuple[float, float, float, float]:
    if bbox is None:
        raise ValueError("bbox is required")
    if len(bbox) != 4:
        raise ValueError("bbox must be (xmin, ymin, xmax, ymax)")
    xmin, ymin, xmax, ymax = (float(b) for b in bbox)
    if not (xmin < xmax and ymin < ymax):
        raise ValueError(
            f"bbox must satisfy xmin<xmax and ymin<ymax; got {bbox}"
        )
    return xmin, ymin, xmax, ymax

def _bbox_polygon(bbox):
    _require_shapely("_bbox_polygon")
    xmin, ymin, xmax, ymax = _check_bbox(bbox)
    return _ShapelyPolygon(
        [(xmin, ymin), (xmax, ymin), (xmax, ymax), (xmin, ymax)]
    )

def _is_collinear_2d(pts: np.ndarray) -> bool:
    if pts.shape[0] < 3:
        return True
    return np.linalg.matrix_rank(pts - pts[0], tol=1e-12) < 2

def _polygon_to_vertices(poly) -> List[Tuple[float, ...]]:
    if poly.is_empty:
        return []
    if poly.geom_type == "Polygon":
        coords = list(poly.exterior.coords)
        # Drop the closing repeated vertex.
        if coords and coords[0] == coords[-1]:
            coords = coords[:-1]
        return [(float(x), float(y)) for x, y in coords]
    if poly.geom_type == "MultiPolygon":
        # Concatenate polygons (rare; happens when bbox carves the cell).
        out: List[Tuple[float, ...]] = []
        for p in poly.geoms:
            out.extend(_polygon_to_vertices(p))
        return out
    return []

def voronoi_neighbors(idx: int, voronoi: Dict[str, Any]) -> List[int]:
    """Indices of cells sharing a ridge with cell ``idx``."""
    out: List[int] = []
    rp = voronoi["ridge_points"]
    for a, b in rp.tolist():
        if a == idx:
            out.append(int(b))
        elif b == idx:
            out.append(int(a))
    return sorted(set(out))

def _polygon_area_shoelace(verts: List[Tuple[float, float]]) -> float:
    if len(verts) < 3:
        return 0.0
    arr = np.asarray(verts, dtype=float)
    x, y = arr[:, 0], arr[:, 1]
    return 0.5 * float(abs(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1))))

def voronoi_cell_area(
    idx: int,
    points,
    bbox: Optional[Tuple[float, float, float, float]] = None,
) -> float:
    """Area of cell ``idx`` (clipped to bbox if supplied).

    For unbounded cells without a bbox, returns ``inf``.
    """
    pts = _as_2d_array(points)
    if bbox is None:
        cell = voronoi_cell(idx, pts)
        if cell is None:
            return float("inf")
        return _polygon_area_shoelace([(c[0], c[1]) for c in cell])
    cell = voronoi_cell_bounded(idx, pts, bbox=bbox)
    if not cell:
        return 0.0
    return _polygon_area_shoelace([(c[0], c[1]) for c in cell])

def _polygon_centroid(verts: List[Tuple[float, float]]) -> np.ndarray:
    """Centroid of a simple polygon via the standard area-weighted formula."""
    arr = np.asarray(verts, dtype=float)
    if arr.shape[0] < 3:
        return arr.mean(axis=0)
    x, y = arr[:, 0], arr[:, 1]
    x1, y1 = np.roll(x, -1), np.roll(y, -1)
    cross = x * y1 - x1 * y
    A = 0.5 * cross.sum()
    if abs(A) < 1e-15:
        return arr.mean(axis=0)
    cx = ((x + x1) * cross).sum() / (6.0 * A)
    cy = ((y + y1) * cross).sum() / (6.0 * A)
    return np.array([cx, cy])

def centroidal_voronoi_tessellation(
    n_points: int,
    bbox: Tuple[float, float, float, float],
    n_iter: int = 20,
    seed: Optional[int] = None,
) -> np.ndarray:
    """Generate a CVT inside ``bbox`` by random init + Lloyd relaxation."""
    if n_points <= 0:
        raise ValueError(f"n_points must be > 0; got {n_points}")
    xmin, ymin, xmax, ymax = _check_bbox(bbox)
    rng = np.random.default_rng(seed)
    pts = np.column_stack(
        [
            rng.uniform(xmin, xmax, size=n_points),
            rng.uniform(ymin, ymax, size=n_points),
        ]
    )
    return lloyd_relaxation(pts, n_iter=n_iter, bbox=bbox)

def _load_json(path: str) -> Optional[Dict[str, Any]]:
    if not os.path.exists(path):
        return None
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def load_all_sources(base_dir: str = PROMETHEUS_MATH_DIR) -> List[Dict[str, Any]]:
    """Load every declared source that exists on disk.

    Skips missing files cleanly; never raises.
    """
    out: List[Dict[str, Any]] = []
    for spec in PILOT_SOURCES:
        path = os.path.join(base_dir, spec["file"])
        data = _load_json(path)
        if data is None:
            continue
        out.append(
            {
                "file": spec["file"],
                "family": spec["family"],
                "schema": spec["schema"],
                "data": data,
            }
        )
    return out

def _extract_kill_pattern_aggregate(rec: Dict[str, Any]) -> Dict[str, Any]:
    """Pull (algorithm_label, kill_pattern, count) tuples out of any rec.

    Returns ``{"per_arm_kill_patterns": {arm: {kp: count}},
                "n_episodes_total": int,
                "details": ..., "schema": ...}``.

    Cleanly returns empty dicts if the schema doesn't carry kill_path.
    """
    schema = rec["schema"]
    data = rec["data"]
    out_arms: Dict[str, Counter] = {}
    n_eps = 0
    n_records = 0

    if schema == "catalog_seeded":
        per_arm = data.get("per_arm", {})
        for arm, val in per_arm.items():
            arm_label = f"catalog_seeded::{arm}"
            arm_counter: Counter = Counter()
            for r in val.get("results", []):
                bkp = r.get("by_kill_pattern", {}) or {}
                for k, v in bkp.items():
                    arm_counter[k] += int(v)
                n_eps += int(r.get("total_episodes", 0))
                n_records += 1
            if arm_counter:
                out_arms[arm_label] = arm_counter

    elif schema == "four_counts_top":
        pc = data.get("per_condition", {})
        for cond, val in pc.items():
            arm_label = f"four_counts::{cond}"
            bkp = val.get("by_kill_pattern", {}) or {}
            arm_counter = Counter()
            for k, v in bkp.items():
                arm_counter[k] += int(v)
            psc = val.get("per_seed_counts", []) or []
            for s in psc:
                # rejected + catalog_hit + promote + shadow ~= total per seed
                n_eps += int(s.get("rejected", 0)) + int(s.get("catalog_hit", 0))
                n_eps += int(s.get("promote", 0)) + int(s.get("shadow_catalog", 0))
                n_records += 1
            if arm_counter:
                out_arms[arm_label] = arm_counter

    elif schema == "four_counts_per_arm":
        for arm, val in data.get("per_arm", {}).items():
            arm_label = f"four_counts_per_arm::{arm}"
            arm_counter = Counter()
            for r in val.get("results", []):
                bkp = r.get("by_kill_pattern", {}) or {}
                for k, v in bkp.items():
                    arm_counter[k] += int(v)
                n_eps += int(r.get("total_episodes", 0))
                n_records += 1
            if arm_counter:
                out_arms[arm_label] = arm_counter

    elif schema == "degree_sweep":
        for deg, deg_block in data.items():
            pc = (deg_block or {}).get("per_condition", {})
            for cond, val in pc.items():
                arm_label = f"degree_sweep::deg{deg}::{cond}"
                arm_counter = Counter()
                bkp = val.get("by_kill_pattern", {}) or {}
                for k, v in bkp.items():
                    arm_counter[k] += int(v)
                psc = val.get("per_seed_counts", []) or []
                for s in psc:
                    n_eps += sum(
                        int(s.get(k, 0))
                        for k in ("rejected", "catalog_hit", "promote", "shadow_catalog")
                    )
                    n_records += 1
                if arm_counter:
                    out_arms[arm_label] = arm_counter

    elif schema == "v2_cells":
        # The v2 schema doesn't aggregate kill_pattern; we can still count
        # episodes for distance-to-target context.
        for cell in data.get("cells", []):
            n_eps += int(cell.get("n_episodes", 0))
            n_records += 1

    elif schema == "v3_cells":
        for cell in data.get("cells", []):
            n_eps += int(cell.get("n_samples", 0))
            n_records += 1

    elif schema == "discovery_v2":
        for r in data.get("results", []):
            n_eps += int(r.get("n_episodes", 0))
            n_records += 1

    elif schema == "lehmer_smoke":
        n_eps += int(data.get("polys_processed", 0))
        n_records += 1

    elif schema == "cross_domain_means":
        # Mean accuracy per algorithm, per seed -- not episode kill_path.
        n_eps += int(data.get("n_episodes", 0)) * int(data.get("n_seeds", 0))
        n_records += 1

    elif schema == "cross_domain_mlp":
        n_eps += int(data.get("n_episodes", 0)) * int(data.get("n_seeds", 0))
        n_records += 1

    return {
        "per_arm_kill_patterns": {a: dict(c) for a, c in out_arms.items()},
        "n_episodes_total": n_eps,
        "n_records": n_records,
        "schema": schema,
    }

def _extract_m_records(rec: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Pull every per-candidate (M, coeffs, label, arm) record.

    Currently only the ``catalog_seeded`` schema persists per-candidate
    records via ``details[*].catalog_hits``.  Other schemas don't.
    """
    out: List[Dict[str, Any]] = []
    if rec["schema"] != "catalog_seeded":
        return out
    per_arm = rec["data"].get("per_arm", {})
    for arm, val in per_arm.items():
        arm_label = f"catalog_seeded::{arm}"
        for det in val.get("details", []):
            seed = det.get("seed")
            for ch in det.get("catalog_hits", []) or []:
                m = ch.get("mahler_measure")
                if m is None:
                    continue
                try:
                    m = float(m)
                except Exception:
                    continue
                if not math.isfinite(m):
                    continue
                out.append(
                    {
                        "arm": arm_label,
                        "seed": seed,
                        "M": m,
                        "coeffs": tuple(ch.get("coeffs", [])),
                        "reward_label": ch.get("reward_label"),
                        "via": ch.get("via"),
                        "episode": ch.get("episode"),
                    }
                )
    return out

def _extract_cross_domain_means(rec: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """For cross-domain pilots: pull per-algorithm test means + p-values."""
    if rec["schema"] not in ("cross_domain_means", "cross_domain_mlp"):
        return None
    d = rec["data"]
    family = rec["family"]
    out: Dict[str, Any] = {
        "family": family,
        "file": rec["file"],
        "n_episodes": d.get("n_episodes"),
        "n_seeds": d.get("n_seeds"),
    }
    # collect any *_means and *_mean fields
    means: Dict[str, Any] = {}
    for k, v in d.items():
        if k.endswith("_means") and isinstance(v, list):
            means[k] = v
        elif k.endswith("_mean") and isinstance(v, (int, float)):
            means[k] = v
        elif k.startswith("p_value_"):
            means[k] = v
    out["means"] = means
    out["corpus"] = d.get("corpus")
    return out

def _extract_lehmer_smoke_records(rec: Dict[str, Any]) -> List[Dict[str, Any]]:
