def _letter_index(letter: str) -> int:
    """LMFDB letter -> 0-based index ('a'->0, 'b'->1, ..., 'aa'->26)."""
    n = 0
    for c in letter:
        if not c.isalpha() or not c.islower():
            raise ValueError(f"bad newform letter {letter!r}")
