def _match_letter_via_lmfdb(
    level: int, weight: int, letter: str, forms: list
):
    """Return the PARI eigenform whose first few a_p match LMFDB's stored
    ap for the (level, weight, letter) newform. None if LMFDB unreachable.
    """
    try:
        from prometheus_math.databases import lmfdb as _lmfdb
    except Exception:
        return None
    try:
        with _lmfdb.connect(timeout=5) as conn:
            cur = conn.cursor()
            label = f"{level}.{weight}.a.{letter}"
            # Pull a_2, a_3, a_5 from LMFDB; for dim>1 these are coeff
            # vectors in the Hecke ring power basis.
            cur.execute(
                "SELECT ap->0, ap->1, ap->2, hecke_ring_rank "
                "FROM mf_hecke_nf WHERE label = %s",
                (label,),
            )
            row = cur.fetchone()
            if row is None:
                return None
            lmfdb_a2, lmfdb_a3, lmfdb_a5, dim = row
    except Exception:
        return None

    def _ap_matches(form, target_ap_lists):
        for prime, target in zip((2, 3, 5), target_ap_lists):
            ap = pari.mfcoef(form, prime)
            ap_list = _to_power_basis_coeffs(ap)
            # Pad/truncate to compare in same length
            if len(ap_list) < len(target):
                ap_list = ap_list + [0] * (len(target) - len(ap_list))
            elif len(ap_list) > len(target):
                # If form's Hecke field is larger than LMFDB's, it can't be
                # the same newform.
                return False
            if list(ap_list) != [int(x) for x in target]:
                return False
        return True

    targets = (lmfdb_a2, lmfdb_a3, lmfdb_a5)
    for f in forms:
        try:
            if _ap_matches(f, targets):
                return f
        except Exception:
            continue
    return None

def _to_power_basis_coeffs(value) -> list[int]:
    """Convert a PARI eigenvalue (int or Mod(poly, defpoly)) to ascending
    power-basis coefficient list [c_0, c_1, ..., c_{r-1}].

    For dim=1 newforms, returns a single-element list [a_p]. For dim>1
    returns the coefficient vector matching LMFDB's `ap[i]` storage.
    """
    try:
        return [int(value)]
    except Exception:
        pass
    # PARI Mod: extract via lift -> Vecrev (ascending coefficients).
    try:
        lifted = pari.lift(value)
        coeffs = pari.Vecrev(lifted)
        return [int(c) for c in coeffs]
    except Exception as e:
        raise RuntimeError(
            f"could not coerce PARI value {value!r} to integer "
            f"power-basis coefficients: {e}"
        ) from e

def _to_eigenvalue(value, prec: str = "exact"):
    """Format a PARI eigenvalue for return.

    prec='exact' returns int for dim=1, otherwise the PARI Mod string.
    prec='complex' returns a complex number (numerical embedding).
    prec='coeffs' returns the ascending power-basis coeff list.
    """
    if prec == "coeffs":
        return _to_power_basis_coeffs(value)
    coeffs = _to_power_basis_coeffs(value)
    if prec == "exact":
        if len(coeffs) == 1:
            return coeffs[0]
        # Higher-dim: return PARI's Mod string repr (researcher-readable).
        return str(value)
    if prec == "complex":
        if len(coeffs) == 1:
            return complex(coeffs[0])
        # Numerically embed the Hecke field's first real root into C.
        try:
            num = pari.subst(pari.lift(value), "y", pari.polroots(pari.minpoly(value))[0])
            return complex(float(pari.real(num)), float(pari.imag(num)))
        except Exception:
            return complex("nan")
    raise ValueError(
        f"unknown prec {prec!r}; expected 'exact' / 'complex' / 'coeffs'"
    )

def eigenvalues_table(
    label: str,
    primes: Optional[Iterable[int]] = None,
    p_max: int = 200,
    prec: str = "exact",
) -> dict[int, Union[int, str, list[int]]]:
    """Compute {p: a_p} for all primes <= p_max, or the explicit primes list.

    For dim=1 newforms each value is an int. For dim>1, each is a
    PARI Mod string (with prec='exact') or coefficient list
    (with prec='coeffs').

    Authority: eigenvalues_table('11.2.a.a', primes=[2,3,5]) ==
        {2: -2, 3: -1, 5: 1}.
    """
    level, weight, _, letter = _parse_label(label)
    f = _select_form(level, weight, letter)
    if primes is None:
        if not isinstance(p_max, int) or p_max < 2:
            raise ValueError(f"p_max must be int >= 2, got {p_max!r}")
        prime_list = list(sieve.primerange(2, p_max + 1))
    else:
        prime_list = []
        for p in primes:
            if not isinstance(p, int) or isinstance(p, bool):
                raise ValueError(f"non-int in primes list: {p!r}")
            if not isprime(p):
                raise ValueError(f"non-prime in primes list: {p}")
            prime_list.append(p)
    out: dict[int, Union[int, str, list[int]]] = {}
    for p in prime_list:
        ap = safe_call(pari.mfcoef, f, p)
        out[p] = _to_eigenvalue(ap, prec=prec)
    return out

def bulk_eigenvalues(
    labels: Iterable[str], p_max: int = 100, prec: str = "exact"
) -> dict[str, dict[int, Union[int, str, list[int]]]]:
    """Compute eigenvalue tables for many newforms.

    Levels/weights are deduplicated so PARI mfinit is called once per
    (level, weight) space rather than once per label. This is a 5-50x
    speedup when sweeping many labels in the same space.

    Returns {label: {p: a_p, ...}, ...}.
    """
    if not isinstance(p_max, int) or p_max < 2:
        raise ValueError(f"p_max must be int >= 2, got {p_max!r}")
    primes_list = list(sieve.primerange(2, p_max + 1))
    out: dict[str, dict[int, Union[int, str, list[int]]]] = {}
    # Group labels by (level, weight) to leverage the eigenform cache.
    groups: dict[tuple[int, int], list[tuple[str, str]]] = {}
    for lbl in labels:
        level, weight, _, letter = _parse_label(lbl)
        groups.setdefault((level, weight), []).append((lbl, letter))
    for (level, weight), group in groups.items():
        for lbl, letter in group:
            f = _select_form(level, weight, letter)
            tbl: dict[int, Union[int, str, list[int]]] = {}
            for p in primes_list:
                ap = safe_call(pari.mfcoef, f, p)
                tbl[p] = _to_eigenvalue(ap, prec=prec)
            out[lbl] = tbl
    return out

def _ap_matches(form, target_ap_lists):
    for prime, target in zip((2, 3, 5), target_ap_lists):
        ap = pari.mfcoef(form, prime)
        ap_list = _to_power_basis_coeffs(ap)
        # Pad/truncate to compare in same length
        if len(ap_list) < len(target):
            ap_list = ap_list + [0] * (len(target) - len(ap_list))
        elif len(ap_list) > len(target):
            # If form's Hecke field is larger than LMFDB's, it can't be
            # the same newform.
            return False
        if list(ap_list) != [int(x) for x in target]:
            return False
    return True

def _coerce_poly(polynomial) -> str:
    """Coerce a polynomial input to a PARI-parseable string in variable x.

    Accepts:
      * str (passed through),
      * list/tuple of integer coefficients in descending order
        [a_n, ..., a_0].
    """
    if isinstance(polynomial, str):
        if not polynomial.strip():
            raise ValueError("lambda_mu: empty polynomial input")
        return polynomial
    coeffs = list(polynomial)
    if not coeffs:
        raise ValueError("lambda_mu: empty polynomial input")
    if len(coeffs) < 2:
        raise ValueError(
            "lambda_mu: input is not a number-field polynomial "
            "(degree must be >= 1)"
        )
    deg = len(coeffs) - 1
    terms = []
    for i, c in enumerate(coeffs):
        power = deg - i
        if c == 0:
            continue
        if power == 0:
            terms.append(f"({int(c)})")
        elif power == 1:
            terms.append(f"({int(c)})*x")
        else:
            terms.append(f"({int(c)})*x^{power}")
    if not terms:
        raise ValueError("polynomial is identically zero")
    return "+".join(terms)

def _safe_call(fn, *, max_retries: int = 3):
    """Run a PARI thunk; on stack overflow, double the stack and retry."""
    last_err: Optional[Exception] = None
    for _ in range(max_retries + 1):
        try:
            return fn()
        except cypari._pari.PariError as e:
            if 'stack overflows' not in str(e):
                raise
            last_err = e
            new_size = min(2 * _pari.stacksize(), _MAX_STACK_BYTES)
            if new_size <= _pari.stacksize():
                break
            _pari.allocatemem(new_size)
    if last_err is not None:
        raise last_err

def _p_adic_valuation(n: int, p: int) -> int:
    """Largest k with p^k | n. v_p(0) := 0 by convention (only used here)."""
    if n == 0:
        return 0
    n = abs(int(n))
    k = 0
    while n % p == 0:
        n //= p
        k += 1
    return k

def _polynomial_degree(pol_str: str) -> int:
    """Return PARI's poldegree of a polynomial string."""
    return int(_pari(f"poldegree({pol_str})"))

def _squash_margin(margin: Optional[float], unit: Optional[str]) -> float:
    """Map a (margin, unit) pair into [0, 1] saturated kill-strength.

    Returns 0.0 when ``margin`` is None or unit is unknown — i.e.
    "no information about how strongly this killed".  Used by
    ``magnitude(unit_aware=True)``.
    """
    if margin is None or unit is None:
        return 0.0
    try:
        m = float(margin)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(m):
        # +inf catalog distance = "no near match" = strong miss-signal,
        # which for kill-strength purposes saturates at 1.
        if math.isinf(m) and m > 0 and unit == "hamming":
            return 1.0
        return 0.0

    if unit == "p_value":
        # margin already mapped to [0, 1] by the convention 1 - p_value.
        return max(0.0, min(1.0, m))
    if unit == "z_score":
        # |z| / (|z| + Z_CHARACTERISTIC); signed z folded by abs.
        a = abs(m)
        return a / (a + _Z_CHARACTERISTIC)
    if unit == "hamming":
        # 0 = exact match (no kill); larger = farther = stronger miss.
        # Saturate via 1 - 1/(1+d) so 0 -> 0, 1 -> 0.5, +inf -> 1.
        if m < 0:
            m = 0.0
        return 1.0 - 1.0 / (1.0 + m)
    if unit == "absolute":
        a = abs(m)
        return a / (a + 1.0)
    if unit == "log_distance":
        # exp(-max(0, m)) so log_distance=0 → 1, large positive → 0.
        return math.exp(-max(0.0, m))
    if unit == "boolean":
        return 1.0 if m else 0.0
    return 0.0

def _coeff_reciprocity_margin(coeffs: List[int]) -> float:
    """Max |c_i - c_{n-1-i}| over coefficient pairs.  0 = palindromic."""
    n = len(coeffs)
    if n == 0:
        return 0.0
    return float(max(abs(coeffs[i] - coeffs[n - 1 - i]) for i in range(n // 2)))

def _f11_drift_margin(rationale: str) -> Optional[float]:
    """Parse F11 rationale for either drift or cross-val numerics.

    Rationale shapes:
      * "F11: cross-val agrees within 1e-6 (V)"   — survived
      * "F11: cross-val mismatch A vs B"          — killed by mismatch
      * "F11: M drift A vs reported B"            — killed by drift
      * "F11: non-finite M in cross-val"          — killed
    """
    import re

    m = re.search(r"mismatch ([\d\.eE\-\+]+) vs ([\d\.eE\-\+]+)", rationale)
    if m:
        try:
            return abs(float(m.group(1)) - float(m.group(2)))
        except ValueError:
            return None
    m = re.search(r"drift ([\d\.eE\-\+]+) vs reported ([\d\.eE\-\+]+)", rationale)
    if m:
        try:
            return abs(float(m.group(1)) - float(m.group(2)))
        except ValueError:
            return None
    return None

def aggregate_by_operator(
    vectors: List[KillVector],
) -> Dict[str, Dict[str, float]]:
    """Compute ``E[k_i | operator]`` over a corpus of KillVectors.

    Returns a nested dict::

        {
            operator_class: {
                falsifier_name: P(triggered=True | operator),
                ...,
                f"{falsifier_name}__mean_squashed": E[squashed_margin],
                f"__count": N,
            },
            ...
        }

    This is the directional-derivative input the Day-4 learner consumes.
    Implementation is intentionally simple (one pass, dict math) so it
    can run inside the kernel's read-path without dragging numpy in.
    """
    by_op: Dict[str, Dict[str, List[float]]] = {}
    counts: Dict[str, int] = {}

    for v in vectors:
        op = v.operator_class or "_unknown"
        bucket = by_op.setdefault(op, {})
        counts[op] = counts.get(op, 0) + 1
        for c in v.components:
            tk = bucket.setdefault(c.falsifier_name, [])
            tk.append(1.0 if c.triggered else 0.0)
            sk = bucket.setdefault(f"{c.falsifier_name}__squashed", [])
            sk.append(c.squashed())

    out: Dict[str, Dict[str, float]] = {}
    for op, bucket in by_op.items():
        d: Dict[str, float] = {"__count": float(counts.get(op, 0))}
        for k, vs in bucket.items():
            if vs:
                d[k] = sum(vs) / len(vs)
        out[op] = d
    return out

def __post_init__(self) -> None:  # type: ignore[override]
    # Frozen dataclass — bypass setattr for sanity-check side-effects.
    if self.margin is not None and self.margin_unit is None:
        object.__setattr__(self, "margin_unit", "absolute")
    if self.margin_unit is not None and self.margin_unit not in MARGIN_UNITS:
        raise ValueError(
            f"unknown margin_unit {self.margin_unit!r}; "
            f"must be one of {MARGIN_UNITS}"
        )
    # Permissive validation for precision fields: accept anything
    # string-shaped for method/convergence (the substrate is
    # permissive at write, strict at hash). But coerce types so
    # JSON serialization doesn't surprise downstream consumers.
    if self.precision_dps is not None:
        try:
            object.__setattr__(self, "precision_dps", int(self.precision_dps))
        except (TypeError, ValueError):
            object.__setattr__(self, "precision_dps", None)
    if not isinstance(self.method, str):
        object.__setattr__(self, "method", str(self.method))
    if not isinstance(self.convergence_status, str):
        object.__setattr__(self, "convergence_status", str(self.convergence_status))
    if self.stability is not None:
        try:
            s = float(self.stability)
        except (TypeError, ValueError):
            s = None
        if s is None or not math.isfinite(s):
            object.__setattr__(self, "stability", None)
        else:
            # Clamp to [0, 1].
            object.__setattr__(self, "stability", max(0.0, min(1.0, s)))
    # T-2026-05-07-T029 multi-precision sister-field validation.
    # Permissive at write (substrate v2.3 §6.2 P3 discipline): coerce
    # to None on bad input rather than raising, mirroring the
    # precision_dps + stability handling above.
    if self.margin_high_precision is not None:
        if not isinstance(self.margin_high_precision, str):
            object.__setattr__(self, "margin_high_precision",
                               str(self.margin_high_precision))
        # Empty string is treated as "not present" — consumers should
        # not see "" and try to parse it.
        if self.margin_high_precision == "":
            object.__setattr__(self, "margin_high_precision", None)
    if self.margin_precision_dps is not None:
        try:
            d = int(self.margin_precision_dps)
            if d < 0:
                d = None
        except (TypeError, ValueError):
            d = None
        object.__setattr__(self, "margin_precision_dps", d)

def squashed(self) -> float:
    """[0, 1] saturated kill-strength for this component."""
    return _squash_margin(self.margin, self.margin_unit)

def to_dict(self) -> Dict[str, Any]:
    return {
        "falsifier_name": self.falsifier_name,
        "triggered": bool(self.triggered),
        "margin": (
            None if self.margin is None else float(self.margin)
        ),
        "margin_unit": self.margin_unit,
        "metadata": dict(self.metadata or {}),
        "precision_dps": (
            None if self.precision_dps is None else int(self.precision_dps)
        ),
        "method": str(self.method),
        "convergence_status": str(self.convergence_status),
        "stability": (
            None if self.stability is None else float(self.stability)
        ),
        "stability_pass": (
            None if self.stability_pass is None
            else self.stability_pass.to_dict()
        ),
        # Multi-precision sister fields (T-2026-05-07-T029). Omit
        # from JSON when None to avoid bloating legacy dumps.
        "margin_high_precision": self.margin_high_precision,
        "margin_precision_dps": (
            None if self.margin_precision_dps is None
            else int(self.margin_precision_dps)
        ),
    }

def from_dict(cls, d: Dict[str, Any]) -> "KillComponent":
    # Backwards-compat: legacy dicts (pre-2026-05-04) lack the four
    # precision fields. Defaults reproduce pre-change behavior.
    sp_raw = d.get("stability_pass")
    sp_obj: Optional[StabilityResult]
    if sp_raw is None:
        sp_obj = None
    elif isinstance(sp_raw, StabilityResult):
        sp_obj = sp_raw
    else:
        sp_obj = StabilityResult.from_dict(sp_raw)
    return cls(
        falsifier_name=str(d["falsifier_name"]),
        triggered=bool(d.get("triggered", False)),
        margin=(
            None if d.get("margin") is None else float(d["margin"])
        ),
        margin_unit=d.get("margin_unit"),
        metadata=dict(d.get("metadata") or {}),
        precision_dps=(
            None if d.get("precision_dps") is None
            else int(d["precision_dps"])
        ),
        method=str(d.get("method", "unknown")),
        convergence_status=str(d.get("convergence_status", "n/a")),
        stability=(
            None if d.get("stability") is None
            else float(d["stability"])
        ),
        stability_pass=sp_obj,
        # Multi-precision sister fields (T-2026-05-07-T029). Legacy
        # pre-2026-05-10 dumps lack these; defaults to None preserve
        # pre-change behavior.
        margin_high_precision=d.get("margin_high_precision"),
        margin_precision_dps=(
            None if d.get("margin_precision_dps") is None
            else int(d["margin_precision_dps"])
        ),
    )

def first_triggered(self) -> Optional[KillComponent]:
    """First component whose ``triggered`` is True, in component
    order.  Equivalent to the old categorical kill_path: the
    pipeline's "first-failing" semantics is preserved."""
    for c in self.components:
        if c.triggered:
            return c
    return None

def to_legacy_kill_path(self) -> Optional[str]:
    """Render the kill_vector to the legacy ``kill_path: str``
    format used by older pipeline records.  Returns None if no
    component triggered (i.e. the candidate would PROMOTE)."""
    c = self.first_triggered
    if c is None:
        return None
    # Reproduce the kill_pattern strings from discovery_pipeline._
    # process_candidate's Phase 2 ladder.
    name = c.falsifier_name
    meta = c.metadata or {}
    if name == "out_of_band":
        m = meta.get("M") or meta.get("mahler_measure") or "?"
        return f"out_of_band:M={m}_outside_(1.001,1.18)"
    if name == "reciprocity":
        return "reciprocity_failed"
    if name == "irreducibility":
        rat = str(meta.get("rationale", "reducible"))[:80]
        return f"reducible:{rat}"
    if name.startswith("catalog:"):
        cat = name.split(":", 1)[1]
        label = meta.get("match_label", "?")
        return f"known_in_catalog:matches {cat} entry {label}"
    if name == "F1_permutation_null":
        rat = str(meta.get("rationale", ""))[:80]
        return f"F1_kill:{rat}"
    if name == "F6_base_rate":
        rat = str(meta.get("rationale", ""))[:80]
        return f"F6_kill:{rat}"
    if name == "F9_simpler_explanation":
        rat = str(meta.get("rationale", ""))[:80]
        return f"F9_kill:{rat}"
    if name == "F11_cross_validation":
        rat = str(meta.get("rationale", ""))[:80]
        return f"F11_kill:{rat}"
    return f"{name}_kill"

def get(self, name: str) -> Optional[KillComponent]:
    """Return the component named ``name``, or None if absent."""
    for c in self.components:
        if c.falsifier_name == name:
            return c
    return None

def min_precision_dps(self) -> Optional[int]:
    """Lowest non-None ``precision_dps`` across components — the
    weakest link of numerical resolution. None iff no component
    recorded a precision (e.g. all methods are non-mpmath).

    Empty-components vector returns None.
    """
    dps_values = [
        c.precision_dps for c in self.components if c.precision_dps is not None
    ]
    if not dps_values:
        return None
    return min(dps_values)

def methods_used(self) -> Tuple[str, ...]:
    """Unordered set of methods invoked across components, returned
    as a sorted tuple for determinism.

    Empty-components vector returns ``()``.
    """
    return tuple(sorted({c.method for c in self.components}))

def triggered_component_names(self) -> Tuple[str, ...]:
    """Sorted tuple of names of all triggered components — the
    component-set used for co-occurrence analysis."""
    return tuple(sorted({c.falsifier_name for c in self.components if c.triggered}))

def to_dict(self) -> Dict[str, Any]:
    return {
        "components": [c.to_dict() for c in self.components],
        "candidate_hash": self.candidate_hash,
        "operator_class": self.operator_class,
        "region_meta": dict(self.region_meta),
        "timestamp": float(self.timestamp),
    }

def from_dict(cls, d: Dict[str, Any]) -> "KillVector":
    comps = tuple(
        KillComponent.from_dict(c) for c in (d.get("components") or [])
    )
    return cls(
        components=comps,
        candidate_hash=str(d.get("candidate_hash", "")),
        operator_class=str(d.get("operator_class", "")),
        region_meta=dict(d.get("region_meta") or {}),
        timestamp=float(d.get("timestamp", 0.0) or 0.0),
    )

def _canonical_component_for_legacy_kp(kp: str) -> Optional[str]:
    """Map a legacy kill_pattern string to one of CANONICAL_COMPONENTS.

    Returns None if the pattern doesn't match any canonical component
    (the record is dropped from the dataset, with a count in the
    diagnostic).
    """
    if not kp:
        return None
    if kp in LEGACY_UPSTREAM_TO_COMPONENT:
        return LEGACY_UPSTREAM_TO_COMPONENT[kp]
    if kp.startswith("upstream:"):
        return "out_of_band"
    if kp.startswith("out_of_band"):
        return "out_of_band"
    if kp.startswith("reciprocity"):
        return "reciprocity"
    if kp.startswith("reducible"):
        return "irreducibility"
    if kp.startswith("known_in_catalog"):
        for cat in ("Mossinghoff", "lehmer_literature", "LMFDB", "OEIS", "arXiv"):
            if cat in kp:
                return f"catalog:{cat}"
        return "catalog:Mossinghoff"
    if kp.startswith("F1_kill"):
        return "F1_permutation_null"
    if kp.startswith("F6_kill"):
        return "F6_base_rate"
    if kp.startswith("F9_kill"):
        return "F9_simpler_explanation"
    if kp.startswith("F11_kill"):
        return "F11_cross_validation"
    return None

def _build_feature_matrix(
    records: Sequence[LearnerRecord],
    *,
    region_encoder: Optional[OneHotEncoder] = None,
    operator_encoder: Optional[OneHotEncoder] = None,
) -> Tuple[np.ndarray, OneHotEncoder, OneHotEncoder]:
    """One-hot encode region + operator + (degree, alphabet_width,
    reward_shape, env) into a dense feature matrix.

    If encoders are supplied (test/eval pass), they are used. Otherwise,
    new encoders are fit on the supplied records (training pass).
    """
    if not records:
        return (np.zeros((0, 0), dtype=float), None, None)

    region_arr = np.array([[r.region] for r in records], dtype=object)
    operator_arr = np.array([[r.operator] for r in records], dtype=object)

    if region_encoder is None:
        region_encoder = OneHotEncoder(
            sparse_output=False, handle_unknown="ignore"
        )
        region_encoder.fit(region_arr)
    if operator_encoder is None:
        operator_encoder = OneHotEncoder(
            sparse_output=False, handle_unknown="ignore"
        )
        operator_encoder.fit(operator_arr)

    region_oh = region_encoder.transform(region_arr)
    operator_oh = operator_encoder.transform(operator_arr)

    # Region meta numeric features: degree, alphabet_width
    def _num(meta: Dict[str, Any], key: str, default: float = 0.0) -> float:
        v = meta.get(key, default)
        try:
            return float(v)
        except (TypeError, ValueError):
            return default

    deg = np.array([[_num(r.region_meta, "degree", 10.0)] for r in records],
                   dtype=float)
    width = np.array([[_num(r.region_meta, "alphabet_width", 5.0)]
                      for r in records], dtype=float)

    # Reward-shape one-hot (binary: step vs shaped)
    shape_one = np.array(
        [[1.0 if r.region_meta.get("reward_shape") == "shaped" else 0.0]
         for r in records],
        dtype=float,
    )

    X = np.hstack([region_oh, operator_oh, deg, width, shape_one])
    return X, region_encoder, operator_encoder

def _safe_brier(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    if len(y_true) == 0:
        return float("nan")
    return float(brier_score_loss(y_true, np.clip(y_pred, 0.0, 1.0)))

def _safe_auc(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    if len(y_true) == 0:
        return float("nan")
    if len(np.unique(y_true)) < 2:
        return float("nan")
    try:
        return float(roc_auc_score(y_true, y_pred))
    except Exception:
        return float("nan")

def _accuracy(y_true: np.ndarray, y_pred_prob: np.ndarray) -> float:
    if len(y_true) == 0:
        return float("nan")
    pred = (y_pred_prob >= 0.5).astype(float)
    return float(np.mean(pred == y_true))

def per_component_metrics(
    records: Sequence[LearnerRecord],
    pred_trig: np.ndarray,
    component_names: Tuple[str, ...],
) -> Dict[str, Dict[str, float]]:
    """For each component, compute classification metrics on the held-out
    set."""
    Y = np.stack([r.y_triggered for r in records]) if records else np.zeros(
        (0, len(component_names))
    )
    out: Dict[str, Dict[str, float]] = {}
    for j, name in enumerate(component_names):
        yj = Y[:, j] if Y.size else np.zeros(0)
        pj = pred_trig[:, j] if pred_trig.size else np.zeros(0)
        out[name] = {
            "accuracy": _accuracy(yj, pj),
            "auc": _safe_auc(yj, pj),
            "brier": _safe_brier(yj, pj),
            "n_positive": int((yj == 1.0).sum()),
            "n_total": int(len(yj)),
        }
    return out

def overall_kill_vector_mae(
    records: Sequence[LearnerRecord],
    pred_trig: np.ndarray,
) -> float:
    """Per-record L1 norm averaged over records: MAE of the predicted
    triggered vector. Lower = better."""
    if not records:
        return float("nan")
    Y = np.stack([r.y_triggered for r in records])
    return float(np.mean(np.abs(Y - pred_trig)))

def _per_region_breakdown(
    test_records: Sequence[LearnerRecord],
    pred_trig: np.ndarray,
) -> Dict[str, Dict[str, float]]:
    by_region_idx: Dict[str, List[int]] = defaultdict(list)
    for i, r in enumerate(test_records):
        by_region_idx[r.region].append(i)
    out: Dict[str, Dict[str, float]] = {}
    for region, idxs in by_region_idx.items():
        if not idxs:
            continue
        Y = np.stack([test_records[i].y_triggered for i in idxs])
        P = pred_trig[idxs]
        out[region] = {
            "n": float(len(idxs)),
            "kv_mae": float(np.mean(np.abs(Y - P))),
            "macro_accuracy": float(
                np.mean(((P >= 0.5).astype(float) == Y).astype(float))
            ),
        }
    return out

def _verdict_from_mae(
    learner_mae: float,
    cell_baseline_mae: float,
    region_baseline_mae: float,
) -> Tuple[str, str]:
    """Apply the A/B/C verdict dispatch."""
    eps = 0.005
    if not math.isfinite(learner_mae) or not math.isfinite(cell_baseline_mae):
        return "C_REPRESENTATION_ISSUE", (
            f"Non-finite MAE (learner={learner_mae}, cell={cell_baseline_mae})"
            " — investigate before Day 5."
        )
    if learner_mae < cell_baseline_mae - eps:
        return "A_BEATS_CELL_MEAN", (
            f"Learner MAE {learner_mae:.4f} beats region x operator cell-mean"
            f" baseline {cell_baseline_mae:.4f} by {cell_baseline_mae - learner_mae:.4f}."
            " Substrate has a learnable gradient field beyond table lookup;"
            " Day 5 navigation is well-founded."
        )
    if learner_mae > cell_baseline_mae + eps:
        return "C_UNDERPERFORMS_CELL_MEAN", (
            f"Learner MAE {learner_mae:.4f} is worse than cell-mean"
            f" baseline {cell_baseline_mae:.4f}. Possible bug or"
            " representation mismatch — investigate."
        )
    return "B_MATCHES_CELL_MEAN", (
        f"Learner MAE {learner_mae:.4f} ≈ cell-mean baseline"
        f" {cell_baseline_mae:.4f} (within {eps}). No generalization beyond"
        " memorization; Day 5 navigation is just lookup. Need denser data"
        " or new operators to find generalisable signal."
    )

def to_dict(self) -> Dict[str, Any]:
    return {
        "region": self.region,
        "operator": self.operator,
        "region_meta": dict(self.region_meta),
        "y_triggered": self.y_triggered.tolist(),
        "y_margin": [None if math.isnan(x) else float(x)
                     for x in self.y_margin.tolist()],
        "weight": float(self.weight),
    }

def coverage_matrix(self) -> Dict[Tuple[str, str], int]:
    """Region x operator -> count of records."""
    c: Counter = Counter()
    for r in self.records:
        c[(r.region, r.operator)] += int(round(r.weight))
    return dict(c)

def _num(meta: Dict[str, Any], key: str, default: float = 0.0) -> float:
    v = meta.get(key, default)
    try:
        return float(v)
    except (TypeError, ValueError):
        return default

def predict(self, records: Sequence[LearnerRecord], *, kind: str) -> np.ndarray:
    """Return shape (n, n_components) predictions for ``records``.

    ``kind`` is one of {"global", "region", "operator", "cell"}.
    Falls back through the hierarchy when a key is missing in
    train: cell -> region+operator -> region -> operator -> global.
    """
    out = np.zeros((len(records), self.n_components), dtype=float)
    for i, r in enumerate(records):
        if kind == "global":
            out[i] = self.global_mean_trig
        elif kind == "region":
            out[i] = self.per_region_trig.get(r.region, self.global_mean_trig)
        elif kind == "operator":
            out[i] = self.per_operator_trig.get(
                r.operator, self.global_mean_trig
            )
        elif kind == "cell":
            v = self.per_cell_trig.get((r.region, r.operator))
            if v is None:
                v = self.per_region_trig.get(r.region)
            if v is None:
                v = self.per_operator_trig.get(r.operator)
            if v is None:
                v = self.global_mean_trig
            out[i] = v
        else:
            raise ValueError(f"unknown baseline kind {kind!r}")
    # Clip floating-point roundoff (weighted mean can produce
    # 1.0000000000000002 when all weights agree on triggered=1).
    np.clip(out, 0.0, 1.0, out=out)
    return out

def predict_proba(self, records: Sequence[LearnerRecord]) -> np.ndarray:
    """Probability of triggered=True per component. Shape (n, K)."""
    if not records:
        return np.zeros((0, len(self.component_names)), dtype=float)
    X, _, _ = _build_feature_matrix(
        records,
        region_encoder=self.region_encoder,
        operator_encoder=self.operator_encoder,
    )
    out = np.zeros((len(records), len(self.component_names)), dtype=float)
    for j, m in enumerate(self.triggered_models):
        if m is None:
            # All training records had identical triggered for this
            # component; predict the train mean.
            out[:, j] = float(self.train_global_mean_trig[j])
        else:
            # liblinear gives binary [P(0), P(1)]; take col 1
            p = m.predict_proba(X)
            if p.shape[1] == 1:
                # only one class seen in train (shouldn't happen given
                # uniq check, but defensive)
                out[:, j] = m.classes_[0]
            else:
                out[:, j] = p[:, list(m.classes_).index(1.0)]
    return out

def predict_margin(self, records: Sequence[LearnerRecord]) -> np.ndarray:
    """Margin prediction per component. Shape (n, K). NaN where no
    margin model could be fit."""
    if not records:
        return np.zeros((0, len(self.component_names)), dtype=float)
    X, _, _ = _build_feature_matrix(
        records,
        region_encoder=self.region_encoder,
        operator_encoder=self.operator_encoder,
    )
    out = np.full((len(records), len(self.component_names)),
                  np.nan, dtype=float)
    for j, m in enumerate(self.margin_models):
        if m is None:
            continue
        out[:, j] = m.predict(X)
    return out

def predict_kill_vector(
    self, records: Sequence[LearnerRecord]
) -> np.ndarray:
    """Combined predicted (n, K) triggered-prob vector for L2 norm
    computations downstream. Equivalent to predict_proba; the margin
    layer is reported separately."""
    return self.predict_proba(records)

def _wmean(ys: List[np.ndarray], ws: List[float]) -> np.ndarray:
    ya = np.stack(ys)
    wa = np.asarray(ws, dtype=float)
    tot = wa.sum()
    return (ya * wa[:, None]).sum(axis=0) / max(tot, 1e-12)

def _region_meta_from_id(region_id: str) -> Dict[str, Any]:
    """Best-effort inverse of ``_region_id_from_meta``."""
    parts = region_id.split("|")
    out: Dict[str, Any] = {}
    if len(parts) >= 1:
        out["env"] = parts[0]
    if len(parts) >= 2 and parts[1].startswith("deg"):
        try:
            out["degree"] = int(parts[1][3:])
        except ValueError:
            out["degree"] = parts[1][3:]
    if len(parts) >= 3 and parts[2].startswith("w"):
        try:
            out["alphabet_width"] = int(parts[2][1:])
        except ValueError:
            out["alphabet_width"] = parts[2][1:]
    if len(parts) >= 4:
        out["reward_shape"] = parts[3]
    return out

def _load_json(path: str) -> Optional[Dict[str, Any]]:
    if not os.path.exists(path):
        return None
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except (OSError, json.JSONDecodeError):
        return None

def _legacy_archaeology_to_region_stats(
    arch: Mapping[str, Any],
) -> Dict[str, _RegionStats]:
    """Turn a gradient_archaeology results JSON into per-region
    *categorical* aggregates only (the legacy ledger has no margins).

    The archaeology result already aggregates by
    ``per_region_disaggregation.regions[<region_id>].operator_kill_table``,
    keyed ``"<operator>|<kill_pattern>"`` -> count. We translate that
    into per-(region, operator) lists of triggered counts -- treating
    every counted kill as one triggered component (the legacy ledger
    only records the *first* failing falsifier).
    """
    out: Dict[str, _RegionStats] = {}
    prd = arch.get("per_region_disaggregation") or {}
    regions = prd.get("regions") or {}
    for region_id, region_data in regions.items():
        if not isinstance(region_data, dict):
            continue
        meta = _region_meta_from_id(region_id)
        stats = out.setdefault(region_id, _RegionStats(
            region=region_id, region_meta=meta,
        ))
        op_table = region_data.get("operator_kill_table") or {}
        for cell_key, count in op_table.items():
            if not isinstance(cell_key, str) or "|" not in cell_key:
                continue
            try:
                count_int = int(count)
            except (TypeError, ValueError):
                continue
            if count_int <= 0:
                continue
            op, _kp = cell_key.split("|", 1)
            samples = stats.categorical_samples.setdefault(op, [])
            samples.extend([1.0] * count_int)
            stats.has_categorical_data = True
    return out

def _kendall_tau(a: Sequence[str], b: Sequence[str]) -> float:
    """Tau over two orderings of the same set of operators. Returns 0
    on degenerate inputs (n < 2 or no overlap)."""
    common = list(set(a) & set(b))
    if len(common) < 2:
        return 0.0
    rank_a = {x: a.index(x) for x in common}
    rank_b = {x: b.index(x) for x in common}
    n = len(common)
    n_concordant = 0
    n_discordant = 0
    for i in range(n):
        for j in range(i + 1, n):
            x, y = common[i], common[j]
            sa = (rank_a[x] - rank_a[y])
            sb = (rank_b[x] - rank_b[y])
            if sa == 0 or sb == 0:
                continue
            if (sa > 0) == (sb > 0):
                n_concordant += 1
            else:
                n_discordant += 1
    total = n_concordant + n_discordant
    if total == 0:
        return 0.0
    return float(n_concordant - n_discordant) / float(total)

def has_margin_for(self, region: str) -> bool:
    st = self.region_stats.get(region)
    return bool(st and st.has_margin_data)

def has_categorical_for(self, region: str) -> bool:
    st = self.region_stats.get(region)
    return bool(st and st.has_categorical_data)

def _resolve_mode(self, region: str, mode: str) -> Optional[str]:
    if mode == "auto":
        if self.has_margin_for(region):
            return "margin"
        if self.has_categorical_for(region):
            return "categorical"
        return None
    if mode == "margin":
        return "margin" if self.has_margin_for(region) else None
    if mode == "categorical":
        return "categorical" if self.has_categorical_for(region) else None
    raise ValueError(f"unknown mode {mode!r}; must be auto/margin/categorical")

def calibration(
    self,
    *,
    min_episodes: int = DEFAULT_MIN_EPISODES,
) -> Dict[str, Any]:
    """For every region with BOTH margin and categorical data, compare
    the two rankings.

    Output shape::

        {
          "n_eligible_regions": N,
          "n_top1_disagree": k,
          "rows": [
             {"region": ...,
              "margin_top1": "ppo_mlp",
              "categorical_top1": "reinforce_linear",
              "agree_top1": False,
              "kendall_tau": float in [-1, 1],
              "n_common_operators": int,
              "margin_ranking": [...],
              "categorical_ranking": [...]},
             ...
          ],
        }
    """
    rows: List[Dict[str, Any]] = []
    n_top1_disagree = 0
    for region in self.regions:
        st = self.region_stats[region]
        if not (st.has_margin_data and st.has_categorical_data):
            continue
        mr = self.recommend(
            region, mode="margin", top_k=10**6, min_episodes=min_episodes,
        )
        cr = self.recommend(
            region, mode="categorical", top_k=10**6,
            min_episodes=min_episodes,
        )
        if not mr or not cr:
            continue
        common = (
            {r.operator_class for r in mr}
            & {r.operator_class for r in cr}
        )
        if not common:
            continue
        margin_order = [
            r.operator_class for r in mr if r.operator_class in common
        ]
        cat_order = [
            r.operator_class for r in cr if r.operator_class in common
        ]
        agree_top1 = bool(
            margin_order and cat_order and margin_order[0] == cat_order[0]
        )
        if not agree_top1:
            n_top1_disagree += 1
        tau = _kendall_tau(margin_order, cat_order)
        rows.append({
            "region": region,
            "margin_top1": margin_order[0] if margin_order else None,
            "categorical_top1": cat_order[0] if cat_order else None,
            "agree_top1": agree_top1,
            "kendall_tau": tau,
            "n_common_operators": len(common),
            "margin_ranking": margin_order,
            "categorical_ranking": cat_order,
        })
    return {
        "n_eligible_regions": len(rows),
        "n_top1_disagree": n_top1_disagree,
        "rows": rows,
    }

