    ]

def build_feature_matrix(
    entries: Sequence[dict],
    feature_keys: Sequence[str] = FEATURE_KEYS,
) -> np.ndarray:
    """Stack per-entry feature dicts into a (n_entries, n_features) matrix."""
    rows = []
    for entry in entries:
        row = []
        for key in feature_keys:
            val = entry.get(key)
            if val is None or (isinstance(val, float) and math.isnan(val)):
                # NaN guard: replace with 0.0 so clustering doesn't blow up.
                # In practice this should not fire on the 17 entries.
                row.append(0.0)
            else:
                row.append(float(val))
        rows.append(row)
    return np.array(rows, dtype=float)

def characterize_clusters(
    entries: Sequence[dict],
    labels: Sequence[int],
) -> list[dict]:
    """For each cluster, summarise the feature distribution + representatives."""
    cluster_ids = sorted({int(x) for x in labels})
    out = []
    for cid in cluster_ids:
        members = [e for e, lab in zip(entries, labels) if int(lab) == cid]
        n = len(members)
        # Numeric feature stats.
        stats = {}
        for key in FEATURE_KEYS:
            vals = [float(m.get(key, 0.0)) for m in members]
            if vals:
                stats[key] = {
                    "min": float(min(vals)),
                    "max": float(max(vals)),
                    "mean": float(sum(vals) / len(vals)),
                }
            else:
                stats[key] = {"min": None, "max": None, "mean": None}
        # Categorical fields: collect unique values.
        classifications_a = sorted({m.get("classification_a") for m in members})
        classifications_c = sorted({m.get("classification_c") for m in members})
        verdicts_a = sorted({m.get("verdict_a") for m in members})
        failure_modes = sorted({m.get("failure_mode") for m in members})
        # cyclotomic_n_indices: union of all
        all_cyc_ns: set[int] = set()
        for m in members:
            all_cyc_ns.update(m.get("cyclotomic_n_indices", []))
        # Representative: the entry closest to the cluster mean in n_distinct_cyc_idx.
        rep = members[0] if members else None
        out.append({
            "cluster_id": int(cid),
            "size": int(n),
            "feature_stats": stats,
            "classifications_a": [c for c in classifications_a if c is not None],
            "classifications_c": [c for c in classifications_c if c is not None],
            "verdicts_a": [v for v in verdicts_a if v is not None],
            "failure_modes": [f for f in failure_modes if f is not None],
            "cyclotomic_n_index_union": sorted(all_cyc_ns),
            "representative_coeffs_ascending": (
                rep.get("coeffs_ascending") if rep else None
            ),
            "representative_phi_factors_c": (
                rep.get("phi_factors_c") if rep else None
            ),
        })
    return out

def _json_default(o):
    """JSON encoder fallback for numpy scalars."""
    if isinstance(o, np.integer):
        return int(o)
    if isinstance(o, np.floating):
        return float(o)
    if isinstance(o, np.ndarray):
        return o.tolist()
    raise TypeError(f"Object of type {type(o).__name__} is not JSON serialisable")

def descending_to_ascending(desc: Sequence[int]) -> list[int]:
    """Reverse a descending coefficient list to ascending order."""
    return list(reversed([int(c) for c in desc]))

def compute_mahler_batch_descending(coeff_matrix: np.ndarray) -> np.ndarray:
    """Compute Mahler measure for a batch of polynomials in descending form.

    Thin wrapper around ``techne.lib.mahler_measure.mahler_measure_padded``
    that operates on a (n_polys, deg+1) matrix in descending order.

    Returns ndarray of float64 of length n_polys.
    """
    from techne.lib.mahler_measure import mahler_measure_padded

    if coeff_matrix.ndim != 2:
        raise ValueError(
            f"coeff_matrix must be 2-D; got shape {coeff_matrix.shape}"
        )
    return mahler_measure_padded(coeff_matrix.astype(np.complex128))

def total_shards(
    coef_range: tuple[int, int] = DEFAULT_COEF_RANGE,
    c0_positive_only: bool = True,
) -> int:
    """Number of shards for the (c_0, c_1) sharding."""
    lo, hi = int(coef_range[0]), int(coef_range[1])
    inner_count = hi - lo + 1
    if c0_positive_only:
        c0_count = sum(1 for c in range(lo, hi + 1) if c > 0)
    else:
        c0_count = sum(1 for c in range(lo, hi + 1) if c != 0)
    return c0_count * inner_count

def total_subspace_size(
    coef_range: tuple[int, int] = DEFAULT_COEF_RANGE,
    c0_positive_only: bool = True,
) -> int:
    """Number of polynomials in the half-coefficient enumeration."""
    lo, hi = int(coef_range[0]), int(coef_range[1])
    inner_count = hi - lo + 1
    if c0_positive_only:
        c0_count = sum(1 for c in range(lo, hi + 1) if c > 0)
    else:
        c0_count = sum(1 for c in range(lo, hi + 1) if c != 0)
    return c0_count * (inner_count ** 7)

def filter_band_candidates(
    half_coeffs_batch: list[tuple[int, ...]],
    M_values: np.ndarray,
    band_lower: float = 1.0 + 1e-6,
    band_upper: float = DEFAULT_BAND_UPPER,
) -> list[tuple[tuple[int, ...], float]]:
    """Return (half_coeffs, M) pairs strictly inside (band_lower, band_upper).

    The lower bound excludes M = 1 cyclotomic-like polys at numerical
    precision; the upper bound is the +100 Lehmer band cap.
    """
    out: list[tuple[tuple[int, ...], float]] = []
    if len(half_coeffs_batch) != len(M_values):
        raise ValueError(
            f"length mismatch: {len(half_coeffs_batch)} half_coeffs vs "
            f"{len(M_values)} M values"
        )
    for hc, M in zip(half_coeffs_batch, M_values):
        if not np.isfinite(M):
            continue
        m = float(M)
        if band_lower < m < band_upper:
            out.append((hc, m))
    return out

def _check_cyclotomic_factor_via_sympy(
    desc: Sequence[int],
    band_M: float,
) -> tuple[bool, Optional[float]]:
    """Trial-divide by Phi_n for each n with deg(Phi_n) ≤ 14."""
    try:
        import sympy as sp
    except Exception:
        return (False, None)

    x = sp.symbols("x")
    # Build P from descending coeffs: P(x) = c_0 * x^14 + c_1 * x^13 + ...
    deg = len(desc) - 1
    P = sum(int(c) * x ** (deg - i) for i, c in enumerate(desc))
    P_poly = sp.Poly(P, x, domain=sp.ZZ)

    # Try every cyclotomic Phi_n with deg ≤ 14: φ(n) ≤ 14.
    # Sympy: sp.cyclotomic_poly(n, x).
    factored_M: Optional[float] = None
    found = False
    for n in range(1, 200):
        try:
            phi = sp.cyclotomic_poly(n, x)
        except Exception:
            continue
        phi_poly = sp.Poly(phi, x, domain=sp.ZZ)
        if phi_poly.degree() > deg:
            continue
        try:
            quot, rem = sp.div(P_poly, phi_poly, domain=sp.ZZ)
        except Exception:
            continue
        if rem.is_zero:
            found = True
            # Compute M(quot) — could itself still be reducible, but for
            # a one-shot indication we just return its Mahler measure.
            try:
                from techne.lib.mahler_measure import mahler_measure as _mm

                quot_coeffs_desc = quot.all_coeffs()
                quot_coeffs_desc = [int(c) for c in quot_coeffs_desc]
                if len(quot_coeffs_desc) >= 2:
                    factored_M = float(_mm(quot_coeffs_desc))
                else:
                    factored_M = abs(float(quot_coeffs_desc[0])) if quot_coeffs_desc else 1.0
            except Exception:
                factored_M = None
            break
    return (found, factored_M)

def _divisors(n: int) -> list[int]:
    n = abs(int(n))
    if n == 0:
        return []
    out: list[int] = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            out.append(i)
            if i != n // i:
                out.append(n // i)
        i += 1
    return out

def total_shards(
    coef_range: Tuple[int, int],
    c0_positive_only: bool = True,
) -> int:
    """Number of shards (= len of (c0, c1) pairs)."""
    lo, hi = int(coef_range[0]), int(coef_range[1])
    n_inner = hi - lo + 1
    if c0_positive_only:
        n_c0 = sum(1 for c in range(lo, hi + 1) if c > 0)
    else:
        n_c0 = sum(1 for c in range(lo, hi + 1) if c != 0)
    return n_c0 * n_inner

def load_brute_force_results(
    path: str | Path = "prometheus_math/_lehmer_brute_force_results.json",
) -> dict:
    """Load the deg-14 brute-force results JSON.

    Returns the parsed dict. Raises FileNotFoundError if missing.
    """
