def coverage_stats(episodes: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    """Coverage: per-component, what fraction of episodes have non-None margin?"""
    n_total = len(episodes)
    if n_total == 0:
        return {"n_total": 0, "per_component": {}}

    triggered_count: Counter = Counter()
    margin_count: Counter = Counter()
    component_seen: Counter = Counter()
    has_any_margin = 0

    for e in episodes:
        kv = e["kill_vector"]
        any_margin = False
        for c in kv["components"]:
            name = c["falsifier_name"]
            component_seen[name] += 1
            if c["triggered"]:
                triggered_count[name] += 1
            if c["margin"] is not None:
                margin_count[name] += 1
                any_margin = True
        if any_margin:
            has_any_margin += 1

    per_component = {}
    for name in PILOT_COMPONENTS:
        seen = component_seen.get(name, 0)
        per_component[name] = {
            "n_seen": seen,
            "n_triggered": triggered_count.get(name, 0),
            "n_with_margin": margin_count.get(name, 0),
            "triggered_rate": (
                triggered_count.get(name, 0) / seen if seen > 0 else 0.0
            ),
            "margin_coverage": (
                margin_count.get(name, 0) / seen if seen > 0 else 0.0
            ),
        }
    return {
        "n_total": n_total,
        "n_with_any_margin": has_any_margin,
        "fraction_with_any_margin": has_any_margin / max(n_total, 1),
        "per_component": per_component,
    }

def component_distributions(
    episodes: Sequence[Dict[str, Any]],
) -> Dict[str, Dict[str, Any]]:
    """For each component: triggered rate + margin distribution summary
    (mean, median, p25, p75, std, n).  Margins are the RAW values (signed)
    from the KillComponent, not squashed."""
    per_component: Dict[str, Dict[str, Any]] = {}
    for name in PILOT_COMPONENTS:
        per_component[name] = {
            "triggered_margins": [],   # margins on triggered=True only
            "untriggered_margins": [], # margins on triggered=False
            "all_margins": [],
            "all_triggered": [],
        }
    for e in episodes:
        for c in e["kill_vector"]["components"]:
            name = c["falsifier_name"]
            if name not in per_component:
                continue
            m = c["margin"]
            if m is not None and math.isfinite(m):
                per_component[name]["all_margins"].append(float(m))
                if c["triggered"]:
                    per_component[name]["triggered_margins"].append(float(m))
                else:
                    per_component[name]["untriggered_margins"].append(float(m))
            per_component[name]["all_triggered"].append(1.0 if c["triggered"] else 0.0)

    summary: Dict[str, Dict[str, Any]] = {}
    for name, data in per_component.items():
        am = np.asarray(data["all_margins"], dtype=float) if data["all_margins"] else np.zeros(0)
        tm = np.asarray(data["triggered_margins"], dtype=float) if data["triggered_margins"] else np.zeros(0)
        ut = np.asarray(data["untriggered_margins"], dtype=float) if data["untriggered_margins"] else np.zeros(0)
        trig = np.asarray(data["all_triggered"], dtype=float) if data["all_triggered"] else np.zeros(0)
        summary[name] = {
            "n_with_margin": int(am.size),
            "n_triggered_with_margin": int(tm.size),
            "n_untriggered_with_margin": int(ut.size),
            "triggered_rate": float(trig.mean()) if trig.size else 0.0,
            "margin_mean": float(am.mean()) if am.size else None,
            "margin_std": float(am.std()) if am.size else None,
            "margin_median": float(np.median(am)) if am.size else None,
            "margin_p25": float(np.percentile(am, 25)) if am.size else None,
            "margin_p75": float(np.percentile(am, 75)) if am.size else None,
            "margin_min": float(am.min()) if am.size else None,
            "margin_max": float(am.max()) if am.size else None,
            "triggered_margin_mean": float(tm.mean()) if tm.size else None,
            "triggered_margin_std": float(tm.std()) if tm.size else None,
        }
    return summary

def operator_chart_margin_space(
    episodes: Sequence[Dict[str, Any]],
) -> Dict[str, Dict[str, Any]]:
    """For each operator (algorithm), compute E[k | operator] using the
    FULL kill_vector (squashed margins as a [0, 1] kill-strength PER
    component), not just triggered/not."""
    by_op: Dict[str, Dict[str, List[float]]] = defaultdict(lambda: defaultdict(list))
    by_op_triggered: Dict[str, Dict[str, List[float]]] = defaultdict(lambda: defaultdict(list))

    for e in episodes:
        op = e["algorithm"]
        for c in e["kill_vector"]["components"]:
            name = c["falsifier_name"]
            # Squashed margin (the unit-aware kill-strength).
            kc = KillComponent.from_dict(c)
            sq = kc.squashed()
            by_op[op][name].append(float(sq))
            by_op_triggered[op][name].append(1.0 if c["triggered"] else 0.0)

    out: Dict[str, Dict[str, Any]] = {}
    for op, comps in by_op.items():
        e_k = {}
        e_trig = {}
        for name in PILOT_COMPONENTS:
            arr = comps.get(name, [])
            tarr = by_op_triggered[op].get(name, [])
            e_k[name] = float(np.mean(arr)) if arr else 0.0
            e_trig[name] = float(np.mean(tarr)) if tarr else 0.0
        out[op] = {
            "n_episodes": int(sum(len(v) for v in by_op_triggered[op].values()) //
                              max(len(by_op_triggered[op]), 1)),
            "E_k_squashed_per_component": e_k,
            "E_triggered_per_component": e_trig,
        }
    return out

def comparative_distinguishability(
    chart: Dict[str, Dict[str, Any]],
) -> Dict[str, float]:
    """Compute the legacy (categorical/triggered) vs native (squashed)
    operator-chart distinguishability."""
    legacy_kl = kl_divergence_distinguishability(chart, use_squashed=False)
    native_kl = kl_divergence_distinguishability(chart, use_squashed=True)
    gain = native_kl / max(legacy_kl, 1e-12) if legacy_kl > 0 else float("inf")
    return {
        "legacy_avg_pairwise_skl": float(legacy_kl),
        "native_avg_pairwise_skl": float(native_kl),
        "native_over_legacy_ratio": float(gain),
    }

def f6_margin_cluster_analysis(
    episodes: Sequence[Dict[str, Any]],
) -> Dict[str, Any]:
    """For candidates that legacy would have categorically lumped as
    'F6_base_rate killed', what's the distribution of their F6 margin
    z-scores?  Tight cluster = legacy was hiding fine structure.
    """
    margins: List[float] = []
    triggered_margins: List[float] = []
    untriggered_margins: List[float] = []
    for e in episodes:
        for c in e["kill_vector"]["components"]:
            if c["falsifier_name"] != "F6_base_rate":
                continue
            m = c["margin"]
            if m is None or not math.isfinite(m):
                continue
            margins.append(float(m))
            if c["triggered"]:
                triggered_margins.append(float(m))
            else:
                untriggered_margins.append(float(m))
    if not margins:
        return {
            "n": 0, "n_triggered": 0, "n_untriggered": 0,
            "mean": None, "std": None, "unique_values": [],
        }
    arr = np.asarray(margins, dtype=float)
    uniq, counts = np.unique(arr, return_counts=True)
    return {
        "n": int(arr.size),
        "n_triggered": int(len(triggered_margins)),
        "n_untriggered": int(len(untriggered_margins)),
        "mean": float(arr.mean()),
        "std": float(arr.std()),
        "median": float(np.median(arr)),
        "min": float(arr.min()),
        "max": float(arr.max()),
        "unique_values": [
            {"value": float(v), "count": int(c)} for v, c in zip(uniq, counts)
        ][:20],   # cap the histogram for JSON size
        "n_unique_values": int(uniq.size),
        "verdict": (
            "spread"
            if arr.std() > 0.5
            else "tight_cluster_or_bimodal"
        ),
    }

def mpf(x, prec: int = 53):
    """Arbitrary-precision real number.

    Parameters
    ----------
    x : int | float | str | mpmath.mpf | Fraction
        Input value. Strings are recommended for exact decimal literals.
    prec : int
        Working precision in BITS (mpmath convention).
    """
    with workprec(prec):
        if isinstance(x, Fraction):
            return _mpf(x.numerator) / _mpf(x.denominator)
        try:
            return _mpf(x)
        except (TypeError, ValueError) as e:
            raise ValueError(f"cannot construct mpf from {x!r}: {e}")

def pslq(x: Sequence, tol: Optional[float] = None,
         max_coeff: int = 10**6) -> Optional[list[int]]:
    """Find an integer relation among a list of mpmath floats.

    Given x = [x_1, ..., x_n], returns [c_1, ..., c_n] of integers with
    sum(c_i * x_i) ≈ 0, or None if no relation found within bounds.

    Parameters
    ----------
    x : sequence of mpmath floats / numerics
    tol : float, optional
        Tolerance; defaults to mpmath default (~1e-prec).
    max_coeff : int
        Reject relations with |c_i| > max_coeff.
    """
    if not x or len(x) < 2:
        raise ValueError("pslq needs at least 2 inputs")
    try:
        xs = [_mpf(v) if not isinstance(v, (_mpf, _mpc)) else v for v in x]
    except Exception as e:
        raise ValueError(f"pslq inputs must be numeric: {e}")
    try:
        if tol is None:
            rel = mpmath.pslq(xs, maxcoeff=max_coeff)
        else:
            rel = mpmath.pslq(xs, tol=tol, maxcoeff=max_coeff)
    except Exception:
        return None
    if rel is None:
        return None
    rel = [int(c) for c in rel]
    if any(abs(c) > max_coeff for c in rel):
        return None
    if all(c == 0 for c in rel):
        return None
    return rel

def lindep_complex(z, max_deg: int = 8, prec: int = 200) -> Optional[list[int]]:
    """Find an integer-polynomial relation satisfied by complex z.

    Returns coefficients [c_0, c_1, ..., c_d] of a polynomial p with
    p(z) ≈ 0, where d ≤ max_deg, or None if no relation found.

    Tries PARI's `algdep` first (cypari) for robustness; falls back to
    `mpmath.pslq` on [1, z, z^2, ..., z^max_deg].
    """
    if max_deg < 1:
        raise ValueError("max_deg must be >= 1")

    # PARI fast path
    if _HAS_CYPARI:
        try:
            old_prec = _pari.set_real_precision(max(38, int(prec / 3.33)))
            try:
                p = _pari.algdep(complex(z) if not hasattr(z, 'real') else z, max_deg)
            finally:
                _pari.set_real_precision(old_prec)
            # PARI poly -> coefficient list (constant term first)
            coeffs = [int(c) for c in p.Vecrev()]
            if any(coeffs):
                return coeffs
        except Exception:
            pass  # fall through to mpmath

    # mpmath fallback
    with workprec(prec):
        try:
            zc = _mpc(z)
        except Exception as e:
            raise ValueError(f"lindep_complex: bad z={z!r}: {e}")
        powers = [zc**k for k in range(max_deg + 1)]
        # mpmath pslq is real-only; split into [Re(z^k), Im(z^k)] system
        # by stacking: real and imaginary parts must both be 0.
        # Use mpmath's complex-aware version: pslq accepts complex.
        try:
            rel = mpmath.pslq(powers, maxcoeff=10**6)
        except Exception:
            rel = None
        if rel is None:
            return None
        rel = [int(c) for c in rel]
        if all(c == 0 for c in rel):
            return None
        return rel

def gamma(z, prec: int = 53):
    """Gamma function Γ(z) at arbitrary precision (BITS)."""
    with workprec(prec):
        return mpmath.gamma(z)

def beta(a, b, prec: int = 53):
    """Beta function B(a, b) = Γ(a)Γ(b)/Γ(a+b) at arbitrary precision."""
    with workprec(prec):
        return mpmath.beta(a, b)

def bernoulli(n: int) -> Fraction:
    """The n-th Bernoulli number B_n as an exact Fraction.

    Uses sympy if available (exact rational); falls back to mpmath
    (which returns mpf and is then rationalised — accurate but slower).

    Convention: B_1 = -1/2 (sympy convention).
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError(f"bernoulli: n must be a non-negative int, got {n!r}")
    if _HAS_SYMPY:
        b = _sympy.bernoulli(n)
        return Fraction(b.p, b.q) if hasattr(b, 'p') else Fraction(b)
    # mpmath fallback at high precision, then rationalise
    with workprec(max(64, 8 * n)):
        v = mpmath.bernoulli(n)
        # Rationalise via mpmath.identify isn't reliable; convert via str.
        return Fraction(str(v)).limit_denominator(10**18)

def _require_flint(op: str) -> None:
    if not _HAS_FLINT:
        raise ImportError(
            f"prometheus_math.numerics.{op} requires python-flint; "
            "install via `pip install python-flint`"
        )

def _is_prime_int(p: int) -> bool:
    """Trial-division primality test for small p; sympy fast path if avail."""
    if not isinstance(p, int) or p < 2:
        return False
    if _HAS_SYMPY:
        return bool(_sympy.isprime(p))
    if p < 4:
        return p in (2, 3)
    if p % 2 == 0 or p % 3 == 0:
        return False
    i = 5
    while i * i <= p:
        if p % i == 0 or p % (i + 2) == 0:
            return False
        i += 6
    return True

def _check_prime(p: int, op: str) -> None:
    if not isinstance(p, int):
        raise ValueError(f"{op}: modulus must be an int, got {type(p).__name__}")
    if p < 2:
        raise ValueError(f"{op}: modulus must be >= 2, got {p}")
    if not _is_prime_int(p):
        raise ValueError(f"{op}: modulus {p} is not prime; FLINT mod-p ops require a prime modulus")

def _strip_trailing_zero_coeffs(coeffs):
    out = list(coeffs)
    while len(out) > 1 and out[-1] == 0:
        out.pop()
    return out

def _validate_matrix(M, op: str) -> tuple[int, int]:
    if M is None:
        raise ValueError(f"{op}: matrix is None")
    try:
        rows = list(M)
    except TypeError:
        raise ValueError(f"{op}: matrix is not iterable")
    if not rows:
        raise ValueError(f"{op}: matrix has zero rows")
    nrows = len(rows)
    ncols = len(rows[0]) if rows[0] is not None else 0
    if ncols == 0:
        raise ValueError(f"{op}: matrix has zero columns")
    for r in rows:
        if len(r) != ncols:
            raise ValueError(f"{op}: matrix is jagged (row lengths differ)")
    return nrows, ncols

def _to_nmod_mat(M, p: int):
    rows = [[int(x) % p for x in r] for r in M]
    return _flint.nmod_mat(rows, p)

def _validate_dft_args(x, prec: int, op: str) -> None:
    if not isinstance(prec, int) or prec < 1:
        raise ValueError(f"{op}: prec must be a positive int, got {prec!r}")
    if x is None:
        raise ValueError(f"{op}: input is None")
    try:
        n = len(x)
    except TypeError:
        raise ValueError(f"{op}: input must be a sequence, got {type(x).__name__}")
    if n == 0:
        raise ValueError(f"{op}: input is empty; DFT requires at least one sample")

def _coerce_mpc_seq(x) -> list:
    """Convert each element of x to mpmath.mpc at the active precision."""
    out = []
    for v in x:
        if isinstance(v, _mpc):
            out.append(v)
        elif isinstance(v, _mpf):
            out.append(_mpc(v, 0))
        elif isinstance(v, complex):
            out.append(_mpc(v.real, v.imag))
        else:
            # int, float, Fraction, str
            try:
                if isinstance(v, Fraction):
                    out.append(_mpc(_mpf(v.numerator) / _mpf(v.denominator), 0))
                else:
                    out.append(_mpc(v, 0))
            except Exception as e:
                raise ValueError(f"DFT: cannot coerce element {v!r} to mpc: {e}")
    return out

def _next_pow2(n: int) -> int:
    if n < 1:
        return 1
    p = 1
    while p < n:
        p <<= 1
    return p

def _bit_reverse_permute(a: list) -> list:
    """In-place bit-reversal permutation for radix-2 FFT."""
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    return a

def _validate_prec(prec: Optional[int], op: str) -> Optional[int]:
    if prec is None:
        return None
    if not isinstance(prec, int):
        raise ValueError(f"{op}: prec must be int or None, got {type(prec).__name__}")
    if prec < 1:
        raise ValueError(f"{op}: prec must be >= 1, got {prec}")
    return prec

def _to_complex(z: _NumberLike) -> complex:
    """Coerce a number-like to a Python `complex`. Accepts mpmath types."""
    if isinstance(z, complex):
        return z
    if isinstance(z, (_mpf, _mpc)):
        # mpmath types convert via their `complex()` cast
        return complex(z)
    if isinstance(z, (int, float)):
        return complex(z)
    # last-ditch: try float
    return complex(float(z))

def _is_real_input(z: _NumberLike) -> bool:
    if isinstance(z, (int, float)):
        return True
    if isinstance(z, _mpf):
        return True
    if isinstance(z, complex):
        return z.imag == 0
    if isinstance(z, _mpc):
        return z.imag == 0
    return False

def _mpmath_polylog(n: int, z: _NumberLike, prec: int):
    """Evaluate Li_n(z) via mpmath at the requested precision in BITS."""
    with workprec(prec):
        if isinstance(z, (_mpf, _mpc)):
            zz = z
        elif isinstance(z, complex):
            zz = _mpc(z.real, z.imag)
        else:
            zz = z  # int/float — mpmath accepts directly
        return mpmath.polylog(n, zz)

def polylogarithm(n: int, z: _NumberLike, prec: Optional[int] = None):
    """Polylogarithm Li_n(z) for integer n.

    For n >= 1 this is the analytic continuation of
    sum_{k >= 1} z^k / k^n. Special closed forms used directly:

      - Li_0(z) = z / (1 - z)
      - Li_1(z) = -log(1 - z)
      - Li_2(z) = dilogarithm(z)

    Parameters
    ----------
    n : int
        Order. Must be an integer; n >= 0.
    z : int | float | complex | mpmath types
    prec : int, optional
        Precision in BITS. None -> default mpmath precision (~53).

    Returns
    -------
    complex or mpmath.mpc.

    Raises
    ------
    ValueError
        If n is not an int, n < 0, or (n == 0 and z == 1) which is the
        pole of Li_0.
    """
    if not isinstance(n, int):
        raise ValueError(f"polylogarithm: n must be int, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"polylogarithm: n must be >= 0, got {n}")
    prec = _validate_prec(prec, "polylogarithm")

    # Closed-form fast paths
    if n == 0:
        zc = _to_complex(z)
        if zc == 1:
            raise ValueError("polylogarithm: Li_0(1) is a pole (z/(1-z) diverges)")
        if prec is None:
            return zc / (1 - zc)
        with workprec(prec):
            zz = _mpc(zc.real, zc.imag)
            return zz / (_mpc(1, 0) - zz)

    if n == 1:
        zc = _to_complex(z)
        if zc == 1:
            raise ValueError("polylogarithm: Li_1(1) is a pole (-log(1-1) diverges)")
        if prec is None:
            # cmath.log on a real positive argument returns complex with imag=0;
            # this preserves analytic continuity for real z < 1.
            return -cmath.log(1 - zc)
        with workprec(prec):
            return -mpmath.log(_mpc(1, 0) - _mpc(zc.real, zc.imag))

    # General path: dispatch n == 2 to dilogarithm for fast scipy path.
    if n == 2:
        return dilogarithm(z, prec=prec)

    # n >= 3: mpmath only.
    eff_prec = prec if prec is not None else 53
    val = _mpmath_polylog(n, z, eff_prec)
    if prec is None:
        return complex(val)
    return val

def _resolve_prec(prec: Optional[int]) -> int:
    """Return the working precision in BITS.

    Mirrors the convention used elsewhere in
    ``prometheus_math.numerics_special_*``.
    """
    if prec is None:
        return mp.prec
    if not isinstance(prec, int) or prec < 1:
        raise ValueError(f"prec must be an int >= 1, got {prec!r}")
    return prec

def _to_mpc(z: Numeric) -> _mpc:
    """Coerce a numeric to mpmath mpc (complex)."""
    if isinstance(z, _mpc):
        return z
    if isinstance(z, _mpf):
        return _mpc(z, 0)
    if isinstance(z, complex):
        return _mpc(z.real, z.imag)
    return _mpc(z, 0)

def _q_of_tau(tau: _mpc) -> _mpc:
    """Return q = exp(2πiτ).  |q| = exp(-2π Im τ) < 1."""
    return mpmath.exp(2 * mpmath.pi * 1j * tau)

def _sigma_k(n: int, k: int) -> int:
    """Divisor power-sum σ_k(n) = Σ_{d | n} d^k.  Used for Eisenstein."""
    if n <= 0:
        return 0
    s = 0
    for d in range(1, n + 1):
        if n % d == 0:
            s += d ** k
    return s

def _check_prec(prec: Optional[int]) -> None:
    """prec must be None or a positive int >= 1."""
    if prec is None:
        return
    if not isinstance(prec, int) or prec < 1:
        raise ValueError(f"prec must be None or a positive int >= 1, got {prec!r}")

def _to_real_or_none(x):
    """Return real(x) as float if x is purely real, else None."""
    if isinstance(x, complex):
        if x.imag == 0:
            return float(x.real)
        return None
    if isinstance(x, mpmath.mpc):
        if x.imag == 0:
            return float(x.real)
        return None
    try:
        return float(x)
    except (TypeError, ValueError):
        return None

def _to_mp(z) -> Union[_mpf, _mpc]:
    """Coerce a numeric to mpmath mpf/mpc."""
    if isinstance(z, (_mpf, _mpc)):
        return z
    if isinstance(z, complex):
        if z.imag == 0:
            return _mpf(z.real)
        return _mpc(z)
    return _mpf(z)

def _validate_n(n: int) -> int:
    """Ensure n is one of {1, 2, 3, 4} (the four Jacobi theta indices)."""
    if not isinstance(n, (int,)):
        raise ValueError(
            f"theta index n must be an int in {{1,2,3,4}}, got {type(n).__name__}"
        )
    if n not in (1, 2, 3, 4):
        raise ValueError(
            f"theta index n must be in {{1,2,3,4}}, got {n}"
        )
    return n

def _coerce_z(z) -> _mpc:
    """Coerce a scalar z (int/float/complex/mpc) to mpc."""
    return _mpc(z)

def _resolve_prec(prec: Optional[int]) -> int:
    """Return the working precision in bits.

    If ``prec`` is None, fall back to ``mp.prec`` (the ambient mpmath
    precision). Otherwise use the explicit value.
    """
    if prec is None:
        return mp.prec
    if not isinstance(prec, int) or prec <= 0:
        raise ValueError(f"prec must be a positive int, got {prec!r}")
    return prec

def _validate_z_vector(z, g: int) -> list:
    """Coerce z to a g-vector of mpc."""
    if hasattr(z, "rows") and hasattr(z, "cols"):
        if z.cols == 1:
            zlist = [z[i, 0] for i in range(z.rows)]
        elif z.rows == 1:
            zlist = [z[0, j] for j in range(z.cols)]
        else:
            raise ValueError(
                f"Riemann theta: z must be a g-vector, got matrix {z.rows}x{z.cols}"
            )
    else:
        try:
            zlist = list(z)
        except TypeError as e:
            raise ValueError(f"Riemann theta: cannot interpret z as vector: {e}")
    if len(zlist) != g:
        raise ValueError(
            f"Riemann theta: z must have length g={g}, got length {len(zlist)}"
        )
    return [_mpc(v) for v in zlist]

