def _qp_cvxpy(P, q, G, h, A_eq, b_eq, lb, ub, verbose) -> dict:
    import cvxpy as cp

    n = P.shape[0]
    x = cp.Variable(n)
    # cvxpy's quad_form requires PSD (it checks). We've already validated.
    objective = cp.Minimize(0.5 * cp.quad_form(x, cp.psd_wrap(P)) + q @ x)
    cons = []
    if G is not None:
        cons.append(G @ x <= h)
    if A_eq is not None:
        cons.append(A_eq @ x == b_eq)
    if lb is not None:
        mask = np.isfinite(lb)
        if mask.any():
            cons.append(x[mask] >= lb[mask])
    if ub is not None:
        mask = np.isfinite(ub)
        if mask.any():
            cons.append(x[mask] <= ub[mask])
    prob = cp.Problem(objective, cons)
    try:
        prob.solve(verbose=verbose)
    except cp.error.SolverError as exc:  # pragma: no cover
        return {
            "x": None,
            "optimal_value": None,
            "status": f"solver_error: {exc}",
            "solver_used": "cvxpy",
            "n_iter": None,
        }
    status = str(prob.status)
    if status in ("optimal", "optimal_inaccurate"):
        x_val = np.asarray(x.value, dtype=float)
        val = float(prob.value)
    else:
        x_val = None
        val = None
    n_iter = None
    try:
        stats = prob.solver_stats
        if stats is not None and stats.num_iters is not None:
            n_iter = int(stats.num_iters)
    except Exception:
        pass
    return {
        "x": x_val,
        "optimal_value": val,
        "status": status,
        "solver_used": "cvxpy",
        "n_iter": n_iter,
    }

def _qp_scipy(P, q, G, h, A_eq, b_eq, lb, ub, verbose) -> dict:
    from scipy.optimize import minimize

    n = P.shape[0]

    def f(x):
        return 0.5 * x @ P @ x + q @ x

    def grad(x):
        return P @ x + q

    constraints = []
    if G is not None:
        constraints.append(
            {"type": "ineq", "fun": lambda x, G=G, h=h: h - G @ x,
             "jac": lambda x, G=G: -G}
        )
    if A_eq is not None:
        constraints.append(
            {"type": "eq", "fun": lambda x, A=A_eq, b=b_eq: A @ x - b,
             "jac": lambda x, A=A_eq: A}
        )
    bounds = None
    if lb is not None or ub is not None:
        lb_arr = lb if lb is not None else np.full(n, -np.inf)
        ub_arr = ub if ub is not None else np.full(n, np.inf)
        bounds = list(zip(
            [None if not np.isfinite(v) else float(v) for v in lb_arr],
            [None if not np.isfinite(v) else float(v) for v in ub_arr],
        ))
    x0 = np.zeros(n)
    if bounds is not None:
        # Project x0 into box.
        for i, (lo, hi) in enumerate(bounds):
            if lo is not None and x0[i] < lo:
                x0[i] = lo
            if hi is not None and x0[i] > hi:
                x0[i] = hi
    res = minimize(
        f, x0, jac=grad, method="SLSQP",
        constraints=constraints if constraints else (),
        bounds=bounds,
        options={"disp": verbose, "maxiter": 200, "ftol": 1e-9},
    )
    success = bool(res.success)
    status = "optimal" if success else (str(res.message) or "unknown")
    return {
        "x": np.asarray(res.x, dtype=float) if success else None,
        "optimal_value": float(res.fun) if success else None,
        "status": status if success else status,
        "solver_used": "scipy",
        "n_iter": int(getattr(res, "nit", 0) or 0),
    }

def solve_box_qp(P, q, lb, ub, solver: str = "cvxpy") -> dict:
    """Box-constrained QP: ``min (1/2) x^T P x + q^T x`` s.t. ``lb <= x <= ub``.

    Convenience wrapper around :func:`solve_qp` with no general
    inequality / equality constraints.
    """
    return solve_qp(P, q, lb=lb, ub=ub, solver=solver)

def _validate_solver(cp, solver: str) -> str:
    """Return the cvxpy solver string after validating availability."""
    avail = cp.installed_solvers()
    if solver not in avail:
        raise ValueError(
            f"Solver {solver!r} is not available in this cvxpy build. "
            f"Installed solvers: {avail}.  "
            f"For SDP, SCS is the standard open-source default."
        )
    return solver

def _ensure_2d_array(M, name: str) -> np.ndarray:
    arr = np.asarray(M, dtype=float)
    if arr.ndim != 2:
        raise ValueError(f"{name} must be a 2-D matrix; got shape {arr.shape}")
    return arr

def _check_n(n) -> int:
    if not isinstance(n, (int, np.integer)) or n <= 0:
        raise ValueError(f"n must be a positive integer; got {n!r}")
    return int(n)

def _normalize_constraints(
    A_list: Optional[Iterable], b_list: Optional[Iterable], n: int, name: str
) -> Tuple[List[np.ndarray], List[float]]:
    if A_list is None:
        A_list = []
    if b_list is None:
        b_list = []
    A_arrs: List[np.ndarray] = []
    for k, A_k in enumerate(A_list):
        A_arr = _ensure_2d_array(A_k, f"{name}[{k}]")
        if A_arr.shape != (n, n):
            raise ValueError(
                f"{name}[{k}] has shape {A_arr.shape}, expected ({n}, {n})")
        A_arrs.append(_symmetrize(A_arr))
    b_arrs: List[float] = [float(x) for x in b_list]
    if len(A_arrs) != len(b_arrs):
        raise ValueError(
            f"length mismatch: {len(A_arrs)} {name} matrices vs "
            f"{len(b_arrs)} rhs values")
    return A_arrs, b_arrs

def _check_solver(solver: str) -> str:
    if solver not in _KNOWN_SOLVERS:
        raise ValueError(
            f"Unknown solver {solver!r}; choose from {sorted(_KNOWN_SOLVERS)}"
        )
    return solver

def _as_vec(v, name: str) -> np.ndarray:
    arr = np.asarray(v, dtype=float).ravel()
    return arr

def _as_mat(M, name: str) -> np.ndarray:
    arr = np.asarray(M, dtype=float)
    if arr.ndim == 1:
        arr = arr.reshape(1, -1)
    if arr.ndim != 2:
        raise ValueError(f"{name} must be 2-D; got shape {arr.shape}")
    return arr

def _extract_n_iter(prob) -> Optional[int]:
    try:
        if prob.solver_stats is not None and prob.solver_stats.num_iters is not None:
            return int(prob.solver_stats.num_iters)
    except Exception:
        pass
    return None

def run_densification(
    cells: Sequence[RegionCell] = DEFAULT_REGION_CELLS,
    n_episodes_per_cell: int = 1000,
    seeds: Tuple[int, ...] = (0, 1, 2),
    algorithms: Tuple[str, ...] = (
        "random_uniform", "reinforce_linear", "ppo_mlp", "ga_elitist_v2",
    ),
    *,
    progress: bool = True,
) -> Dict[str, Any]:
    """Run native KillVector pilots on multiple region cells.

    Returns a dict with the same shape as ``run_pilot`` from
    ``native_kill_vector_pilot`` so the navigator can consume both:

      * meta: setup
      * episodes: list[EpisodeKillVector.to_dict()]
      * cell_summary: {(cell_id, algo, seed): {n, n_pipeline_routed, ...}}
      * elapsed_s: total wall time
    """
    t_global = time.perf_counter()
    all_episodes: List[EpisodeKillVector] = []
    cell_summary: Dict[str, Dict[str, Any]] = {}
    skipped: List[str] = []

    for cell in cells:
        for algo in algorithms:
            if algo not in CELL_ALGORITHM_RUNNERS:
                raise ValueError(f"unknown algorithm {algo!r}")
            runner = CELL_ALGORITHM_RUNNERS[algo]
            for s in seeds:
                t0 = time.perf_counter()
                key = f"{cell.cell_id}|{algo}@seed={s}"
                if progress:
                    print(
                        f"[densify] {key} (target={n_episodes_per_cell} eps)...",
                        flush=True,
                    )
                try:
                    eps = runner(cell, n_episodes_per_cell, int(s))
                except Exception as e:
                    if progress:
                        print(
                            f"  ERROR in {key}: {type(e).__name__}: {e!r}",
                            flush=True,
                        )
                    skipped.append(f"{key}: {type(e).__name__}")
                    eps = []
                elapsed = time.perf_counter() - t0
                n_pipeline = sum(
                    1 for e in eps if e.pipeline_terminal_state is not None
                )
                cell_summary[key] = {
                    "cell_id": cell.cell_id,
                    "algorithm": algo,
                    "seed": int(s),
                    "n_episodes": len(eps),
                    "n_pipeline_routed": n_pipeline,
                    "elapsed_s": elapsed,
                    "skipped": len(eps) == 0 and n_episodes_per_cell > 0,
                }
                all_episodes.extend(eps)
                if progress:
                    print(
                        f"  -> {len(eps)} eps, {n_pipeline} pipeline-routed,"
                        f" {elapsed:.1f}s ({len(eps)/max(elapsed,1e-9):.1f} eps/s)",
                        flush=True,
                    )

    elapsed = time.perf_counter() - t_global
    return {
        "meta": {
            "n_episodes_per_cell": int(n_episodes_per_cell),
            "seeds": list(seeds),
            "algorithms": list(algorithms),
            "cells": [
                {
                    "cell_id": c.cell_id,
                    "degree": c.degree,
                    "alphabet_width": c.alphabet_width,
                    "alphabet_size": c.alphabet_size,
                    "reward_shape": c.reward_shape,
                }
                for c in cells
            ],
            "pilot_components": list(PILOT_COMPONENTS),
        },
        "episodes": [e.to_dict() for e in all_episodes],
        "cell_summary": cell_summary,
        "skipped": skipped,
        "elapsed_s": float(elapsed),
        "total_episodes": len(all_episodes),
    }

def compare_with_baseline(
    densification_margins: Dict[str, Dict[str, Any]],
    baseline_pilot_path: Optional[str] = None,
) -> Dict[str, Any]:
    """Compare per-region top operator vs the deg14 ±5 step native baseline.

    Loads the existing ``_native_kill_vector_pilot.json`` if present and
    computes its top operator per region.  Reports whether the same
    operator wins everywhere (verdict A) or whether different cells
    have different winners (verdict B), or whether margins overlap so
    much per cell that no clear winner emerges (verdict C).
    """
    if baseline_pilot_path is None:
        baseline_pilot_path = (
            Path(__file__).parent / "_native_kill_vector_pilot.json"
        )
    baseline_pilot_path = Path(baseline_pilot_path)
    baseline_top: Dict[str, str] = {}
    if baseline_pilot_path.exists():
        try:
            blob = json.loads(baseline_pilot_path.read_text(encoding="utf-8"))
            baseline_pilot = blob.get("pilot", {})
            baseline_margins = per_region_operator_margins(baseline_pilot)
            for r, info in baseline_margins.items():
                if info.get("top_operator"):
                    baseline_top[r] = info["top_operator"]
        except Exception:
            pass

    densification_top: Dict[str, str] = {}
    for r, info in densification_margins.items():
        if info.get("top_operator"):
            densification_top[r] = info["top_operator"]

    # Did the same operator win in every densification region?
    densification_winners = set(densification_top.values())
    same_op_everywhere = len(densification_winners) == 1

    # CI overlap test: in any densification region, does the top
    # operator's CI overlap with the runner-up's CI?
    n_overlapping = 0
    n_with_clear = 0
    for r, info in densification_margins.items():
        ranked = info.get("ranking") or []
        ops = info.get("operators") or {}
        if len(ranked) < 2:
            continue
        top, second = ranked[0], ranked[1]
        top_hi = ops[top]["ci_high"]
        second_lo = ops[second]["ci_low"]
        if top_hi >= second_lo:
            n_overlapping += 1
        else:
            n_with_clear += 1

    # Verdict
    if same_op_everywhere and len(densification_winners) > 0:
        verdict_letter = "A"
        verdict_text = (
            "PPO/single-operator wins everywhere -> operator hierarchy is"
            " region-invariant despite Stream 2's region-info finding."
        )
    elif len(densification_winners) >= 2:
        verdict_letter = "B"
        verdict_text = (
            "Different operators win in different regions -> region-specific"
            " gradient field structure confirmed; navigator's region"
            " conditioning is empirically meaningful."
        )
    else:
        verdict_letter = "C"
        verdict_text = "No densification regions had a top operator."

    if n_overlapping > n_with_clear and n_overlapping > 0:
        verdict_letter = "C"
        verdict_text = (
            f"In {n_overlapping}/{n_overlapping + n_with_clear} regions, the"
            " top operator's CI overlaps the runner-up's CI.  Margins"
            " distinguish operators on average but the 1K-episode budget"
            " produces wide CIs; navigator is operationally useful but"
            " per-region recommendations are uncertain."
        )

    return {
        "densification_top_per_region": densification_top,
        "baseline_top_per_region": baseline_top,
        "same_operator_everywhere_in_densification": same_op_everywhere,
        "n_distinct_top_operators": len(densification_winners),
        "n_regions_with_overlapping_top_ci": n_overlapping,
        "n_regions_with_clear_top_winner": n_with_clear,
        "verdict": verdict_letter,
        "verdict_text": verdict_text,
    }

