def _objective_minimize_mahler_measure(
    eval_result: Any,
    args: Tuple[Any, ...],
    arg_label: str,
) -> Tuple[float, bool]:
    """Reward for finding low-M reciprocal polys.

    Returns (reward, hit_target).

    Reward shape:
    - +1.0 for any M finite in [1, 5)
    - +5.0 if M < 2.0
    - +20.0 if M < 1.5 (Lehmer-territory)
    - +100.0 if M < 1.18 (sub-Lehmer; would be a real find)
    - 0.0 otherwise (NaN, M>=5, etc.)
    """
    try:
        m = float(eval_result)
    except (TypeError, ValueError):
        return 0.0, False
    if not math.isfinite(m):
        return 0.0, False
    if m < 1.0 - 1e-9:
        # Reciprocal poly with M < 1 should not exist; numerical artifact.
        return 0.0, False
    hit = m < 1.18
    if m < 1.18:
        return 100.0, True
    if m < 1.5:
        return 20.0, False
    if m < 2.0:
        return 5.0, False
    if m < 5.0:
        return 1.0, False
    return 0.0, False

def _objective_riemann_zeros(
    eval_result: Any,
    args: Tuple[Any, ...],
    arg_label: str,
) -> Tuple[float, bool]:
    """Reward for evaluating Li_2 close to known reference values."""
    try:
        v = complex(eval_result)
    except (TypeError, ValueError):
        return 0.0, False
    target = math.pi * math.pi / 6.0
    if not args:
        return 0.0, False
    try:
        z = float(args[0])
    except (TypeError, ValueError):
        return 0.0, False
    if abs(z - 1.0) < 1e-9 and abs(v.real - target) < 1e-6 and abs(v.imag) < 1e-6:
        return 50.0, True
    if abs(z) < 1e-9 and abs(v) < 1e-9:
        return 5.0, False
    return 1.0, False

def register_with_gymnasium() -> Optional[str]:
    """Register ``"prometheus/SigmaMath-v0"`` with gymnasium.

    Returns the env_id on success, ``None`` if gymnasium isn't installed.
    """
    try:
        import gymnasium as gym
    except ImportError:
        return None
    env_id = "prometheus/SigmaMath-v0"
    try:
        gym.register(
            id=env_id,
            entry_point="prometheus_math.sigma_env:SigmaMathEnv",
        )
    except Exception:
        # Already registered or gymnasium changed signature; ignore.
        pass
    return env_id

def step(self, action: int) -> Tuple[np.ndarray, float, bool, bool, Dict[str, Any]]:
    if self._kernel is None or self._ext is None:
        raise RuntimeError("env.step() called before env.reset()")
    if action < 0 or action >= len(self._actions):
        raise ValueError(
            f"action {action} out of range [0, {len(self._actions)})"
        )
    row = self._actions[action]
    cap = self._kernel.mint_capability("EvalCap")

    truncated = False
    info: Dict[str, Any] = {
        "callable_ref": row.callable_ref,
        "arg_label": row.arg_label,
        "step": self._step_count,
    }
    try:
        ev = self._ext.EVAL(
            binding_name=row.binding_name,
            binding_version=row.binding_version,
            args=list(row.args),
            kwargs=row.kwargs,
            cap=cap,
            eval_version=self._step_count + 1,
        )
    except BudgetExceeded as e:
        self._step_count += 1
        self._last_reward = -1.0
        info["error"] = f"budget_exceeded: {e}"
        terminated = self._step_count >= self.max_steps
        return self._obs(), -1.0, terminated, False, info

    # Parse the output back from repr(); for the Lehmer objective the
    # output is a float so eval(repr(x)) round-trips. For richer
    # objectives we'd need a structured channel.
    try:
        output_value: Any = eval(ev.output_repr, {"__builtins__": {}}, {})
    except Exception:
        output_value = ev.output_repr

    reward, hit_target = self._objective_fn(
        output_value, row.args, row.arg_label
    )
    self._n_total += 1
    if ev.success:
        self._n_success += 1
    self._last_reward = float(reward)
    if reward > self._best_reward:
        self._best_reward = float(reward)
    if isinstance(output_value, (int, float)) and math.isfinite(output_value):
        v = float(output_value)
        if (
            self.objective_name == "minimize_mahler_measure"
            and v >= 1.0
            and (self._best_value is None or v < self._best_value)
        ):
            self._best_value = v

    self._step_count += 1
    terminated = bool(hit_target) or self._step_count >= self.max_steps
    info.update(
        {
            "output_value": output_value,
            "reward_breakdown": {
                "magnitude": float(reward),
                "hit_target": bool(hit_target),
            },
            "actual_cost": ev.actual_cost,
            "n_success": self._n_success,
            "n_total": self._n_total,
        }
    )
    self._last_terminated = terminated
    return self._obs(), float(reward), terminated, truncated, info

def _obs(self) -> np.ndarray:
    best_val = self._best_value if self._best_value is not None else -1.0
    return np.array(
        [
            float(self._step_count),
            float(self._n_success),
            float(self._n_total),
            float(self._last_reward),
            float(best_val),
        ],
        dtype=np.float64,
    )

def action_table(self) -> List[ActionRow]:
    """Return the live action table (after reset)."""
    return list(self._actions)

def kernel(self) -> SigmaKernel:
    """Return the underlying kernel (after reset). Useful for tests."""
    if self._kernel is None:
        raise RuntimeError("env not reset yet")
    return self._kernel

def __init__(self, shape):
    self.shape = tuple(shape)
    self.dtype = np.float64

def sample(self) -> int:
    if self.n <= 0:
        raise RuntimeError("action_space empty (call reset() first)")
    return random.randrange(self.n)

def _summarize_run(
    rewards: np.ndarray,
    n_terminations: int,
    best_value: Optional[float],
    extras: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Standard return shape for all training fns."""
    rewards = np.asarray(rewards, dtype=np.float64)
    if rewards.size == 0:
        mean_r = 0.0
        mean_per_ep = 0.0
    else:
        mean_r = float(rewards.mean())
        mean_per_ep = (
            float(rewards.sum() / max(1, n_terminations))
            if n_terminations > 0
            else float(rewards.sum())
        )
    out = {
        "rewards": rewards,
        "mean_reward": mean_r,
        "mean_reward_per_episode": mean_per_ep,
        "n_terminations": int(n_terminations),
        "best_value": float(best_value) if best_value is not None else None,
        "n_steps": int(rewards.size),
    }
    if extras:
        out.update(extras)
    return out

def _track_best(
    info: Dict[str, Any], best_value: Optional[float]
) -> Optional[float]:
    """Track minimum-Mahler (or other) finite output across an episode."""
    v = info.get("output_value")
    try:
        v = float(v)
    except (TypeError, ValueError):
        return best_value
    if not math.isfinite(v) or v < 1.0 - 1e-9:
        return best_value
    if best_value is None or v < best_value:
        return v
    return best_value

def _softmax(logits: np.ndarray) -> np.ndarray:
    z = logits - logits.max()
    e = np.exp(z)
    return e / e.sum()

def _gym_env_base() -> Any:
    """Resolve gymnasium.Env at import-or-call time so the wrappers can
    inherit from it when SB3 / gymnasium are present, and fall back to
    object when they are not.
    """
    try:
        import gymnasium as gym  # noqa: F401

        return gym.Env
    except ImportError:
        return object

def _make() -> Any:
    env = env_factory()
    # Auto-reset on termination is needed for a continuous step count.
    return _AutoResetWrapper(Monitor(_GymCompatWrapper(env)))

def step(self, action):
    obs, r, term, trunc, info = self._env.step(action)
    if term or trunc:
        obs, _ = self._env.reset()
    return obs, r, term, trunc, info

def _smooth(x: np.ndarray, w: int) -> np.ndarray:
    if w <= 1 or x.size <= w:
        return x
    kernel = np.ones(w, dtype=np.float64) / w
    return np.convolve(x, kernel, mode="same")

def _coerce_k(k: Any) -> int:
    """Tolerate KTier or raw int; coerce to int."""
    if isinstance(k, KTier):
        return int(k.value)
    try:
        return int(k)
    except (TypeError, ValueError):
        return int(KTier.DIAGNOSTIC.value)

def _seeded_rng(seed: int) -> Any:
    """Cheap deterministic float-generator shim (no numpy dependency)."""
    import random
    return random.Random(seed)

def stability_numeric_margin(
    margin: float,
    precision_dps: Optional[int],
    *,
    k: int = KTier.DIAGNOSTIC,
    falsifier_callable: Optional[Callable[[float], bool]] = None,
    seed: int = 0,
) -> StabilityResult:
    """Stability via epsilon-perturbation of a numeric margin.

    ``epsilon = 10^-(precision_dps - 2)`` per substrate v2.3 §6.2; if
    ``precision_dps`` is None we fall back to ``epsilon = 1e-12``
    (numpy double precision floor with two-digit safety margin).

    The ``falsifier_callable`` receives the *perturbed* margin and
    returns True iff the falsifier still kills (matching the
    unperturbed verdict). When ``None``, returns NaN-filled result.
    """
    k_used = _coerce_k(k)
    ftype = FalsifierType.NUMERIC_MARGIN.value
    if precision_dps is not None:
        # Floor at dps=2 → epsilon = 1.0 doesn't make sense; clamp.
        try:
            dps = max(3, int(precision_dps))
        except (TypeError, ValueError):
            dps = 14
        epsilon = 10.0 ** (-(dps - 2))
    else:
        epsilon = 1e-12
    family = f"epsilon={epsilon:g}"

    if falsifier_callable is None:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:no_callable")

    # Reference verdict at the unperturbed margin.
    try:
        ref = bool(falsifier_callable(float(margin)))
    except Exception:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:ref_failed")

    rng = _seeded_rng(seed)
    outcomes = []
    for _ in range(k_used):
        delta = rng.uniform(-epsilon, epsilon)
        try:
            v = bool(falsifier_callable(float(margin) + delta))
        except Exception:
            outcomes.append(0.0)
            continue
        outcomes.append(1.0 if v == ref else 0.0)
    return _aggregate_outcomes(outcomes, ftype, family, k_used)

def stability_graph_metric(
    graph_data: Any,
    *,
    k: int = KTier.DIAGNOSTIC,
    metric_callable: Optional[Callable[[Any], Any]] = None,
    edge_perturbation_rate: float = 0.05,
    seed: int = 0,
) -> StabilityResult:
    """Stability via edge perturbation / sampling perturbation.

    ``metric_callable(perturbed_graph)`` returns a verdict; agreement
    across k perturbations measures edge-perturbation stability.

    For the substrate's smoke-test path, ``graph_data`` is treated
    opaquely. Real callers should pass a graph with an ``.edges``
    iterator and a perturbation function; the adapter applies a
    ``edge_perturbation_rate``-fraction Bernoulli edge dropout per
    perturbation.
    """
    k_used = _coerce_k(k)
    ftype = FalsifierType.GRAPH_METRIC.value
    family = f"edge_dropout={edge_perturbation_rate:g}"

    if metric_callable is None:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:no_callable")

    try:
        ref = metric_callable(graph_data)
    except Exception:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:ref_failed")

    rng = _seeded_rng(seed)
    outcomes = []
    for _ in range(k_used):
        # Build a "perturbed" graph: if graph_data has an edges
        # attribute, drop a fraction; otherwise pass through.
        perturbed = graph_data
        if hasattr(graph_data, "edges"):
            try:
                edges = list(graph_data.edges)
                kept = [e for e in edges if rng.random() > edge_perturbation_rate]
                # If the graph is mutable & has a from_edges, use it;
                # otherwise pass the kept edges as a tuple.
                if hasattr(graph_data, "from_edges"):
                    perturbed = graph_data.from_edges(kept)
                else:
                    perturbed = tuple(kept)
            except Exception:
                pass
        try:
            v = metric_callable(perturbed)
        except Exception:
            outcomes.append(0.0)
            continue
        outcomes.append(1.0 if v == ref else 0.0)
    return _aggregate_outcomes(outcomes, ftype, family, k_used)

def stability_sequence_feature(
    sequence: Sequence,
    *,
    k: int = KTier.DIAGNOSTIC,
    feature_callable: Optional[Callable[[Sequence], Any]] = None,
    seed: int = 0,
) -> StabilityResult:
    """Stability via prefix truncation / suffix extension / modulus
    perturbation.

    ``feature_callable(perturbed_sequence)`` returns a verdict.
    Perturbations: each iteration drops 0..min(3, len/4) elements from
    each end at random.
    """
    k_used = _coerce_k(k)
    ftype = FalsifierType.SEQUENCE_FEATURE.value
    family = "prefix_truncation_suffix_extension"

    if feature_callable is None:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:no_callable")

    seq = list(sequence)
    try:
        ref = feature_callable(seq)
    except Exception:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:ref_failed")

    rng = _seeded_rng(seed)
    n = len(seq)
    max_drop = max(0, min(3, n // 4))
    outcomes = []
    for _ in range(k_used):
        drop_left = rng.randint(0, max_drop) if max_drop > 0 else 0
        drop_right = rng.randint(0, max_drop) if max_drop > 0 else 0
        if n - drop_left - drop_right < 1:
            perturbed = seq
        else:
            perturbed = seq[drop_left: n - drop_right] if drop_right > 0 else seq[drop_left:]
        try:
            v = feature_callable(perturbed)
        except Exception:
            outcomes.append(0.0)
            continue
        outcomes.append(1.0 if v == ref else 0.0)
    return _aggregate_outcomes(outcomes, ftype, family, k_used)

def stability_model_policy(
    policy_callable: Optional[Callable[[Any, int], Any]],
    input_data: Any,
    *,
    k: int = KTier.DIAGNOSTIC,
    seeds: Optional[Sequence[int]] = None,
) -> StabilityResult:
    """Stability via seed perturbation / replay perturbation.

    ``policy_callable(input_data, seed)`` returns a verdict. The
    adapter calls it across ``k`` distinct seeds and measures
    seed-to-seed agreement.

    NOTE: the first positional argument is the policy_callable itself
    (not input_data) — this matches the substrate v2.3 §6.2 spec
    signature. When ``policy_callable is None``, returns NaN-filled
    result.
    """
    k_used = _coerce_k(k)
    ftype = FalsifierType.MODEL_POLICY.value
    family = "seed_replay"

    if policy_callable is None:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:no_callable")

    if seeds is None:
        seeds = list(range(k_used))
    seeds = list(seeds)[:k_used]

    if not seeds:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:empty_seeds")

    try:
        ref = policy_callable(input_data, seeds[0])
    except Exception:
        return StabilityResult.empty(falsifier_type=ftype, k=k_used,
                                     perturbation_family=f"{family}:ref_failed")

    outcomes = [1.0]  # ref agrees with itself
    used = 1
    for s in seeds[1:]:
        used += 1
        try:
            v = policy_callable(input_data, s)
        except Exception:
            outcomes.append(0.0)
            continue
        outcomes.append(1.0 if v == ref else 0.0)
    return _aggregate_outcomes(outcomes, ftype, family, used)

def compute_stability(
    falsifier_type: FalsifierType,
    *args: Any,
    k: int = KTier.DIAGNOSTIC,
    **kwargs: Any,
) -> StabilityResult:
    """Dispatch to the adapter for ``falsifier_type``.

    Tolerates the falsifier_type being passed as a string (matched
    case-insensitively) for callers reading directly from JSON.
    """
    if isinstance(falsifier_type, str):
        try:
            ft = FalsifierType(falsifier_type)
        except ValueError:
            ft = FalsifierType(falsifier_type.lower())
    else:
        ft = falsifier_type
    adapter = _ADAPTERS.get(ft)
    if adapter is None:
        return StabilityResult.empty(
            falsifier_type=str(ft.value if hasattr(ft, "value") else ft),
            k=_coerce_k(k),
            perturbation_family="dispatch:unknown_type",
        )
    return adapter(*args, k=k, **kwargs)

def falsifier_type_for_margin_unit(unit: Optional[str]) -> Optional[FalsifierType]:
    """Default FalsifierType for a given margin_unit; None if unknown."""
    if unit is None:
        return None
    return MARGIN_UNIT_TO_FALSIFIER_TYPE.get(unit)

def to_dict(self) -> Dict[str, Any]:
    return {
        "stability_mean": (
            None if math.isnan(self.stability_mean) else float(self.stability_mean)
        ),
        "stability_variance": (
            None if math.isnan(self.stability_variance) else float(self.stability_variance)
        ),
        "perturbation_family": str(self.perturbation_family),
        "worst_case_flip_rate": (
            None if math.isnan(self.worst_case_flip_rate) else float(self.worst_case_flip_rate)
        ),
        "k_used": int(self.k_used),
        "falsifier_type": str(self.falsifier_type),
    }

def from_dict(cls, d: Dict[str, Any]) -> "StabilityResult":
    def _f(v: Any) -> float:
        if v is None:
            return float("nan")
        try:
            return float(v)
        except (TypeError, ValueError):
            return float("nan")

    return cls(
        stability_mean=_f(d.get("stability_mean")),
        stability_variance=_f(d.get("stability_variance")),
        perturbation_family=str(d.get("perturbation_family", "")),
        worst_case_flip_rate=_f(d.get("worst_case_flip_rate")),
        k_used=int(d.get("k_used", 0)),
        falsifier_type=str(d.get("falsifier_type", "")),
    )

def _f(v: Any) -> float:
    if v is None:
        return float("nan")
    try:
        return float(v)
    except (TypeError, ValueError):
        return float("nan")

def _check_positive(name: str, value: float) -> float:
    v = float(value)
    if not math.isfinite(v) or v <= 0.0:
        raise ValueError(f"{name} must be a positive finite float, got {value!r}")
    return v

def _check_nonneg(name: str, value: float) -> float:
    v = float(value)
    if not math.isfinite(v) or v < 0.0:
        raise ValueError(f"{name} must be a non-negative finite float, got {value!r}")
    return v

def _check_int_nonneg(name: str, value: int) -> int:
    v = int(value)
    if v < 0:
        raise ValueError(f"{name} must be a non-negative int, got {value!r}")
    return v

def _check_prob(name: str, value: float) -> float:
    v = float(value)
    if not (0.0 < v <= 1.0):
        raise ValueError(f"{name} must be in (0, 1], got {value!r}")
    return v

def _normal_frozen(*, mu: float = 0.0, sigma: float = 1.0):
    sigma = _check_positive("sigma", sigma)
    return _ss.norm(loc=float(mu), scale=sigma)

def _exponential_frozen(*, rate: float = 1.0):
    rate = _check_positive("rate", rate)
    return _ss.expon(scale=1.0 / rate)

def _beta_frozen(*, alpha: float, beta: float):
    a = _check_positive("alpha", alpha)
    b = _check_positive("beta", beta)
    return _ss.beta(a, b)

def _gamma_frozen(*, shape: float, rate: float = 1.0):
    s = _check_positive("shape", shape)
    r = _check_positive("rate", rate)
    return _ss.gamma(s, scale=1.0 / r)

def _chi2_frozen(*, k: float):
    df = _check_positive("k", k)
    return _ss.chi2(df)

def _t_frozen(*, df: float):
    nu = _check_positive("df", df)
    return _ss.t(nu)

def _f_frozen(*, d1: float, d2: float):
    a = _check_positive("d1", d1)
    b = _check_positive("d2", d2)
    return _ss.f(a, b)

def _binomial_frozen(*, n: int, p: float):
    n = _check_int_nonneg("n", n)
    p_ = float(p)
    if not (0.0 <= p_ <= 1.0):
        raise ValueError(f"p must be in [0, 1], got {p!r}")
    return _ss.binom(n, p_)

def _poisson_frozen(*, mu: float):
    m = _check_positive("mu", mu)
    return _ss.poisson(m)

def _geometric_frozen(*, p: float):
    p_ = _check_prob("p", p)
    return _ss.geom(p_)

def _negative_binomial_frozen(*, r: int, p: float):
    r_ = int(r)
    if r_ <= 0:
        raise ValueError(f"r must be positive int, got {r!r}")
    p_ = _check_prob("p", p)
    return _ss.nbinom(r_, p_)

def _uniform_frozen(*, a: float = 0.0, b: float = 1.0):
    a_ = float(a)
    b_ = float(b)
    if b_ <= a_:
        raise ValueError(f"need a < b for Uniform; got a={a!r}, b={b!r}")
    return _ss.uniform(loc=a_, scale=b_ - a_)

def _lognormal_frozen(*, mu: float = 0.0, sigma: float = 1.0):
    s = _check_positive("sigma", sigma)
    return _ss.lognorm(s=s, scale=math.exp(float(mu)))

def _weibull_frozen(*, k: float, lam: float = 1.0):
    sh = _check_positive("k", k)
    sc = _check_positive("lam", lam)
    return _ss.weibull_min(sh, scale=sc)

def _cauchy_frozen(*, loc: float = 0.0, scale: float = 1.0):
    s = _check_positive("scale", scale)
    return _ss.cauchy(loc=float(loc), scale=s)

def _laplace_frozen(*, loc: float = 0.0, scale: float = 1.0):
    s = _check_positive("scale", scale)
    return _ss.laplace(loc=float(loc), scale=s)

def _pareto_frozen(*, alpha: float, xm: float = 1.0):
    a = _check_positive("alpha", alpha)
    s = _check_positive("xm", xm)
    return _ss.pareto(a, scale=s)

def get_family(name_or_family) -> Any:
    """Resolve a name or Family object to its Family instance."""
    if isinstance(name_or_family, str):
        try:
            return FAMILIES[name_or_family]
        except KeyError as exc:
            raise ValueError(f"unknown distribution family: {name_or_family!r}") from exc
    return name_or_family

def kl_divergence(
    dist_a, params_a: Mapping[str, Any], dist_b, params_b: Mapping[str, Any]
) -> float:
    """KL(P || Q) for two same-family named distributions.

    Closed-form for normal / exponential / poisson; numerical integration
    elsewhere. Continuous families integrate ``p(x) * log p(x)/q(x)`` over
    the support; discrete families sum over a truncation that captures
    >= 1-1e-12 of the mass.
    """
    fa = get_family(dist_a)
    fb = get_family(dist_b)
    if fa.name != fb.name:
        raise ValueError(
            f"kl_divergence requires both distributions be the same family; "
            f"got {fa.name!r} and {fb.name!r}"
        )
    name = fa.name
    if name in _CLOSED_FORM_KL:
        return _CLOSED_FORM_KL[name](dict(params_a), dict(params_b))

    if fa.discrete:
        return _kl_discrete(fa, params_a, params_b)
    return _kl_continuous(fa, params_a, params_b)

def _kl_continuous(family: Family, pa, pb) -> float:
    rva = family.frozen(**pa)
    rvb = family.frozen(**pb)
    lo_a, hi_a = family.support(**pa)

    def integrand(x):
        pdf_p = rva.pdf(x)
        pdf_q = rvb.pdf(x)
        if pdf_p <= 0.0:
            return 0.0
        if pdf_q <= 0.0:
            return np.inf
        return pdf_p * (math.log(pdf_p) - math.log(pdf_q))

    # Integrate over a finite truncation of the support.
    eps = 1e-12
    lo = rva.ppf(eps) if not math.isfinite(lo_a) else lo_a + 1e-12
    hi = rva.ppf(1.0 - eps) if not math.isfinite(hi_a) else hi_a - 1e-12
    val, _err = _integrate.quad(integrand, lo, hi, limit=200)
    return float(max(val, 0.0))

def _validate_samples(samples) -> np.ndarray:
    arr = np.asarray(samples, dtype=float)
    if arr.ndim != 1 or arr.size == 0:
        raise ValueError("samples must be a non-empty 1-D array")
    if not np.all(np.isfinite(arr)):
        raise ValueError("samples must be finite")
    return arr

def moment_estimator(
    samples, family, n_moments: int = 4
) -> Dict[str, Any]:
    """Method-of-moments parameter estimation.

    Currently supports normal/exponential/gamma/uniform/poisson. Returns
    a dict ``{ 'family': name, 'params': {...}, 'moments': [m1, ..., mk] }``.
    """
    arr = _validate_samples(samples)
    if int(n_moments) < 1:
        raise ValueError("n_moments must be >= 1")
    if int(n_moments) > arr.size:
        raise ValueError("n_moments must be <= len(samples)")
    fam = get_family(family)

    # Raw and central moments.
    m1 = float(np.mean(arr))
    var = float(np.var(arr, ddof=0))
    moments = [float(np.mean(arr**k)) for k in range(1, int(n_moments) + 1)]

    if fam.name == "normal":
        params = {"mu": m1, "sigma": math.sqrt(max(var, 0.0))}
    elif fam.name == "exponential":
        if m1 <= 0:
            raise ValueError("exponential MoM requires positive sample mean")
        params = {"rate": 1.0 / m1}
    elif fam.name == "gamma":
        if m1 <= 0 or var <= 0:
            raise ValueError("gamma MoM requires positive mean and variance")
        rate = m1 / var
        shape = m1 * rate
        params = {"shape": shape, "rate": rate}
    elif fam.name == "uniform":
        # X ~ U(a,b); E[X] = (a+b)/2; Var[X] = (b-a)^2/12.
        spread = math.sqrt(max(12.0 * var, 0.0))
        a_hat = m1 - spread / 2.0
        b_hat = m1 + spread / 2.0
        params = {"a": a_hat, "b": b_hat}
    elif fam.name == "poisson":
        if m1 <= 0:
            raise ValueError("poisson MoM requires positive sample mean")
        params = {"mu": m1}
    else:
        raise NotImplementedError(
            f"moment_estimator not implemented for family {fam.name!r}"
        )
    return {"family": fam.name, "params": params, "moments": moments}

