def mle_estimator(samples, family) -> Dict[str, Any]:
    """Maximum-likelihood parameter estimation.

    Closed-form where available (normal/exponential/poisson/uniform);
    scipy.stats.fit otherwise.
    """
    arr = _validate_samples(samples)
    fam = get_family(family)
    name = fam.name

    if name == "normal":
        mu = float(np.mean(arr))
        sigma = float(np.std(arr, ddof=0))
        if sigma == 0.0:
            raise ValueError("normal MLE: sample variance is zero")
        return {"family": name, "params": {"mu": mu, "sigma": sigma}}
    if name == "exponential":
        m = float(np.mean(arr))
        if m <= 0:
            raise ValueError("exponential MLE requires positive sample mean")
        return {"family": name, "params": {"rate": 1.0 / m}}
    if name == "poisson":
        m = float(np.mean(arr))
        if m <= 0:
            raise ValueError("poisson MLE requires positive sample mean")
        return {"family": name, "params": {"mu": m}}
    if name == "uniform":
        a_hat = float(np.min(arr))
        b_hat = float(np.max(arr))
        if a_hat == b_hat:
            raise ValueError("uniform MLE: degenerate sample (min==max)")
        return {"family": name, "params": {"a": a_hat, "b": b_hat}}
    if name == "lognormal":
        if np.any(arr <= 0):
            raise ValueError("lognormal MLE requires strictly positive samples")
        log_arr = np.log(arr)
        mu = float(np.mean(log_arr))
        sigma = float(np.std(log_arr, ddof=0))
        if sigma == 0.0:
            raise ValueError("lognormal MLE: log-sample variance is zero")
        return {"family": name, "params": {"mu": mu, "sigma": sigma}}
    if name == "gamma":
        # scipy.stats.gamma.fit returns (shape, loc, scale); fix loc=0.
        try:
            shape, loc, scale = _ss.gamma.fit(arr, floc=0.0)
        except Exception as exc:  # pragma: no cover
            raise ValueError(f"gamma MLE failed: {exc}") from exc
        return {
            "family": name,
            "params": {"shape": float(shape), "rate": 1.0 / float(scale)},
        }
    if name == "beta":
        try:
            a_, b_, _loc, _scale = _ss.beta.fit(arr, floc=0.0, fscale=1.0)
        except Exception as exc:  # pragma: no cover
            raise ValueError(f"beta MLE failed: {exc}") from exc
        return {"family": name, "params": {"alpha": float(a_), "beta": float(b_)}}

    raise NotImplementedError(f"mle_estimator not implemented for {name!r}")

def pdf(self, x, **params):
    """Probability density (continuous) or mass (discrete)."""
    rv = self.frozen(**params)
    return rv.pmf(x) if self.discrete else rv.pdf(x)

def cdf(self, x, **params):
    """Cumulative distribution function ``P[X <= x]``."""
    return self.frozen(**params).cdf(x)

def quantile(self, p, **params):
    """Inverse CDF (a.k.a. percent-point function).

    ``quantile(0)`` returns the support lower bound, ``quantile(1)``
    the upper bound. ``p`` outside ``[0, 1]`` raises ValueError.
    """
    p_arr = np.asarray(p, dtype=float)
    if np.any(p_arr < 0.0) or np.any(p_arr > 1.0):
        raise ValueError("quantile p must be in [0, 1]")
    return self.frozen(**params).ppf(p)

def sample(self, n, seed: Optional[int] = None, **params):
    """Draw ``n`` i.i.d. samples."""
    if int(n) < 0:
        raise ValueError("n must be >= 0")
    if int(n) == 0:
        return np.array([], dtype=float)
    rng = np.random.default_rng(seed)
    return self.frozen(**params).rvs(size=int(n), random_state=rng)

def _frozen(*, mean, cov):
    m = np.asarray(mean, dtype=float).ravel()
    C = np.asarray(cov, dtype=float)
    if C.shape != (m.size, m.size):
        raise ValueError(
            f"cov must be ({m.size},{m.size}); got {C.shape}"
        )
    # Symmetric? scipy will raise if not PSD.
    try:
        return _ss.multivariate_normal(mean=m, cov=C, allow_singular=False)
    except (np.linalg.LinAlgError, ValueError) as exc:
        raise ValueError(f"invalid covariance matrix: {exc}") from exc

def support(self, **params):
    m = np.asarray(params["mean"], dtype=float).ravel()
    return (np.full_like(m, -np.inf), np.full_like(m, np.inf))

def quantile(self, p, **params):
    # No standard multivariate quantile; raise to be honest.
    raise NotImplementedError(
        "quantile is not defined for multivariate_normal "
        "(use marginal normal.quantile)"
    )

def sample(self, n, seed: Optional[int] = None, **params):
    if int(n) < 0:
        raise ValueError("n must be >= 0")
    if int(n) == 0:
        d = np.asarray(params["mean"], dtype=float).ravel().size
        return np.empty((0, d), dtype=float)
    rng = np.random.default_rng(seed)
    return self._frozen(**params).rvs(size=int(n), random_state=rng)

def integrand(x):
    pdf_p = rva.pdf(x)
    pdf_q = rvb.pdf(x)
    if pdf_p <= 0.0:
        return 0.0
    if pdf_q <= 0.0:
        return np.inf
    return pdf_p * (math.log(pdf_p) - math.log(pdf_q))

def ec(x):
    x_arr = np.asarray(x, dtype=float)
    idx = np.searchsorted(sorted_arr, x_arr, side="right")
    out = idx / n
    if x_arr.ndim == 0:
        return float(out)
    return out

def f(x):
    x_arr = np.asarray(x, dtype=float)
    out = kdefn(x_arr.ravel())
    return float(out[0]) if x_arr.ndim == 0 else out.reshape(x_arr.shape)

def parse(s: ExprLike) -> sympy.Expr:
    """Parse a string (or pass-through expression) into a sympy.Expr.

    Convenience over sympy.sympify with a clearer error.
    """
    if isinstance(s, sympy.Basic):
        return s
    try:
        return sympy.sympify(s)
    except (sympy.SympifyError, SyntaxError, TypeError) as e:
        raise ValueError(f"cannot parse {s!r} as sympy expression: {e}")

def _as_var(v) -> sympy.Symbol:
    if isinstance(v, sympy.Symbol):
        return v
    if isinstance(v, str):
        return sympy.Symbol(v)
    raise ValueError(f"expected symbol or string, got {v!r}")

def _as_vars(vs) -> list[sympy.Symbol]:
    if vs is None:
        return []
    if isinstance(vs, (sympy.Symbol, str)):
        return [_as_var(vs)]
    return [_as_var(v) for v in vs]

def simplify(expr: ExprLike) -> sympy.Expr:
    """Simplify an expression (sympy.simplify)."""
    return sympy.simplify(parse(expr))

def factor(expr: ExprLike) -> sympy.Expr:
    """Factor a polynomial / expression."""
    return sympy.factor(parse(expr))

def expand(expr: ExprLike) -> sympy.Expr:
    """Expand a polynomial / expression."""
    return sympy.expand(parse(expr))

def solve(expr_or_eqs, vars=None):
    """Solve equation(s) for given variable(s).

    Parameters
    ----------
    expr_or_eqs : Expr | str | sequence
        Single expression (assumed = 0), sympy.Eq, or list of those.
    vars : Symbol | str | sequence, optional
        Variable(s) to solve for. If None, sympy auto-detects.

    Returns
    -------
    list or dict (sympy.solve return convention).
    """
    if isinstance(expr_or_eqs, (list, tuple)):
        eqs = [parse(e) for e in expr_or_eqs]
    else:
        eqs = parse(expr_or_eqs)
    vs = _as_vars(vars)
    try:
        if vs:
            return sympy.solve(eqs, *vs)
        return sympy.solve(eqs)
    except Exception as e:
        raise ValueError(f"solve failed for {expr_or_eqs!r}: {e}")

def integrate(expr: ExprLike, var) -> sympy.Expr:
    """Indefinite integral.

    For definite: pass `var=(x, a, b)` as a tuple, sympy convention.
    """
    e = parse(expr)
    if isinstance(var, tuple):
        return sympy.integrate(e, var)
    return sympy.integrate(e, _as_var(var))

def differentiate(expr: ExprLike, var) -> sympy.Expr:
    """Differentiate w.r.t. var (avoids name clash with sympy.diff)."""
    return sympy.diff(parse(expr), _as_var(var))

def series_expand(expr: ExprLike, var, x0=0, n: int = 6) -> sympy.Expr:
    """Taylor / Laurent series of `expr` around `var = x0` to order n."""
    return sympy.series(parse(expr), _as_var(var), x0, n)

def solve_ode(eq, func) -> sympy.Expr:
    """Solve an ODE.

    Parameters
    ----------
    eq : sympy.Eq | Expr
        The ODE (Expr is interpreted as eq = 0).
    func : sympy.Function applied to a Symbol, e.g. f(x).
    """
    e = parse(eq) if not isinstance(eq, sympy.Basic) else eq
    try:
        return sympy.dsolve(e, func)
    except Exception as ex:
        raise ValueError(f"solve_ode failed: {ex}")

def resultant(p: ExprLike, q: ExprLike, var) -> sympy.Expr:
    """Resultant of two polynomials in `var`."""
    return sympy.resultant(parse(p), parse(q), _as_var(var))

def discriminant(p: ExprLike, var) -> sympy.Expr:
    """Discriminant of polynomial `p` in variable `var`."""
    return sympy.discriminant(parse(p), _as_var(var))

def polynomial_factor_finite(poly: ExprLike, p: int) -> list:
    """Factor a polynomial over GF(p).

    Returns a list of (factor, multiplicity) pairs.
    """
    if not isinstance(p, int) or p < 2 or not sympy.isprime(p):
        raise ValueError(f"polynomial_factor_finite: p must be a prime, got {p!r}")
    expr = parse(poly)
    try:
        # Need at least one variable; use the free symbols of expr
        syms = list(expr.free_symbols)
        if not syms:
            raise ValueError("polynomial has no variables")
        poly_obj = sympy.Poly(expr, *syms, modulus=p)
        const, factors = poly_obj.factor_list()
        return [(f.as_expr(), m) for (f, m) in factors]
    except Exception as e:
        raise ValueError(f"polynomial_factor_finite failed: {e}")

def _as_numpy(tensor) -> np.ndarray:
    """Coerce input to a numpy.ndarray of dtype float64.

    Rejects bare scalars, lists-of-strings, etc.  Lists / tuples of
    numbers are accepted (per numpy's array constructor).
    """
    if tensor is None:
        raise ValueError("tensor input is None")
    if isinstance(tensor, (str, bytes)):
        raise ValueError("tensor input must be array-like, got string")
    try:
        arr = np.asarray(tensor, dtype=np.float64)
    except (TypeError, ValueError) as e:
        raise ValueError(f"cannot interpret input as a tensor: {e}")
    if arr.ndim == 0:
        raise ValueError("tensor must have ndim >= 1, got a scalar")
    if not np.all(np.isfinite(arr)):
        raise ValueError("tensor contains NaN or inf")
    return arr

def _check_tol(tol: float) -> None:
    if tol < 0:
        raise ValueError(f"tol must be >= 0, got {tol}")

def _check_max_iter(max_iter: int) -> None:
    if max_iter < 1:
        raise ValueError(f"max_iter must be >= 1, got {max_iter}")

def cp_reconstruct(
    factors: Sequence[np.ndarray],
    weights: Optional[np.ndarray] = None,
) -> np.ndarray:
    """Reconstruct a dense tensor from CP factors.

    T_{i_1...i_d} = Σ_r λ_r · ∏_k F^{(k)}_{i_k, r}
    """
    if not factors:
        raise ValueError("factors must be a non-empty sequence")
    factors = [np.asarray(f, dtype=np.float64) for f in factors]
    rank = factors[0].shape[1]
    for k, f in enumerate(factors):
        if f.ndim != 2:
            raise ValueError(f"factor {k} must be 2-D, got shape {f.shape}")
        if f.shape[1] != rank:
            raise ValueError(
                f"factor {k} has rank {f.shape[1]} but factor 0 has rank {rank}"
            )
    if weights is None:
        weights = np.ones(rank, dtype=np.float64)
    else:
        weights = np.asarray(weights, dtype=np.float64).reshape(-1)
        if weights.shape[0] != rank:
            raise ValueError(
                f"weights has length {weights.shape[0]} but rank is {rank}"
            )
    out = cp_to_tensor((weights, factors))
    return np.asarray(out, dtype=np.float64)

def tucker_reconstruct(
    core: np.ndarray,
    factors: Sequence[np.ndarray],
) -> np.ndarray:
    """Reconstruct dense tensor from Tucker decomposition."""
    core = np.asarray(core, dtype=np.float64)
    factors = [np.asarray(f, dtype=np.float64) for f in factors]
    if len(factors) != core.ndim:
        raise ValueError(
            f"factors has length {len(factors)} but core has ndim {core.ndim}"
        )
    out = _tucker_to_tensor((core, factors))
    return np.asarray(out, dtype=np.float64)

def tt_reconstruct(cores: Sequence[np.ndarray]) -> np.ndarray:
    """Reconstruct a dense tensor from TT cores."""
    if not cores:
        raise ValueError("cores must be a non-empty sequence")
    cores = [np.asarray(c, dtype=np.float64) for c in cores]
    for k, c in enumerate(cores):
        if c.ndim != 3:
            raise ValueError(f"core {k} must be 3-D, got shape {c.shape}")
    if cores[0].shape[0] != 1:
        raise ValueError(
            f"first core must have leading bond dim 1, got {cores[0].shape[0]}"
        )
    if cores[-1].shape[2] != 1:
        raise ValueError(
            f"last core must have trailing bond dim 1, got {cores[-1].shape[2]}"
        )
    for k in range(len(cores) - 1):
        if cores[k].shape[2] != cores[k + 1].shape[0]:
            raise ValueError(
                f"bond mismatch between core {k} (right={cores[k].shape[2]}) "
                f"and core {k+1} (left={cores[k+1].shape[0]})"
            )
    out = _tt_to_tensor(cores)
    return np.asarray(out, dtype=np.float64)

def decomp_storage(decomp_dict: dict, kind: str) -> int:
    """Number of floats stored in a decomposition (compression measure).

    Parameters
    ----------
    decomp_dict : dict
        Output of cp_decompose / tucker_decompose / tt_decompose.
    kind : {"cp", "tucker", "tt"}
    """
    kind = kind.lower()
    if kind == "cp":
        n = sum(int(np.asarray(f).size) for f in decomp_dict["factors"])
        n += int(np.asarray(decomp_dict["weights"]).size)
        return n
    if kind == "tucker":
        n = int(np.asarray(decomp_dict["core"]).size)
        n += sum(int(np.asarray(f).size) for f in decomp_dict["factors"])
        return n
    if kind == "tt":
        return sum(int(np.asarray(c).size) for c in decomp_dict["cores"])
    raise ValueError(f"kind must be 'cp', 'tucker', or 'tt', got {kind!r}")

