def _get_client() -> "Optional[_arxiv.Client]":
    global _client
    if _arxiv is None:
        return None
    if _client is None:
        _client = _arxiv.Client(
            page_size=_DEFAULT_PAGE_SIZE,
            delay_seconds=_DEFAULT_DELAY,
            num_retries=_DEFAULT_RETRIES,
        )
    return _client

def _resolve_sort(sort_by: str):
    if _arxiv is None:
        return None
    name = _SORT_MAP.get(sort_by, sort_by)
    try:
        return getattr(_arxiv.SortCriterion, name)
    except AttributeError:
        return _arxiv.SortCriterion.Relevance

def _normalize_id(arxiv_id) -> str:
    """Strip any trailing version suffix and surrounding whitespace."""
    s = str(arxiv_id).strip()
    if s.startswith("arXiv:"):
        s = s[len("arXiv:"):]
    # Old-style: math.NT/0501234. New-style: 2410.12345 (with optional vN).
    if "v" in s:
        head, _, tail = s.rpartition("v")
        if tail.isdigit():
            s = head
    return s

def get(arxiv_id) -> Optional[dict]:
    """Fetch metadata for a single arXiv paper by id.

    Accepts modern ids ('2410.12345', '2410.12345v2') and legacy ids
    ('math.NT/0501234'). Returns the normalized dict, or None on miss
    or network error.
    """
    client = _get_client()
    if client is None:
        return None
    aid = _normalize_id(arxiv_id)
    try:
        s = _arxiv.Search(id_list=[aid], max_results=1)
        for r in client.results(s):
            return _shape_result(r)
        return None
    except Exception:
        return None

def download_pdf(arxiv_id,
                 dirpath: str = ".",
                 filename: Optional[str] = None) -> Optional[str]:
    """Download the PDF for a paper to `dirpath`.

    Returns the saved path on success, None on failure. The default
    filename is ``<arxiv_id>.pdf``. The underlying `arxiv` client uses
    its own rate limiter; do not call this in tight loops.
    """
    client = _get_client()
    if client is None:
        return None
    aid = _normalize_id(arxiv_id)
    if filename is None:
        filename = f"{aid}.pdf"
    try:
        s = _arxiv.Search(id_list=[aid], max_results=1)
        for r in client.results(s):
            return r.download_pdf(dirpath=dirpath, filename=filename)
        return None
    except Exception:
        return None

def by_category(category: str,
                max_results: int = 100,
                year: Optional[int] = None) -> list[dict]:
    """Papers in a single arXiv category, optionally filtered by year.

    `year` filters by the calendar year of the `published` timestamp.
    Sorting is by submission date, newest first.
    """
    if not category:
        return []
    client = _get_client()
    if client is None:
        return []

    fetch = max_results if year is None else max(max_results * 3, max_results + 50)
    try:
        s = _arxiv.Search(
            query=f"cat:{category}",
            max_results=fetch,
            sort_by=_arxiv.SortCriterion.SubmittedDate,
            sort_order=_arxiv.SortOrder.Descending,
        )
        out: list[dict] = []
        for r in client.results(s):
            if year is not None and isinstance(r.published, _dt.datetime):
                if r.published.year > year:
                    continue
                if r.published.year < year:
                    # Descending sort — older years are past the window.
                    break
            out.append(_shape_result(r))
            if len(out) >= max_results:
                break
        return out
    except Exception:
        return []

def latex_source(arxiv_id, dirpath: str = ".") -> Optional[str]:
    """Download the LaTeX source tarball (`.tar.gz`) for a paper.

    Useful for AI training, formalization-tool ingestion, and recovering
    the original equations / macros that PDFs lose. Returns the saved
    path on success, None on failure.
    """
    client = _get_client()
    if client is None:
        return None
    aid = _normalize_id(arxiv_id)
    try:
        s = _arxiv.Search(id_list=[aid], max_results=1)
        for r in client.results(s):
            return r.download_source(dirpath=dirpath)
        return None
    except Exception:
        return None

def _read_paper(path: pathlib.Path) -> Optional[dict]:
    try:
        with path.open("r", encoding="utf-8") as fh:
            obj = json.load(fh)
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(obj, dict):
        return None
    if not all(k in obj for k in _REQUIRED_FIELDS):
        return None
    return obj

def _write_paper(rec: dict) -> Optional[pathlib.Path]:
    aid = (rec.get("id") or "").strip()
    if not aid:
        return None
    dest = _paper_path(aid)
    tmp = dest.with_suffix(".json.tmp")
    try:
        with tmp.open("w", encoding="utf-8") as fh:
            json.dump(rec, fh, ensure_ascii=False, indent=2, sort_keys=True)
        os.replace(tmp, dest)
    except OSError:
        try:
            if tmp.exists():
                tmp.unlink()
        except OSError:
            pass
        return None
    return dest

def _iter_paper_paths() -> list[pathlib.Path]:
    base = _corpus_dir()
    if not base.is_dir():
        return []
    return sorted(p for p in base.glob("*.json") if p.name != _INDEX_FILE)

def _iter_papers() -> Iterable[dict]:
    for p in _iter_paper_paths():
        rec = _read_paper(p)
        if rec is not None:
            yield rec

def _write_index_summary() -> None:
    """Recompute and persist the corpus-level summary JSON."""
    base = _corpus_dir()
    stats = corpus_stats(_skip_index=True)
    payload = {
        "generated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        **stats,
    }
    try:
        with (base / _INDEX_FILE).open("w", encoding="utf-8") as fh:
            json.dump(payload, fh, ensure_ascii=False, indent=2, sort_keys=True)
    except OSError:
        pass

def get_by_id(arxiv_id: str) -> Optional[dict]:
    """Return the on-disk record for ``arxiv_id`` or None.

    Strips any trailing version suffix the caller may have included
    (e.g. ``2410.12345v2`` -> ``2410.12345``).
    """
    if not arxiv_id:
        return None
    aid = str(arxiv_id).strip()
    if aid.startswith("arXiv:"):
        aid = aid[len("arXiv:"):]
    if "v" in aid:
        head, _, tail = aid.rpartition("v")
        if tail.isdigit():
            aid = head
    path = _paper_path(aid)
    if not path.is_file():
        return None
    return _read_paper(path)

def _neg_iso(s: str) -> str:
    """Sort key that orders ISO date strings *descending* lexicographically.

    Used as a tie-break inside :func:`search`. Empty strings sort last.
    """
    if not s:
        return "\x00"  # last
    # Invert each char so larger date strings produce smaller keys.
    return "".join(chr(0xFFFF - ord(c)) for c in s)

def corpus_stats(_skip_index: bool = False) -> dict:
    """Return summary stats over the local corpus.

    ``_skip_index`` is internal: ``update_corpus`` calls this to compute
    a snapshot without recursing into a previously-written ``_index.json``.

    Returned dict::

        {
            "n_papers":         int,
            "by_category":      dict[str, int],
            "by_year":          dict[int, int],
            "total_size_bytes": int,
            "corpus_dir":       str,
        }
    """
    base = _corpus_dir()
    paths = _iter_paper_paths()
    n_papers = 0
    by_category: dict[str, int] = {}
    by_year: dict[int, int] = {}
    total_size = 0
    for p in paths:
        try:
            total_size += p.stat().st_size
        except OSError:
            continue
        rec = _read_paper(p)
        if rec is None:
            continue
        n_papers += 1
        for c in (rec.get("categories") or []):
            by_category[c] = by_category.get(c, 0) + 1
        pub = rec.get("published") or ""
        try:
            yr = int(pub[:4])
        except ValueError:
            yr = 0
        if yr:
            by_year[yr] = by_year.get(yr, 0) + 1
    if not _skip_index:
        # Don't double-count the index file on disk.
        idx = base / _INDEX_FILE
        if idx.exists():
            try:
                total_size += idx.stat().st_size
            except OSError:
                pass
    return {
        "n_papers": n_papers,
        "by_category": by_category,
        "by_year": by_year,
        "total_size_bytes": total_size,
        "corpus_dir": str(base),
    }

def tags_index() -> dict[str, list[str]]:
    """Reverse map ``arxiv_id -> [category, ...]`` over the local corpus."""
    out: dict[str, list[str]] = {}
    for rec in _iter_papers():
        aid = rec.get("id") or ""
        if not aid:
            continue
        cats = list(rec.get("categories") or [])
        out[aid] = cats
    return out

def probe(timeout: float = 3.0) -> bool:
    """Cheap availability check for the registry.

    True iff (a) the corpus directory contains at least one paper JSON,
    OR (b) the live arXiv API responds. The sibling ``arxiv`` module is
    used for the network probe so we don't duplicate its rate-limiter.
    """
    base = _corpus_dir()
    try:
        for p in base.iterdir():
            if p.is_file() and p.suffix == ".json" and p.name != _INDEX_FILE:
                return True
    except OSError:
        pass
    if _live_arxiv is None:
        return False
    try:
        return bool(_live_arxiv.probe(timeout=timeout))
    except Exception:
        return False

def _build_index() -> None:
    """Index every canonical name + every alias for fast lookup."""
    global _NAME_INDEX
    _NAME_INDEX = {}
    for entry in ATLAS_TABLE:
        keys = {entry["name"]}
        keys.update(entry.get("aliases", []))
        for k in keys:
            nk = _norm_key(k)
            if not nk:
                continue
            # First write wins (the canonical name comes first in the
            # set, but Python set order is non-deterministic; we re-add
            # the canonical key explicitly below for safety).
            if nk not in _NAME_INDEX:
                _NAME_INDEX[nk] = entry
        # Always make sure the canonical name maps to this entry.
        _NAME_INDEX[_norm_key(entry["name"])] = entry

def schur_multiplier(name: str) -> Optional[str]:
    """Return the Schur multiplier of ``name`` as an ATLAS-style string.

    Examples: ``"trivial"``, ``"Z/2"``, ``"Z/6"``, ``"Z/3 x Z/3"``.
    Returns ``None`` if ``name`` isn't in the snapshot.
    """
    e = lookup(name)
    if e is None:
        return None
    return e.get("schur_multiplier")

def outer_automorphism_group(name: str) -> Optional[str]:
    """Return the structure of Out(G) as an ATLAS-style string.

    Examples: ``"trivial"``, ``"Z/2"``, ``"Z/2 x Z/2"``, ``"S_3"``.
    Returns ``None`` if ``name`` isn't in the snapshot.
