def _parse_ainvs(token: str) -> Optional[list[int]]:
    """Parse '[0,-1,1,-10,-20]' -> [0, -1, 1, -10, -20]."""
    if not isinstance(token, str):
        return None
    m = _AINVS_RE.match(token.strip())
    if m is None:
        return None
    try:
        return [int(x) for x in m.group(1).split(",")]
    except ValueError:
        return None

def _to_int(s: str) -> Optional[int]:
    try:
        return int(s)
    except (TypeError, ValueError):
        return None

def _to_float(s: str) -> Optional[float]:
    try:
        return float(s)
    except (TypeError, ValueError):
        return None

def _parse_alllabels_line(line: str) -> Optional[tuple[str, str]]:
    """Parse one line of alllabels: N CRE_CLS CRE_NCURVE N LMFDB_CLS LMFDB_NCURVE.

    Returns (cremona_label, lmfdb_label) or None.
    """
    parts = line.strip().split()
    if len(parts) < 6:
        return None
    n1, cc, ci, n2, lc, li = parts[:6]
    if n1 != n2:
        return None
    if not n1.isdigit():
        return None
    return (f"{n1}{cc}{ci}", f"{n2}.{lc}{li}")

def _existing_blocks(family: str, conductor_max: int) -> list[tuple[int, pathlib.Path]]:
    """Return [(lo, path), ...] for every existing file under cremona/<family>/
    whose lo<=conductor_max."""
    out = []
    for lo, tag in _ranges_up_to(conductor_max):
        p = _file_path(family, tag)
        if p.is_file() and p.stat().st_size > 0:
            out.append((lo, p))
    return out

def has_local_mirror() -> bool:
    """True iff at least one Cremona ecdata file is present on disk.

    We accept either ``allcurves/*`` or ``allbsd/*`` files; either family
    suffices for basic lookup. The check is filesystem-only (no parsing).
    """
    root = _root()
    if not root.is_dir():
        return False
    for family in ("allbsd", "allcurves"):
        sub = root / family
        if not sub.is_dir():
            continue
        try:
            for p in sub.iterdir():
                if p.is_file() and p.stat().st_size > 0:
                    return True
        except OSError:
            continue
    return False

def lookup_by_ainvs(ainvs) -> Optional[dict]:
    """Exact match by Weierstrass 5-tuple [a1, a2, a3, a4, a6].

    Returns the canonical curve dict (rank, torsion, regulator, sha_an,
    real_period, etc.) or None if not in the mirror.
    """
    if not isinstance(ainvs, (list, tuple)):
        return None
    if len(ainvs) != 5:
        return None
    try:
        key = tuple(int(x) for x in ainvs)
    except (TypeError, ValueError):
        return None
    # Make sure cache is populated
    cmax = _cache["loaded_for_max"] or _DEFAULT_CONDUCTOR_MAX
    _ensure_loaded(cmax)
    return (_cache["by_ainvs"] or {}).get(key)

def elliptic_curves(label: Optional[str] = None,
                    conductor: Optional[int] = None,
                    rank: Optional[int] = None,
                    ainvs: Optional[list] = None,
                    conductor_max: Optional[int] = None,
                    limit: int = 10_000,
                    fall_back_to_lmfdb: bool = True,
                    ) -> list[dict]:
    """Local-first elliptic-curve lookup with LMFDB fallback.

    Parameters
    ----------
    label : LMFDB or Cremona label (e.g. "11.a1" or "11a1"). Both
            spellings are accepted; we look up under both.
    conductor : exact conductor filter (int).
    rank : exact rank filter (int).
    ainvs : 5-tuple Weierstrass coefficients (exact match).
    conductor_max : when scanning, only return rows with conductor <=
                    this. Defaults to whatever is loaded in cache.
    limit : max rows returned. Default 10_000.
    fall_back_to_lmfdb : if no local match (or no local mirror), try
                        ``prometheus_math.databases.lmfdb.elliptic_curves``
                        with the same filters. Default True.

    Returns
    -------
    list[dict] of curve records. Each record carries at least
    ``cremona_label``, ``lmfdb_label``, ``ainvs``, ``conductor``,
    ``rank``, ``torsion``; ``regulator``, ``sha_an``, ``real_period``,
    ``L1``, ``tamagawa`` are present iff the allbsd file was mirrored.
    """
    cmax = conductor_max or _cache["loaded_for_max"] or _DEFAULT_CONDUCTOR_MAX

    # Local-first
    local_results: list[dict] = []
    if has_local_mirror():
        _ensure_loaded(cmax)

        # Fast paths: single-row queries.
        if ainvs is not None and len(ainvs) == 5:
            row = lookup_by_ainvs(ainvs)
            if row is not None:
                if conductor is None or row["conductor"] == conductor:
                    if rank is None or row["rank"] == rank:
                        local_results = [row]

        elif label is not None:
            cl, ll = _normalize_label(label)
            row = None
            if cl is not None:
                row = (_cache["by_cremona_label"] or {}).get(cl)
            if row is None and ll is not None:
                row = (_cache["by_lmfdb_label"] or {}).get(ll)
            if row is not None:
                if conductor is None or row["conductor"] == conductor:
                    if rank is None or row["rank"] == rank:
                        local_results = [row]

        else:
            # Range scan
            for r in _cache["all_rows"] or []:
                if conductor is not None and r["conductor"] != conductor:
                    continue
                if rank is not None and r["rank"] != rank:
                    continue
                if conductor_max is not None and r["conductor"] > conductor_max:
                    continue
                local_results.append(r)
                if len(local_results) >= limit:
                    break

    if local_results:
        return local_results[:limit]

    # Fallback
    if not fall_back_to_lmfdb:
        return []
    try:
        from . import lmfdb as _lmfdb
    except Exception:
        return []
    # Translate label to LMFDB form.
    lmfdb_label: Optional[str] = None
    if label is not None:
        _, ll = _normalize_label(label)
        lmfdb_label = ll or label
    try:
        return _lmfdb.elliptic_curves(label=lmfdb_label,
                                      conductor=conductor,
                                      rank=rank,
                                      limit=limit)
    except Exception:
        return []

def _mahler_cache_path() -> pathlib.Path:
    # Mahler is embedded — point at the data module file as the
    # cache-age proxy (refresh = re-bundling the snapshot).
    return pathlib.Path(__file__).with_name("_mahler_data.py")

def _oeis_refresh() -> dict:
    """Refresh OEIS bulk dumps via the wrapper's update_mirror()."""
    from . import oeis as _oeis  # local import avoids hard dep at import time
    return _oeis.update_mirror(force=True)

def _mahler_refresh() -> dict:
    from . import mahler as _mahler
    return _mahler.update_mirror()

def _touch_probe_marker(path: pathlib.Path) -> dict:
    """Write a tiny marker file recording 'last probe' wallclock."""
    path.parent.mkdir(parents=True, exist_ok=True)
    now = _dt.datetime.now(_dt.timezone.utc).isoformat()
    path.write_text(now + "\n", encoding="utf-8")
    return {"refreshed": True, "marker": str(path), "at": now}

def _lmfdb_refresh() -> dict:
    """For the live Postgres mirror, 'refresh' means probe-and-record."""
    return _touch_probe_marker(_lmfdb_cache_path())

def probe_upstream(source: DataSource, timeout: float = _HEAD_TIMEOUT) -> dict:
    """HEAD-probe the upstream URL.  Returns a result dict.

    Keys (always present):
        last_modified : datetime | None    (Last-Modified header parsed)
        etag          : str | None         (ETag header)
        size          : int | None         (Content-Length, if any)
        status        : int | None         (HTTP status; -1 for non-HTTP)
        error         : str | None         (None on success)
    """
    out: dict[str, Any] = {
        "last_modified": None, "etag": None, "size": None,
        "status": None, "error": None,
    }
    if not source.upstream_url:
        out["error"] = "no upstream_url configured"
        return out

    req = urllib.request.Request(
        source.upstream_url,
        method="HEAD",
        headers={"User-Agent": _USER_AGENT, "Accept": "*/*"},
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            out["status"] = getattr(r, "status", None) or r.getcode()
            lm = r.headers.get("Last-Modified")
            if lm:
                try:
                    out["last_modified"] = parsedate_to_datetime(lm)
                except (TypeError, ValueError):
                    out["last_modified"] = None
            et = r.headers.get("ETag")
            if et:
                out["etag"] = et.strip('"')
            cl = r.headers.get("Content-Length")
            if cl is not None:
                try:
                    out["size"] = int(cl)
                except ValueError:
                    out["size"] = None
    except urllib.error.HTTPError as e:
        # Some hosts reject HEAD; retry once with GET (no body read).
        if e.code in (400, 403, 405, 501):
            return _probe_upstream_get(source, timeout)
        out["status"] = e.code
        out["error"] = f"HTTPError {e.code}"
    except (urllib.error.URLError, TimeoutError, OSError) as e:
        out["error"] = f"{type(e).__name__}: {e}"
    except Exception as e:  # pragma: no cover — defensive
        out["error"] = f"{type(e).__name__}: {e}"
    return out

def _probe_upstream_get(source: DataSource, timeout: float) -> dict:
    """Fallback for hosts that reject HEAD; issues GET and reads 0 bytes."""
    out: dict[str, Any] = {
        "last_modified": None, "etag": None, "size": None,
        "status": None, "error": None,
    }
    req = urllib.request.Request(
        source.upstream_url,
        headers={"User-Agent": _USER_AGENT, "Accept": "*/*", "Range": "bytes=0-0"},
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            out["status"] = getattr(r, "status", None) or r.getcode()
            lm = r.headers.get("Last-Modified")
            if lm:
                try:
                    out["last_modified"] = parsedate_to_datetime(lm)
                except (TypeError, ValueError):
                    out["last_modified"] = None
            et = r.headers.get("ETag")
            if et:
                out["etag"] = et.strip('"')
    except (urllib.error.URLError, urllib.error.HTTPError,
            TimeoutError, OSError) as e:
        out["error"] = f"{type(e).__name__}: {e}"
    except Exception as e:  # pragma: no cover
        out["error"] = f"{type(e).__name__}: {e}"
    return out

def probe_local(source: DataSource) -> dict:
    """Inspect the local cache.

    Returns:
        {exists: bool, last_refresh: datetime|None, size: int|None,
         path: str}
    """
    path = source.cache_path()
    out: dict[str, Any] = {
        "exists": False, "last_refresh": None,
        "size": None, "path": str(path),
    }
    try:
        if not path.exists():
            return out
        out["exists"] = True
        if path.is_file():
            st = path.stat()
            out["size"] = int(st.st_size)
            out["last_refresh"] = _dt.datetime.fromtimestamp(
                st.st_mtime, tz=_dt.timezone.utc,
            )
        elif path.is_dir():
            # Directory: take the newest file's mtime + sum sizes.
            newest = 0.0
            total = 0
            for root, _dirs, files in os.walk(path):
                for f in files:
                    p = pathlib.Path(root) / f
                    try:
                        s = p.stat()
                    except OSError:
                        continue
                    total += int(s.st_size)
                    if s.st_mtime > newest:
                        newest = s.st_mtime
            out["size"] = total
            if newest > 0:
                out["last_refresh"] = _dt.datetime.fromtimestamp(
                    newest, tz=_dt.timezone.utc,
                )
    except OSError as e:
        out["error"] = f"{type(e).__name__}: {e}"
    return out

def _age_days(then: Optional[_dt.datetime],
              now: Optional[_dt.datetime] = None) -> float:
    """Wallclock age in days, or +inf if `then` is missing."""
    if then is None:
        return math.inf
    if now is None:
        now = _dt.datetime.now(_dt.timezone.utc)
    if then.tzinfo is None:
        then = then.replace(tzinfo=_dt.timezone.utc)
    return max(0.0, (now - then).total_seconds() / 86400.0)

def is_stale(source: DataSource,
             now: Optional[_dt.datetime] = None,
             upstream: Optional[dict] = None) -> bool:
    """True iff the local cache is older than the source's threshold,
    or its etag has drifted from the upstream's, or it doesn't exist.

    Always returns a *bool* (never None / str / Exception)."""
    if math.isinf(source.max_staleness_days) and source.kind == "embedded":
        # Embedded sources never auto-stale.
        return False
    local = probe_local(source)
    if not local["exists"]:
        return True
    age = _age_days(local["last_refresh"], now=now)
    if age > source.max_staleness_days:
        return True
    if upstream and upstream.get("etag"):
        marker = source.cache_path().with_suffix(
            source.cache_path().suffix + ".etag"
        )
        try:
            local_etag = marker.read_text(encoding="utf-8").strip()
        except OSError:
            local_etag = ""
        if local_etag and local_etag != upstream["etag"]:
            return True
    return False

def freshness_report(sources: Optional[list[DataSource]] = None,
                     format: str = "dict",
                     probe_timeout: float = _HEAD_TIMEOUT) -> Any:
    """Probe every source and emit a structured report.

    format='dict'      -> {generated_at: iso, rows: [row, ...], summary: {...}}
    format='markdown'  -> str (Markdown table for CI summary)

    Network failures on any single upstream become row-level errors,
    not exceptions.
    """
    srcs = list(sources) if sources is not None else list(SOURCE_REGISTRY)
    now = _dt.datetime.now(_dt.timezone.utc)
    rows: list[dict] = []
    for s in srcs:
        try:
            up = probe_upstream(s, timeout=probe_timeout)
        except Exception as e:  # pragma: no cover — defensive
            up = {"last_modified": None, "etag": None, "size": None,
                  "status": None, "error": f"{type(e).__name__}: {e}"}
        try:
            loc = probe_local(s)
        except Exception as e:  # pragma: no cover
            loc = {"exists": False, "last_refresh": None,
                   "size": None, "path": str(s.cache_path()),
                   "error": f"{type(e).__name__}: {e}"}
        rows.append(_row(s, up, loc, now))

    n_stale = sum(1 for r in rows if r["stale"])
    n_unreachable = sum(1 for r in rows if r["upstream_error"])
    summary = {
        "n_sources": len(rows),
        "n_stale": n_stale,
        "n_unreachable": n_unreachable,
        "healthy": (n_stale == 0),
    }
    payload = {
        "generated_at": now.isoformat(),
        "rows": rows,
        "summary": summary,
    }
    if format == "dict":
        return payload
    if format == "markdown":
        return _to_markdown(payload)
    raise ValueError(f"unknown format: {format!r}")

def cache_path(self) -> pathlib.Path:
    """Resolve the local cache artifact path lazily."""
    return self.local_cache_path()

def _load_via_package() -> Optional[tuple[list[dict], list[dict]]]:
    """Try the packaged CSVs from `database_knotinfo`. Returns (knots, links) or None."""
    try:
        from database_knotinfo import link_list as _link_list  # type: ignore
    except Exception:
        return None
    try:
        knots = _link_list(proper_links=False)
        links = _link_list(proper_links=True)
    except Exception:
        return None
    if not knots:
        return None
    return knots, links

def _load_csv_from_url(url: str) -> Optional[list[dict]]:
    """Download a KnotInfo-style pipe-delimited CSV and parse to list[dict]."""
    import csv
    try:
        r = requests.get(url, headers={"User-Agent": _USER_AGENT},
                         timeout=_DEFAULT_TIMEOUT)
    except requests.RequestException:
        return None
    if r.status_code != 200 or not r.text:
        return None
    try:
        reader = csv.DictReader(io.StringIO(r.text), delimiter="|")
        rows = list(reader)
    except Exception:
        return None
    return rows or None

def _load_via_network() -> Optional[tuple[list[dict], list[dict]]]:
    """Try direct CSV downloads from KnotInfo / LinkInfo. Returns what we got
    (each side may be None if its server is unreachable)."""
    knots = None
    for url in _KNOT_CSV_URLS:
        knots = _load_csv_from_url(url)
        if knots:
            break
    links = None
    for url in _LINK_CSV_URLS:
        links = _load_csv_from_url(url)
        if links:
            break
    if knots is None and links is None:
        return None
    return knots or [], links or []

def _ensure_loaded() -> None:
    """Populate the module-level cache exactly once. Idempotent."""
    with _lock:
        if _cache["knots_by_name"] is not None:
            return
        # Strategy 1: pip package (preferred — no network).
        result = _load_via_package()
        source = "database_knotinfo"
        if result is None:
            result = _load_via_network()
            source = "csv-network"
        if result is None:
            _cache["knots_by_name"] = {}
            _cache["knots_list"] = []
            _cache["links_by_name"] = {}
            _cache["links_list"] = []
            _cache["source"] = None
            _cache["load_error"] = "all backends failed (no package, no network)"
            return

        knots_raw, links_raw = result
        knots = [_shape_knot(row) for row in (knots_raw or [])
                 if _is_real_data_row(row)]
        links = [_shape_link(row) for row in (links_raw or [])
                 if _is_real_data_row(row)]

        # Index by canonical name plus all known aliases.
        knots_by_name: dict[str, dict] = {}
        for k in knots:
            for alias in _name_aliases(k["name"]):
                knots_by_name.setdefault(alias, k)

        links_by_name: dict[str, dict] = {}
        for ll in links:
            for alias in _name_aliases(ll["name"]):
                links_by_name.setdefault(alias, ll)

        _cache["knots_list"] = knots
        _cache["knots_by_name"] = knots_by_name
        _cache["links_list"] = links
        _cache["links_by_name"] = links_by_name
        _cache["source"] = source
        _cache["load_error"] = None

def _is_real_data_row(row: dict) -> bool:
    """The first row of every KnotInfo CSV is a 'pretty header' row whose
    'name' field is literally 'Name'. Filter that out."""
    n = (row or {}).get("name", "")
    if not n or not isinstance(n, str):
        return False
    s = n.strip()
    if not s:
        return False
    if s.lower() == "name":
        return False
    return True

def _name_aliases(canonical: str) -> list[str]:
    """All input forms that should resolve to this canonical name."""
    out = {canonical, canonical.lower()}
    # 3_1 -> 3.1, 31 (well, 3a1 etc)
    m = re.match(r"^(\d+)([an]?)_(\d+)$", canonical)
    if m:
        cn, cls, idx = m.group(1), m.group(2), m.group(3)
        forms = [
            f"{cn}_{idx}",
            f"{cn}.{idx}" if not cls else f"{cn}{cls}.{idx}",
            f"{cn}{cls}{idx}" if cls else f"{cn}_{idx}",
            f"{cn}{cls}_{idx}",
            f"K{cn}{cls}_{idx}",
            f"K{cn}{cls}{idx}",
            f"k{cn}{cls}_{idx}",
        ]
        for f in forms:
            out.add(f)
            out.add(f.lower())
    return list(out)

def _parse_int(s: Any) -> Optional[int]:
    if s is None:
        return None
    if isinstance(s, int):
        return s
    s = str(s).strip()
    if not s:
        return None
    # Some KnotInfo cells are e.g. '-2' or '0' or '1'; strip any junk.
    try:
        return int(s)
    except ValueError:
        # Sometimes 'g4' fields contain ranges like '0,1' meaning lower=0 upper=1.
        # We refuse to guess; return None.
        return None

def _parse_float(s: Any) -> Optional[float]:
    if s is None:
        return None
    if isinstance(s, (int, float)):
        return float(s)
    s = str(s).strip()
    if not s:
        return None
    try:
        return float(s)
    except ValueError:
        return None

def _parse_yes_no(s: Any) -> Optional[bool]:
    if s is None:
        return None
    s = str(s).strip().lower()
    if s in ("y", "yes", "true", "1"):
        return True
    if s in ("n", "no", "false", "0"):
        return False
    return None

def _parse_alex_vector(s: Any) -> Optional[list[int]]:
    """Parse KnotInfo's alexander_polynomial_vector format.

    Format (per KnotInfo docs):  '[lo_degree, length, c_lo, c_lo+1, ..., c_hi]'

    Returns the bare coefficient list in ascending degree order, e.g.
    trefoil's '[0, 2, 1, -1, 1]' -> [1, -1, 1] meaning 1 - t + t^2.
    """
    if s is None:
        return None
    txt = str(s).strip()
    if not txt:
        return None
    if txt.startswith("["):
        txt = txt[1:]
    if txt.endswith("]"):
        txt = txt[:-1]
    parts = [p.strip() for p in txt.split(",") if p.strip()]
    if len(parts) < 3:
        return None
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        return None
    # First two entries are degree-min and length; the rest are coefficients.
    return nums[2:] or None

def _shape_knot(row: dict) -> dict:
    """Convert a raw KnotInfo CSV row into our normalized dict."""
    out: dict[str, Any] = {"name": (row.get("name") or "").strip()}

    for canonical, raw_key, parser in _KNOT_FIELDS:
        raw_val = row.get(raw_key, "")
        if raw_val == "" or raw_val is None:
            continue
        try:
            parsed = parser(raw_val)
        except Exception:
            parsed = None
        if parsed is None and parser is str:
            parsed = str(raw_val).strip() or None
        if parsed is not None and not (isinstance(parsed, str) and not parsed):
            out[canonical] = parsed

    # Aliases / derived fields.
    if "three_genus" in out:
        out.setdefault("genus", out["three_genus"])
        out.setdefault("seifert_genus", out["three_genus"])

    # hyperbolic_volume: present and >0 means hyperbolic.
    vol = out.pop("hyperbolic_volume_raw", None)
    if vol is not None and vol > 0:
        out["hyperbolic_volume"] = vol
        out["hyperbolic"] = True
    else:
        out["hyperbolic_volume"] = None
        out["hyperbolic"] = False

    # Slice genera: KnotInfo separates smooth and topological. Provide a
    # conventional 'slice_genus_smooth' / 'slice_genus_topological' alias.
    if "smooth_four_genus" in out:
        out["slice_genus_smooth"] = out["smooth_four_genus"]
    if "topological_four_genus" in out:
        out["slice_genus_topological"] = out["topological_four_genus"]
    if "smooth_concordance_genus" in out:
        out["concordance_genus"] = out["smooth_concordance_genus"]

    # Alexander polynomial coefficients, parsed to list[int].
    apv = row.get("alexander_polynomial_vector")
    coeffs = _parse_alex_vector(apv)
    if coeffs is not None:
        out["alexander_coeffs"] = coeffs

    # L-space classification: KnotInfo uses 'Yes' / 'No'.
    ls = (row.get("l_space") or "").strip().lower()
    if ls == "yes":
        out["l_space"] = True
    elif ls == "no":
        out["l_space"] = False
    else:
        out["l_space"] = None

    # nu (HFK invariant): often missing in KnotInfo; we expose it as None
    # to keep the documented surface stable.
    out["nu"] = _parse_int(row.get("nu"))

    return out

def _shape_link(row: dict) -> dict:
    """Minimal shaping for a LinkInfo row. We expose the raw KnotInfo dict
    plus a couple of normalized keys; full link-invariant parsing isn't
    implemented yet (Prometheus's first uses are knot-only)."""
    out: dict[str, Any] = {"name": (row.get("name") or "").strip()}
    for key in ("crossing_number", "braid_index", "alternating"):
        v = row.get(key)
        if v in (None, ""):
            continue
        if key == "alternating":
            out[key] = _parse_yes_no(v)
        else:
            iv = _parse_int(v)
            if iv is not None:
                out[key] = iv
    # Preserve a handful of polynomial fields verbatim (LinkInfo convention).
    for key in ("homflypt_polynomial", "jones_polynomial",
                "multivariable_alexander_polynomial"):
        v = row.get(key)
        if v:
            out[key] = str(v).strip()
    return out

def lookup(name) -> Optional[dict]:
    """Look up a knot by name.

    Accepts canonical KnotInfo names ('3_1', '4_1', '11n_34') as well as
    common variants ('3.1', '3a1', 'K3_1', 'K11n34'). Returns the
    normalized dict described in the module docstring, or None if not
    found.
    """
    _ensure_loaded()
    by_name: dict[str, dict] = _cache["knots_by_name"] or {}
    if not by_name:
        return None
    # First try exact match.
    if name in by_name:
        return by_name[name]
    canon = _canonical_knot_name(name)
    if canon is None:
        return None
    return by_name.get(canon)

def filter(crossing_number: Any = None,
           genus: Any = None,
           alternating: Any = None,
           determinant: Any = None,
           hyperbolic: Any = None,
           signature: Any = None,
           fibered: Any = None,
           l_space: Any = None) -> list[dict]:
    """Filter knots by computed invariants.

    Each parameter is either:
      * None         - don't filter on this attribute
      * a value      - exact match
      * a (lo, hi) tuple - inclusive range (numeric attributes only)

    Boolean filters (alternating, hyperbolic, fibered, l_space) accept
    True/False, and treat None values in the data as a non-match.
    """
    _ensure_loaded()
    knots: list[dict] = list(_cache["knots_list"] or [])

    def _match_numeric(val, spec) -> bool:
        if val is None:
            return False
        if isinstance(spec, tuple) and len(spec) == 2:
            lo, hi = spec
            try:
                return (lo is None or val >= lo) and (hi is None or val <= hi)
            except TypeError:
                return False
        return val == spec

    def _match_bool(val, spec) -> bool:
        if val is None:
            return False
        return bool(val) == bool(spec)

    out = []
    for k in knots:
        if crossing_number is not None and not _match_numeric(
                k.get("crossing_number"), crossing_number):
            continue
        if genus is not None and not _match_numeric(
                k.get("three_genus"), genus):
            continue
        if determinant is not None and not _match_numeric(
                k.get("determinant"), determinant):
            continue
        if signature is not None and not _match_numeric(
                k.get("signature"), signature):
            continue
        if alternating is not None and not _match_bool(
                k.get("alternating"), alternating):
            continue
        if fibered is not None and not _match_bool(
                k.get("fibered"), fibered):
            continue
        if hyperbolic is not None and not _match_bool(
                k.get("hyperbolic"), hyperbolic):
            continue
        if l_space is not None and not _match_bool(
                k.get("l_space"), l_space):
            continue
        out.append(k)
    return out

def alexander(name) -> Optional[list[int]]:
    """Alexander polynomial coefficients of `name`, ascending degree.

    Returns e.g. [1, -3, 1] for the figure-8 knot 4_1 (i.e. 1 - 3t + t^2).
    Sign convention matches KnotInfo's vector representation directly.
    """
    rec = lookup(name)
    if rec is None:
        return None
    coeffs = rec.get("alexander_coeffs")
    if coeffs is None:
        return None
    return list(coeffs)

def signature(name) -> Optional[int]:
    """Knot signature (always an even integer for knots; positive or negative)."""
    rec = lookup(name)
    return None if rec is None else rec.get("signature")

def is_l_space(name) -> Optional[bool]:
    """Whether the knot is an L-space knot (per HFK detection in KnotInfo).

    Returns True / False / None (unknown / not in census).
    """
    rec = lookup(name)
    return None if rec is None else rec.get("l_space")

def list_l_space_knots(crossing_max: int = 13) -> list[str]:
    """Names of every L-space knot in the KnotInfo census up to `crossing_max`."""
    return [k["name"] for k in filter(crossing_number=(0, crossing_max),
                                      l_space=True)]

def link_lookup(name: str) -> Optional[dict]:
    """Look up a link by LinkInfo name (e.g. 'L4a1{0}', 'L6n1{1,1}')."""
    _ensure_loaded()
    by_name: dict[str, dict] = _cache["links_by_name"] or {}
    if not by_name:
        return None
    if name in by_name:
        return by_name[name]
    return by_name.get(name.lower())

def all_links() -> list[dict]:
    """Every link in the LinkInfo census (~4,189 entries)."""
    _ensure_loaded()
    return list(_cache["links_list"] or [])

def cache_info() -> dict:
    """Diagnostics for the in-memory cache."""
    knots = _cache["knots_list"]
    links = _cache["links_list"]
    return {
        "knots_loaded": len(knots) if knots is not None else 0,
        "links_loaded": len(links) if links is not None else 0,
        "source":       _cache["source"],
        "load_error":   _cache["load_error"],
    }

def probe(timeout: float = 3.0) -> bool:
    """Cheap availability check used by prometheus_math.registry.

    The wrapper is "available" if either:
      (a) the `database_knotinfo` PyPI package is importable AND yields
          a non-empty knot list, or
      (b) the live KnotInfo CSV is reachable in `timeout` seconds.

    No network is hit when (a) succeeds.
    """
    # Fast path: package is importable.
    try:
        from database_knotinfo import link_list as _link_list  # type: ignore
        rows = _link_list(proper_links=False)
        if rows and len(rows) > 100:
            return True
    except Exception:
        pass

    # Slow path: HEAD/GET the live CSV with a tight timeout.
    for url in _KNOT_CSV_URLS:
        try:
            r = requests.head(url, headers={"User-Agent": _USER_AGENT},
                              timeout=timeout, allow_redirects=True)
        except requests.RequestException:
            continue
        if r.status_code == 200:
            return True
    return False

def _pip_version() -> Optional[str]:
    """Currently installed `database_knotinfo` version, or None if not installed.

    Uses importlib.metadata which is part of Python 3.8+ stdlib; no
    network access. Returns None rather than raising when the package
    is absent so the caller can degrade gracefully.
    """
    try:
        import importlib.metadata as _md
        return _md.version("database_knotinfo")
    except Exception:
        return None

def _latest_pypi_version(timeout: float = 5.0) -> Optional[str]:
    """Latest released `database_knotinfo` version on PyPI, or None if PyPI
    is unreachable / response is malformed. Network call.

    The caller is responsible for any retry / caching policy; this fn
    issues a single GET with the supplied timeout and returns None on
    any failure (no exception escapes).
    """
    try:
        r = requests.get(_PYPI_JSON_URL,
                         headers={"User-Agent": _USER_AGENT,
                                  "Accept": "application/json"},
                         timeout=timeout)
    except requests.RequestException:
        return None
    if r.status_code != 200:
        return None
    try:
        info = r.json().get("info") or {}
        v = info.get("version")
        if isinstance(v, str) and v:
            return v
    except Exception:
        return None
    return None

def _semver_lt(a: str, b: str) -> bool:
    """Best-effort 'is version a strictly older than b?' comparator.

    `database_knotinfo` uses calendar-style versions (e.g. '2026.4.1');
    naïve lexicographic comparison would fail at digit boundaries
    ('2026.10.1' < '2026.2.1'). We fall back to packaging.version when
    available and to a tuple-of-ints split on '.' otherwise. Unknown
    forms compare equal (no upgrade signaled).
    """
    if not a or not b or a == b:
        return False
    try:
        from packaging.version import Version  # type: ignore
        return Version(a) < Version(b)
    except Exception:
        pass
    try:
        ta = tuple(int(x) for x in a.split(".") if x.isdigit())
        tb = tuple(int(x) for x in b.split(".") if x.isdigit())
        if ta and tb:
            return ta < tb
    except Exception:
        pass
    return False

def _match_numeric(val, spec) -> bool:
    if val is None:
        return False
    if isinstance(spec, tuple) and len(spec) == 2:
        lo, hi = spec
        try:
            return (lo is None or val >= lo) and (hi is None or val <= hi)
        except TypeError:
            return False
    return val == spec

def _match_bool(val, spec) -> bool:
    if val is None:
        return False
    return bool(val) == bool(spec)

