def connect(timeout: int = 10) -> psycopg2.extensions.connection:
    """Open a new connection to the LMFDB Postgres mirror.

    The caller is responsible for ``close()`` (or use as a context manager;
    psycopg2 connections support ``with``).
    """
    try:
        return psycopg2.connect(
            host=LMFDB_HOST,
            port=LMFDB_PORT,
            dbname=LMFDB_DBNAME,
            user=LMFDB_USER,
            password=LMFDB_PASSWORD,
            connect_timeout=timeout,
        )
    except psycopg2.OperationalError as e:
        raise LMFDBConnectionError(
            f"Could not connect to LMFDB mirror at {LMFDB_HOST}:{LMFDB_PORT} "
            f"(dbname={LMFDB_DBNAME}). The mirror may be unreachable, your "
            f"network blocked, or the connection timed out after {timeout}s. "
            f"Original error: {e}"
        ) from e

def _maybe_conn(conn: Optional[psycopg2.extensions.connection], timeout: int):
    """Yield ``conn`` if provided, else open a fresh one and close it."""
    if conn is not None:
        yield conn
        return
    own = connect(timeout=timeout)
    try:
        yield own
    finally:
        try:
            own.close()
        except Exception:
            pass

def _coerce_scalar(v: Any) -> Any:
    if isinstance(v, Decimal):
        # int when integral, else float
        if v == v.to_integral_value():
            try:
                return int(v)
            except (OverflowError, ValueError):
                return float(v)
        return float(v)
    return v

def _coerce_value(v: Any) -> Any:
    if v is None:
        return None
    if isinstance(v, Decimal):
        return _coerce_scalar(v)
    if isinstance(v, list):
        return [_coerce_value(x) for x in v]
    if isinstance(v, tuple):
        return tuple(_coerce_value(x) for x in v)
    return v

def _build_select(
    table: str,
    columns: Optional[list[str]],
    filters: dict[str, Any],
    extra_clauses: Optional[list[tuple[str, Any]]] = None,
    limit: Optional[int] = None,
) -> tuple[str, list[Any]]:
    """Build a parameterized SELECT statement.

    Identifiers (``table``, ``columns``, filter keys) are NOT user-provided
    here — they are constants from the typed accessors below. Values flow
    through ``%s`` placeholders.
    """
    col_sql = "*" if not columns else ", ".join(f'"{c}"' for c in columns)
    sql = f'SELECT {col_sql} FROM "{table}"'
    where_parts: list[str] = []
    params: list[Any] = []
    for key, val in filters.items():
        if val is None:
            continue
        where_parts.append(f'"{key}" = %s')
        params.append(val)
    if extra_clauses:
        for clause, val in extra_clauses:
            where_parts.append(clause)
            if val is not None:
                if isinstance(val, (list, tuple)):
                    params.extend(val)
                else:
                    params.append(val)
    if where_parts:
        sql += " WHERE " + " AND ".join(where_parts)
    if limit is not None:
        sql += " LIMIT %s"
        params.append(int(limit))
    return sql, params

def _validate_newform_label(label: str) -> tuple[int, int, str, str]:
    """Parse and validate an LMFDB newform label ``N.k.x.y``.

    Returns ``(level, weight, char_orbit_letter, hecke_orbit_letter)``.
    Raises ``ValueError`` on malformed input.
    """
    if not isinstance(label, str) or not label:
        raise ValueError(f"invalid newform label: {label!r} (must be non-empty string)")
    parts = label.split(".")
    if len(parts) != 4:
        raise ValueError(
            f"invalid newform label: {label!r} (expected 'N.k.x.y' with 4 dot-separated parts)"
        )
    try:
        level = int(parts[0])
        weight = int(parts[1])
    except ValueError as e:
        raise ValueError(
            f"invalid newform label: {label!r} (level and weight must be integers)"
        ) from e
    if level <= 0 or weight < 1:
        raise ValueError(
            f"invalid newform label: {label!r} (level must be positive, weight >= 1)"
        )
    if not parts[2] or not parts[3]:
        raise ValueError(f"invalid newform label: {label!r} (empty char/hecke orbit)")
    return level, weight, parts[2], parts[3]

def _atkin_lehner_to_dict(eigenvals: Optional[list]) -> dict[int, int]:
    """Convert LMFDB ``atkin_lehner_eigenvals`` list-of-pairs to a dict.

    LMFDB stores Atkin-Lehner data as a list of ``[prime, eigenvalue]``
    pairs (e.g. ``[[11, -1]]``). We convert to a normal Python dict
    ``{prime: ±1}``. Returns ``{}`` if the input is None or empty.
    """
    out: dict[int, int] = {}
    if not eigenvals:
        return out
    for entry in eigenvals:
        if entry is None or len(entry) < 2:
            continue
        try:
            p = int(entry[0])
            v = int(entry[1])
        except (TypeError, ValueError):
            continue
        out[p] = v
    return out

def _primes_up_to(n: int) -> list[int]:
    """Return all primes <= n via a simple sieve. Cheap, no deps."""
    if n < 2:
        return []
    sieve = bytearray(b"\x01") * (n + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytes(len(sieve[i * i :: i]))
    return [i for i in range(2, n + 1) if sieve[i]]

def newform_hecke_eigenvalues_full(
    label: str,
    p_max: int = 1000,
    conn: Optional[psycopg2.extensions.connection] = None,
    timeout: int = 10,
) -> dict[int, list[int]]:
    """All stored Hecke eigenvalues a_p for primes p <= p_max.

    For dimension-1 newforms each value is a single Python int; for
    dim > 1 each value is a list of integers (power-basis coefficients
    in the Hecke ring's chosen basis).

    Parameters
    ----------
    label : LMFDB newform label.
    p_max : Inclusive upper bound on primes to return (default 1000).

    Returns
    -------
    dict mapping prime ``p`` -> ``a_p`` (int for dim=1, list[int] for dim>1).
    Empty dict if the newform is not in ``mf_hecke_nf`` or stores fewer ap.
    """
    _validate_newform_label(label)
    if p_max < 2:
        return {}

    sql = (
        'SELECT "ap", "maxp", "hecke_ring_rank" FROM "mf_hecke_nf" '
        'WHERE "label" = %s LIMIT 1'
    )
    rows = query(sql, (label,), timeout=timeout, conn=conn)
    if not rows:
        return {}
    ap, maxp, _rank = rows[0]
    if ap is None:
        return {}
    primes = _primes_up_to(min(int(p_max), int(maxp) if maxp else int(p_max)))
    out: dict[int, list[int]] = {}
    for i, p in enumerate(primes):
        if i >= len(ap):
            break
        v = ap[i]
        if isinstance(v, list) and len(v) == 1:
            out[p] = int(v[0])
        elif isinstance(v, list):
            out[p] = [int(x) for x in v]
        else:
            out[p] = v
    return out

def _normalize(coeffs: list[int]) -> list[int]:
    """Strip trailing zeros and return a canonical ascending list."""
    out = list(coeffs)
    while len(out) > 1 and out[-1] == 0:
        out.pop()
    return out

def _entries() -> list[dict]:
    """Return a *deep* copy of the embedded table.

    We never expose live references to the snapshot; mutating returned
    dicts must not poison the catalog.
    """
    return copy.deepcopy(MAHLER_TABLE)

def lookup_polynomial(coeffs: list[int]) -> Optional[dict]:
    """Find a catalog entry matching these ascending coefficients.

    Mahler measure is invariant under the substitution x -> -x, so we
    also try the sign-flipped form.  Returns the first matching entry
    (deep-copied) or ``None``.
    """
    target = _normalize(list(coeffs))
    target_flip = _normalize(_x_flip(target))
    for e in MAHLER_TABLE:
        c = _normalize(list(e["coeffs"]))
        if c == target or c == target_flip:
            return copy.deepcopy(e)
    return None

def _is_cyclotomic_poly_sympy(f, x, max_n: int = _DEFAULT_MAX_CYCLOTOMIC_N
                              ) -> Optional[int]:
    """If ``f`` (sympy expression in ``x``) equals Phi_n for some n in
    [1, max_n], return that n; otherwise return None.

    Comparison is done at the polynomial-coefficient level (not sympy
    structural equality) so that algebraically-equal but structurally
    different forms still match.
    """
    import sympy as sp

    try:
        f_poly = sp.Poly(f, x, domain=sp.ZZ)
    except Exception:
        return None
    deg_f = f_poly.degree()
    if deg_f < 1:
        return None
    # phi(n) = deg_f restricts the candidate range; iterate small n until
    # phi(n) > max possible deg_f. We keep a tight per-call cap.
    for n in range(1, int(max_n) + 1):
        try:
            phi = sp.cyclotomic_poly(n, x)
        except Exception:
            continue
        try:
            phi_poly = sp.Poly(phi, x, domain=sp.ZZ)
        except Exception:
            continue
        if phi_poly.degree() != deg_f:
            continue
        if phi_poly == f_poly:
            return n
    return None

def _ascending_from_sympy_poly(poly, x) -> list[int]:
    """Extract ascending integer coefficients from a sympy Poly/Expr."""
    import sympy as sp

    if not isinstance(poly, sp.Poly):
        poly = sp.Poly(poly, x, domain=sp.ZZ)
    desc = [int(c) for c in poly.all_coeffs()]
    return list(reversed(desc))

def lehmer_witness() -> dict:
    """Return Lehmer's degree-10 polynomial entry.

    This is the polynomial conjecturally achieving the global infimum
    M = 1.17628081826... -- Lehmer's conjecture asserts no integer
    polynomial has smaller non-trivial Mahler measure.
    """
    for e in MAHLER_TABLE:
        if e.get("lehmer_witness", False):
            return copy.deepcopy(e)
    raise RuntimeError("Lehmer witness missing from embedded snapshot "
                       "-- this should never happen.")

def count_by_degree() -> dict[int, int]:
    """Return ``{degree: number_of_entries}`` across the whole catalog.

    Useful for stats reporting and quick coverage audits (e.g. "do we
    have any deg-22 entries?").
    """
    out: dict[int, int] = {}
    for e in MAHLER_TABLE:
        d = e["degree"]
        out[d] = out.get(d, 0) + 1
    return dict(sorted(out.items()))

def degree_minima() -> dict[int, dict]:
    """Map ``degree -> smallest-known Mahler-measure entry`` at each
    degree present in the catalog.

    Only entries flagged ``degree_minimum=True`` are eligible; if
    multiple flagged entries share the same degree (e.g. catalog
    revisions) the one with smallest M wins.
    """
    by_deg: dict[int, dict] = {}
    for e in MAHLER_TABLE:
        if not e.get("degree_minimum", False):
            continue
        d = e["degree"]
        cur = by_deg.get(d)
        if cur is None or e["mahler_measure"] < cur["mahler_measure"]:
            by_deg[d] = copy.deepcopy(e)
    return dict(sorted(by_deg.items()))

def _normalize_a_number(a_number) -> str:
    """Coerce 45, 'a45', 'A45', 'A000045' all to canonical 'A000045'."""
    if isinstance(a_number, int):
        n = a_number
    else:
        s = str(a_number).strip().upper()
        if s.startswith("A"):
            s = s[1:]
        if not s.isdigit():
            raise ValueError(f"not a valid A-number: {a_number!r}")
        n = int(s)
    if n < 0 or n > 9_999_999:
        raise ValueError(f"A-number out of range: {a_number!r}")
    return f"A{n:06d}"

def _http_get(url: str, params: Optional[dict] = None,
              accept_json: bool = True) -> Optional[requests.Response]:
    """Perform a polite, throttled GET. Returns Response or None on failure."""
    _throttle()
    headers = {"User-Agent": _USER_AGENT}
    if accept_json:
        headers["Accept"] = "application/json"
    try:
        r = requests.get(url, params=params, headers=headers,
                         timeout=_DEFAULT_TIMEOUT)
    except requests.RequestException:
        return None
    if r.status_code != 200:
        return None
    return r

def _parse_data_field(s: str) -> list[int]:
    """OEIS 'data' is a comma-separated string of integers."""
    if not s:
        return []
    out: list[int] = []
    for tok in s.split(","):
        tok = tok.strip()
        if not tok:
            continue
        try:
            out.append(int(tok))
        except ValueError:
            # Some sequences include things like 'inf' or fractions; skip.
            continue
    return out

def _parse_offset(s: str) -> tuple:
    """OEIS 'offset' is e.g. '0,3' meaning offset=0, first |a(n)|>1 at n=3."""
    if not s:
        return ()
    parts = []
    for tok in s.split(","):
        tok = tok.strip()
        try:
            parts.append(int(tok))
        except ValueError:
            pass
    return tuple(parts)

def _extract_cross_refs(xref_lines: Iterable[str]) -> list[str]:
    """Pull all A-numbers mentioned in xref lines, deduped, in order."""
    seen: set[str] = set()
    out: list[str] = []
    for line in xref_lines or []:
        for m in _A_RE.finditer(line):
            try:
                an = _normalize_a_number(m.group(0))
            except ValueError:
                continue
            if an not in seen:
                seen.add(an)
                out.append(an)
    return out

def find_sequence(values: Iterable[int], max_results: int = 10) -> list[dict]:
    """Convenience: 'I have these N integers — what sequences match?'.

    Resolution priority:
      1. Local mirror prefix index (when present and use_local_first()).
      2. Live OEIS sequence search.
    """
    seq = [int(v) for v in values]
    if not seq:
        return []
    if has_local_mirror() and use_local_first():
        local_hits = _local_find_sequence(seq, max_results=max_results)
        if local_hits:
            return local_hits
    return search(sequence=seq, max_results=max_results)

def cache_info() -> dict:
    """Diagnostics for the in-memory cache."""
    return {
        "json_entries":  len(_json_cache),
        "bfile_entries": len(_bfile_cache),
        "min_interval":  _MIN_INTERVAL,
        "user_agent":    _USER_AGENT,
    }

def _parse_stripped_line(line: str) -> Optional[tuple[str, list[int]]]:
    """Parse one line of stripped.gz: ``A000045 ,0,1,1,2,3,5,...,``.

    Returns (a_number, [int, ...]) or None on malformed lines.
    Lines beginning with '#' are comments.
    """
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    # Split on first whitespace to separate the A-num from the data.
    parts = line.split(None, 1)
    if len(parts) != 2:
        return None
    a_id, body = parts
    if not (a_id.startswith("A") and a_id[1:].isdigit()):
        return None
    body = body.strip().strip(",")
    if not body:
        return (a_id, [])
    out: list[int] = []
    for tok in body.split(","):
        tok = tok.strip()
        if not tok:
            continue
        try:
            out.append(int(tok))
        except ValueError:
            # Some sequences carry signs or unparseable cells; skip silently.
            continue
    return (a_id, out)

def _parse_names_line(line: str) -> Optional[tuple[str, str]]:
    """Parse one line of names.gz: ``A000045\tFibonacci numbers: ...``."""
    line = line.rstrip("\n").rstrip("\r")
    if not line or line.startswith("#"):
        return None
    # Names file is TAB-delimited.
    if "\t" in line:
        a_id, name = line.split("\t", 1)
    else:
        # Fallback: first token + rest.
        parts = line.split(None, 1)
        if len(parts) != 2:
            return None
        a_id, name = parts
    a_id = a_id.strip()
    if not (a_id.startswith("A") and a_id[1:].isdigit()):
        return None
    return (a_id, name.strip())

def _load_local_cache(stripped: pathlib.Path,
                      names: pathlib.Path) -> int:
    """Populate _OEIS_LOCAL_CACHE from the gz dumps.  Returns N loaded."""
    _OEIS_LOCAL_CACHE.clear()
    _OEIS_PREFIX_INDEX.clear()
    with gzip.open(stripped, "rt", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            parsed = _parse_stripped_line(line)
            if parsed is None:
                continue
            a_id, data = parsed
            _OEIS_LOCAL_CACHE[a_id] = {"data": data, "name": ""}
    if names.exists():
        with gzip.open(names, "rt", encoding="utf-8", errors="replace") as fh:
            for line in fh:
                parsed = _parse_names_line(line)
                if parsed is None:
                    continue
                a_id, name = parsed
                if a_id in _OEIS_LOCAL_CACHE:
                    _OEIS_LOCAL_CACHE[a_id]["name"] = name
                else:
                    _OEIS_LOCAL_CACHE[a_id] = {"data": [], "name": name}
    return len(_OEIS_LOCAL_CACHE)

def _autoload_if_present() -> None:
    """If the dump files are already on disk, parse them lazily — no network."""
    global _OEIS_LOCAL_LOADED
    if _OEIS_LOCAL_LOADED:
        return
    with _OEIS_LOCAL_LOCK:
        if _OEIS_LOCAL_LOADED:
            return
        if not _local.has_mirror(_OEIS_DATASET, "stripped.gz"):
            return
        base = _local.dataset_path(_OEIS_DATASET)
        try:
            n = _load_local_cache(base / "stripped.gz", base / "names.gz")
        except Exception as e:
            _log.warning("OEIS mirror auto-load failed: %s", e)
            return
        _OEIS_LOCAL_LOADED = n > 0

def has_local_mirror() -> bool:
    """True iff the OEIS local mirror is parsed and ready to serve lookups."""
    if _OEIS_LOCAL_LOADED and _OEIS_LOCAL_CACHE:
        return True
    # Lazy: auto-load if the files exist on disk.
    _autoload_if_present()
    return _OEIS_LOCAL_LOADED and bool(_OEIS_LOCAL_CACHE)

def use_local_first(value: Optional[bool] = None) -> bool:
    """Get or set the global local-first flag.

    With no argument, returns the current effective value (auto-detected
    from `has_local_mirror()` if never explicitly set).  With an argument,
    sets and returns the new value.
    """
    global _OEIS_USE_LOCAL_FIRST
    if value is not None:
        _OEIS_USE_LOCAL_FIRST = bool(value)
        return _OEIS_USE_LOCAL_FIRST
    if _OEIS_USE_LOCAL_FIRST is None:
        # Don't trigger autoload here — has_local_mirror handles that.
        return has_local_mirror()
    return _OEIS_USE_LOCAL_FIRST

def _local_lookup(a_number) -> Optional[dict]:
    """Look up one A-number in the local mirror."""
    if not has_local_mirror():
        return None
    a_id = _normalize_a_number(a_number)
    return _local_record(a_id)

def _local_is_known(values: list[int]) -> Optional[str]:
    hits = _local_find_sequence(values, max_results=1)
    if not hits:
        return None
    return hits[0]["number"]

def _metadata_path() -> pathlib.Path:
    """Absolute path to the on-disk metadata sidecar."""
    return _local.dataset_path(_OEIS_DATASET) / _METADATA_FILE

def _empty_metadata() -> dict:
    """Default skeleton when no mirror exists yet."""
    return {
        "sequences":        0,
        "last_refresh_iso": None,
        "files":            [],
        "size_bytes":       0,
    }

def _http_get(path: str, params: Optional[dict] = None,
              timeout: float = _DEFAULT_TIMEOUT) -> Optional[dict]:
    """Throttled GET against the zbMATH Open API. Returns parsed JSON or None."""
    url = f"{_BASE}{path}"
    cache_key = f"{path}?{tuple(sorted((params or {}).items()))}"
    if cache_key in _cache:
        return _cache[cache_key]
    _throttle()
    headers = {"User-Agent": _USER_AGENT, "Accept": "application/json"}
    try:
        r = requests.get(url, params=params, headers=headers, timeout=timeout)
    except requests.RequestException:
        _cache[cache_key] = None
        return None
    if r.status_code != 200:
        _cache[cache_key] = None
        return None
    try:
        data = r.json()
    except ValueError:
        _cache[cache_key] = None
        return None
    _cache[cache_key] = data
    return data

def _extract_title(record: dict) -> str:
    """zbMATH titles can land in any of several sub-fields depending on
    whether the original was English, translated, or has a subtitle."""
    t = record.get("title") or {}
    if isinstance(t, str):
        return t.strip()
    if not isinstance(t, dict):
        return ""
    for key in ("title", "original", "addition"):
        v = t.get(key)
        if isinstance(v, str) and v.strip():
            return v.strip()
    return ""

def _extract_authors(record: dict) -> list[str]:
    contrib = record.get("contributors") or {}
    authors = contrib.get("authors") or []
    out: list[str] = []
    for a in authors:
        if isinstance(a, dict):
            name = a.get("name")
            if isinstance(name, str) and name.strip():
                out.append(name.strip())
        elif isinstance(a, str) and a.strip():
            out.append(a.strip())
    return out

def _extract_year(record: dict) -> Optional[int]:
    """Year may live at top-level `year` or nested in source.series[0].year."""
    y = record.get("year")
    if isinstance(y, int):
        return y
    if isinstance(y, str) and y.strip().isdigit():
        return int(y.strip())
    src = (record.get("source") or {}).get("series") or []
    if src and isinstance(src[0], dict):
        sy = src[0].get("year")
        if isinstance(sy, str) and sy.strip().isdigit():
            return int(sy.strip())
        if isinstance(sy, int):
            return sy
    return None

def _extract_msc(record: dict) -> list[str]:
    msc = record.get("msc") or []
    out: list[str] = []
    for m in msc:
        if isinstance(m, dict):
            code = m.get("code")
            if isinstance(code, str) and code.strip():
                out.append(code.strip())
        elif isinstance(m, str) and m.strip():
            out.append(m.strip())
    return out

def _extract_journal(record: dict) -> str:
    src = (record.get("source") or {}).get("series") or []
    if src and isinstance(src[0], dict):
        for key in ("short_title", "title"):
            v = src[0].get(key)
            if isinstance(v, str) and v.strip():
                return v.strip()
    return ""

def _extract_doi(record: dict) -> str:
    for link in record.get("links") or []:
        if isinstance(link, dict) and (link.get("type") or "").lower() == "doi":
            ident = link.get("identifier")
            if isinstance(ident, str) and ident.strip():
                return ident.strip()
    return ""

def _extract_abstract(record: dict) -> str:
    """Use the first review/abstract editorial contribution when open."""
    for contrib in record.get("editorial_contributions") or []:
        if not isinstance(contrib, dict):
            continue
        text = contrib.get("text")
        if isinstance(text, str) and text.strip():
            return text.strip()
    return ""

def _extract_keywords(record: dict) -> list[str]:
    kws = record.get("keywords") or []
    return [k.strip() for k in kws if isinstance(k, str) and k.strip()]

def _build_search_string(query: Optional[str] = None,
                         author: Optional[str] = None,
                         msc: Optional[str] = None,
                         year: Optional[int] = None,
                         year_range: Optional[tuple] = None) -> str:
    """Combine kwargs into a zbMATH `search_string`. Year range wins over year."""
    parts: list[str] = []
    if query:
        parts.append(str(query).strip())
    if author:
        a = str(author).strip()
        # Multi-word names: zbMATH accepts "Wiles, Andrew" but quoting is
        # safer with spaces; the API treats commas as field separators in
        # some contexts, so we only quote when there's no comma.
        if " " in a and "," not in a:
            parts.append(f'au:"{a}"')
        else:
            parts.append(f"au:{a}")
    if msc:
        parts.append(f"cc:{str(msc).strip()}")
    if year_range and len(year_range) == 2:
        lo, hi = year_range
        if lo and hi:
            parts.append(f"py:{int(lo)}-{int(hi)}")
        elif lo:
            parts.append(f"py:{int(lo)}-")
        elif hi:
            parts.append(f"py:-{int(hi)}")
    elif year is not None:
        parts.append(f"py:{int(year)}")
    return " ".join(parts).strip()

def get(zbmath_id) -> Optional[dict]:
    """Fetch a single document by zbMATH identifier or numeric internal id.

    Examples:
        get('0823.11029')   # zbMATH-style identifier (Wiles, FLT proof)
        get(732023)         # numeric internal id
    """
    if zbmath_id is None:
        return None
    sid = str(zbmath_id).strip()
    if not sid:
        return None
    data = _http_get(f"/document/{sid}")
    if not data:
        return None
    rec = data.get("result")
    if not isinstance(rec, dict):
        return None
    return _shape_record(rec)

def by_author(author_name: str, max_results: int = 20) -> list[dict]:
    """Papers by an author. Wrapper for ``search(author=...)``.

    zbMATH author resolution is fuzzy: 'Wiles' matches every author whose
    surname contains 'Wiles'. Pass 'Surname, First' to disambiguate when
    needed.
    """
    if not author_name:
        return []
    return search(author=author_name, max_results=max_results)

def reviews(zbmath_id) -> Optional[dict]:
    """Return the open-access review of a paper, if one exists.

    Returns ``{"reviewer": str, "review_text": str, "review_year": int|None}``
    or None when no review is attached or when the record is closed.
    """
    if zbmath_id is None:
        return None
    sid = str(zbmath_id).strip()
    if not sid:
        return None
    data = _http_get(f"/document/{sid}")
    if not data:
        return None
    rec = data.get("result")
    if not isinstance(rec, dict):
        return None
    contribs = rec.get("editorial_contributions") or []
    for c in contribs:
        if not isinstance(c, dict):
            continue
        if (c.get("contribution_type") or "").lower() not in ("review", "abstract"):
            continue
        text = c.get("text") or ""
        if not text.strip():
            continue
        reviewer_obj = c.get("reviewer") or {}
        reviewer = ""
        if isinstance(reviewer_obj, dict):
            reviewer = (reviewer_obj.get("name")
                        or reviewer_obj.get("sign")
                        or "").strip()
        return {
            "reviewer":    reviewer,
            "review_text": text.strip(),
            "review_year": _extract_year(rec),
        }
    return None

def _classify_code(canonical: str) -> str:
    """Return the level of a *canonical* code, or raise KeyError if unknown."""
    if canonical in _msc.TOP:
        return "top"
    if canonical in _msc.SUBJECT:
        return "subject"
    if canonical in _msc.LEAF:
        return "leaf"
    raise KeyError(f"unknown MSC2020 code: {canonical!r}")

def _description_for(canonical: str, level: str) -> str:
    if level == "top":
        return _msc.TOP[canonical]
    if level == "subject":
        return _msc.SUBJECT[canonical]
    return _msc.LEAF[canonical]

def msc_codes(level: str = "leaf") -> list[str]:
    """Return all MSC2020 codes at the requested level, sorted.

    Parameters
    ----------
    level : {'leaf', 'subject', 'top'}
        - ``'leaf'``    -> 5-character codes (e.g. ``"11G05"``); ~6000 entries.
        - ``'subject'`` -> 3-character codes (e.g. ``"11G"``); ~530 entries.
        - ``'top'``     -> 2-character codes (e.g. ``"11"``); 63 entries.

    Raises
    ------
    ValueError
        If ``level`` is not one of the three valid values.
    """
    if level not in _VALID_LEVELS:
        raise ValueError(
            f"unknown level {level!r}; must be one of "
            f"{', '.join(_VALID_LEVELS)}"
        )
    if level == "leaf":
        return sorted(_msc.LEAF.keys())
    if level == "subject":
        return sorted(_msc.SUBJECT.keys())
    return sorted(_msc.TOP.keys())

def msc_descriptions(level: str = "leaf") -> dict[str, str]:
    """Return ``code -> description`` for every MSC2020 code at ``level``.

    The dict is a fresh copy; mutating it does not affect the embedded
    snapshot.
    """
    if level not in _VALID_LEVELS:
        raise ValueError(
            f"unknown level {level!r}; must be one of "
            f"{', '.join(_VALID_LEVELS)}"
        )
    if level == "leaf":
        return dict(_msc.LEAF)
    if level == "subject":
        return dict(_msc.SUBJECT)
    return dict(_msc.TOP)

def msc_search(query: str, max_results: int = 20) -> list[dict]:
    """Substring-match ``query`` against descriptions at every level.

    Returns a list of ``msc_lookup``-shaped dicts, sorted by (level
    priority [leaf, subject, top], code) so the most specific hits come
    first. The match is case-insensitive.

    Raises
    ------
    ValueError
        If ``query`` is empty or whitespace.
    """
    if query is None:
        raise ValueError("msc_search query must not be None")
    needle = str(query).strip().lower()
    if not needle:
        raise ValueError("msc_search query must not be empty")

    out: list[dict] = []
    # Search leaves first (most specific), then subjects, then top.
    for code, desc in _msc.LEAF.items():
        if needle in desc.lower():
            out.append(msc_lookup(code))
            if len(out) >= max_results:
                return out
    for code, desc in _msc.SUBJECT.items():
        if needle in desc.lower():
            out.append(msc_lookup(code))
            if len(out) >= max_results:
                return out
    for code, desc in _msc.TOP.items():
        if needle in desc.lower():
            out.append(msc_lookup(code))
            if len(out) >= max_results:
                return out
    return out

def clear_cache() -> None:
    """Drop every cached response. Mostly useful in tests."""
    _cache.clear()

def cache_info() -> dict:
    """Diagnostics for the in-memory cache."""
    return {
        "entries":      len(_cache),
        "min_interval": _MIN_INTERVAL,
        "user_agent":   _USER_AGENT,
        "base":         _BASE,
    }

def probe(timeout: float = 3.0) -> bool:
    """Cheap availability check used by prometheus_math.registry.

    Hits the search endpoint with a minimal query and tight timeout.
    Returns True iff the API responded with a 200 and a JSON envelope
    we recognize.
    """
    try:
        # `an:` is the zbMATH "accession number" field; an exact-id query
        # gives a cheap, deterministic round-trip without hitting the
        # 404-on-nothing-found branch the bare-id form takes.
        r = requests.get(
            f"{_BASE}/document/_search",
            params={"search_string": "an:0823.11029", "results_per_page": "1"},
            headers={"User-Agent": _USER_AGENT, "Accept": "application/json"},
            timeout=timeout,
        )
    except requests.RequestException:
        return False
    if r.status_code != 200:
        return False
    try:
        data = r.json()
    except ValueError:
        return False
    return isinstance(data, dict) and ("result" in data or "status" in data)

def _factor(n: int) -> list[tuple[int, int]]:
    """Plain trial-division factorisation; only used at module load."""
    out: list[tuple[int, int]] = []
    if n <= 1:
        return out
    p = 2
    while p * p <= n:
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            out.append((p, e))
        p += 1 if p == 2 else 2
    if n > 1:
        out.append((n, 1))
    return out

def _factored_str(decomp: list[tuple[int, int]]) -> str:
    if not decomp:
        return "1"
    parts = []
    for p, e in decomp:
        parts.append(f"{p}" if e == 1 else f"{p}^{e}")
    return " * ".join(parts)

def _is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def _factorial(n: int) -> int:
    out = 1
    for k in range(2, n + 1):
        out *= k
    return out

def _lcm_range(n: int) -> int:
    from math import gcd
    out = 1
    for k in range(1, n + 1):
        out = out * k // gcd(out, k)
    return out

def _outer_sn(n: int) -> tuple[str, int]:
    if n == 6:
        return ("Z/2", 2)
    return ("trivial", 1)

def _outer_an(n: int) -> tuple[str, int]:
    if n == 6:
        return ("Z/2 x Z/2", 4)
    if n >= 4:
        return ("Z/2", 2)
    return ("trivial", 1)

def dataset_path(name: str) -> pathlib.Path:
    """Return the (existing-or-not) directory for a named dataset."""
    if not name or "/" in name or "\\" in name:
        raise ValueError(f"invalid dataset name: {name!r}")
    return data_dir() / name

def has_mirror(name: str, file: Optional[str] = None) -> bool:
    """True iff the dataset directory (or a specific file inside it) exists.

    `file=None` checks for the directory only; pass a filename to verify a
    particular member is present and non-empty.
    """
    base = dataset_path(name)
    if file is None:
        return base.is_dir()
    target = base / file
    try:
        return target.is_file() and target.stat().st_size > 0
    except OSError:
        return False

def mirror_size(name: str) -> int:
    """Total disk usage (bytes) of a dataset's mirror directory."""
    base = dataset_path(name)
    if not base.exists():
        return 0
    total = 0
    for root, _dirs, files in os.walk(base):
        for f in files:
            try:
                total += (pathlib.Path(root) / f).stat().st_size
            except OSError:
                continue
    return total

def gunzip(src: pathlib.Path, dest: Optional[pathlib.Path] = None,
           keep: bool = True) -> pathlib.Path:
    """Decompress a .gz file. dest defaults to src without the .gz suffix."""
    src = pathlib.Path(src)
    if dest is None:
        if src.suffix != ".gz":
            raise ValueError(f"cannot infer dest from non-.gz path: {src}")
        dest = src.with_suffix("")
    dest = pathlib.Path(dest)
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_suffix(dest.suffix + ".tmp")
    try:
        with gzip.open(src, "rb") as fin, tmp.open("wb") as fout:
            shutil.copyfileobj(fin, fout, length=65536)
        os.replace(tmp, dest)
    except Exception:
        try:
            if tmp.exists():
                tmp.unlink()
        except OSError:
            pass
        raise
    if not keep:
        try:
            src.unlink()
        except OSError:
            pass
    return dest

def _x_flip_tuple(coeffs):
    """Apply x -> -x to an ascending coefficient tuple/list."""
    return tuple(c if (i % 2 == 0) else -c for i, c in enumerate(coeffs))

def _normalize_coeffs_key(coeffs):
    """Canonical key for dedup: (length-stripped, min(self, x_flip))."""
    out = list(coeffs)
    while len(out) > 1 and out[-1] == 0:
        out.pop()
    a = tuple(out)
    b = _x_flip_tuple(out)
    return min(a, b)

def _existing_keys(table):
    out = set()
    for e in table:
        out.add((e["degree"], _normalize_coeffs_key(e["coeffs"])))
    return out

