    max_curves: int = 500,
) -> list[dict]:
    """Pull L-function zeros for the family from LMFDB.

    Lazy-imports the LMFDB wrapper so unit tests that pass
    ``zeros_records`` directly never touch the network.
    """
    from prometheus_math.research.spectral_gaps import (
        fetch_zeros_for_family as _fetch,
    )
    records = _fetch(
        family_query,
        max_rows=max_curves,
        min_zeros=max(n_zeros, 5),
    )
    out = []
    for rec in records:
        zeros = rec.get("zeros") or []
        if len(zeros) < 5:
            continue
        out.append({
            "label": rec.get("label"),
            "zeros": zeros[:n_zeros],
        })
    return out

def _validate_samples(samples: Any, name: str = "samples") -> np.ndarray:
    """Coerce ``samples`` to a 1-D float array and validate non-empty."""
    arr = np.asarray(samples, dtype=float)
    if arr.ndim == 0:
        arr = arr.reshape(1)
    if arr.ndim != 1:
        raise ValueError(
            f"{name} must be 1-D; got shape {arr.shape}"
        )
    if arr.size == 0:
        raise ValueError(f"{name} is empty; need at least 1 observation")
    return arr

def _validate_n(n: int, name: str = "n_resamples") -> int:
    if not isinstance(n, (int, np.integer)):
        raise ValueError(f"{name} must be int; got {type(n).__name__}")
    if int(n) <= 0:
        raise ValueError(f"{name} must be > 0; got {n}")
    return int(n)

def _validate_alpha(alpha: float) -> float:
    a = float(alpha)
    if not (0.0 < a < 1.0):
        raise ValueError(f"alpha must be in (0,1); got {a}")
    return a

def _statistic_name(fn: Callable[..., Any]) -> str:
    """Best-effort human name for a statistic callable."""
    name = getattr(fn, "__name__", None)
    if name and name != "<lambda>":
        return name
    return repr(fn)

def _is_ainvs(spec: Any) -> bool:
    return (
        isinstance(spec, (list, tuple))
        and len(spec) == 5
        and all(isinstance(a, (int,)) or (isinstance(a, float) and float(a).is_integer())
                for a in spec)
    )

def _normalise_spec(spec: Any) -> tuple[Optional[str], Optional[list[int]]]:
    """Return (label, ainvs). At least one is non-None on success."""
    if _is_label(spec):
        return str(spec), None
    if _is_ainvs(spec):
        return None, [int(a) for a in spec]
    raise BSDAuditError(
        f"Unrecognised curve spec: {spec!r}. Expected an LMFDB label "
        f"(str like '11.a2') or a length-5 list of ints."
    )

def _run_with_timeout(fn, args=(), kwargs=None, timeout_s: float = 30.0):
    """Run ``fn(*args, **kwargs)`` in a daemon thread, return value or
    raise ``TimeoutError``. Exceptions inside fn are re-raised in the
    caller thread.

    Note: the worker is a daemon thread; if it stalls in PARI we simply
    abandon it. PARI is process-global so a stuck worker may interfere
    with subsequent calls — caller should consider restarting the
    process if many timeouts occur.
    """
    if kwargs is None:
        kwargs = {}
    out: dict[str, Any] = {"v": None, "err": None}

    def _target():
        try:
            out["v"] = fn(*args, **kwargs)
        except BaseException as e:  # noqa: BLE001 — capture for caller
            out["err"] = e

    t = threading.Thread(target=_target, daemon=True)
    t.start()
    t.join(timeout_s)
    if t.is_alive():
        raise TimeoutError(f"computation exceeded {timeout_s}s cap")
    if out["err"] is not None:
        raise out["err"]
    return out["v"]

def _verdict(deltas: dict[str, float], parity_ok: Optional[bool],
             tolerance: float) -> bool:
    """Aggregate consistency verdict.

    True iff every available delta is within tolerance AND parity_ok
    isn't actively False. (Parity unknown => not penalised.)
    """
    if parity_ok is False:
        return False
    if not deltas:
        return False
    for k, d in deltas.items():
        if d is None or (isinstance(d, float) and math.isnan(d)):
            return False
        if abs(d) > tolerance:
            return False
    return True

def _to_int(v: Any) -> Optional[int]:
    if v is None:
        return None
    try:
        return int(v)
    except (TypeError, ValueError):
        return None

def _to_float(v: Any) -> Optional[float]:
    if v is None:
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None

def _max_abs_delta(record: dict) -> float:
    """Max |delta| across the numeric delta fields. NaN if no deltas."""
    vals: list[float] = []
    for k in record:
        if k.startswith("delta_") and record[k] is not None:
            try:
                v = abs(float(record[k]))
                if not math.isnan(v):
                    vals.append(v)
            except (TypeError, ValueError):
                pass
    return max(vals) if vals else float("nan")

def _target():
    try:
        out["v"] = fn(*args, **kwargs)
    except BaseException as e:  # noqa: BLE001 — capture for caller
        out["err"] = e

def _try(key, fn, *args, **kwargs):
    try:
        computed[key] = _run_with_timeout(
            fn, args=args, kwargs=kwargs, timeout_s=timeout_s
        )
    except TimeoutError:
        warnings.append(f"{key}_runtime_exceeded")
    except Exception as e:  # noqa: BLE001 — capture per-tool failure
        warnings.append(f"{key}_failed:{type(e).__name__}")

def _primes_up_to(n: int) -> list[int]:
    """Sieve of Eratosthenes; cached so repeated calls are O(1) on the cache."""
    if n < 2:
        return []
    if _PRIMES_CACHE and _PRIMES_CACHE[-1] >= n:
        # Already sieved high enough.
        cutoff = 0
        for i, p in enumerate(_PRIMES_CACHE):
            if p > n:
                cutoff = i
                break
        else:
            cutoff = len(_PRIMES_CACHE)
        return _PRIMES_CACHE[:cutoff]
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(math.isqrt(n)) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    primes = [i for i in range(n + 1) if sieve[i]]
    if len(primes) > len(_PRIMES_CACHE):
        _PRIMES_CACHE[:] = primes
    return primes

def _first_n_primes(n: int) -> list[int]:
    """Return the first ``n`` primes; grows the sieve as needed."""
    if n <= 0:
        return []
    # Rosser bound: p_n < n * (log n + log log n) for n >= 6; we pad slightly.
    if n < 6:
        bound = 15
    else:
        bound = int(n * (math.log(n) + math.log(math.log(n)))) + 10
    while True:
        primes = _primes_up_to(bound)
        if len(primes) >= n:
            return primes[:n]
        bound *= 2

def _nf_prime_split(coeffs: list[int], primes: list[int]) -> list[int]:
    """Number of prime ideals above each rational prime in K."""
    try:
        import cypari
    except ImportError as e:  # pragma: no cover
        raise RuntimeError(f"cypari unavailable: {e}") from e
    pari = cypari.pari
    poly_str = "+".join(
        f"({c})*x^{i}" if i > 1 else (f"({c})*x" if i == 1 else f"({c})")
        for i, c in enumerate(coeffs) if c != 0
    ) or "0"
    nf = pari.nfinit(poly_str)
    out: list[int] = []
    for p in primes:
        try:
            dec = pari.idealprimedec(nf, p)
            out.append(int(len(dec)))
        except Exception:
            out.append(0)
    return out

def bulk_scan(
    label_iter: Iterable[str],
    kinds: Iterable[str] = ("ap_sequence",),
    n_terms: int = 20,
    min_match_terms: int = 8,
    conn=None,
    progress_every: int = 0,
) -> Iterator[dict]:
    """Streaming counterpart to :func:`cross_join_ec_oeis`.

    Yields one match dict per (label, kind) hit, so the full 3.8M-EC
    LMFDB corpus can be scanned without materializing all results in
    memory. Per-yield memory cost is bounded by one OEIS row.
    """
    kinds = list(kinds)
    if not kinds:
        return
    own_conn = False
    _conn = conn
    if _conn is None:
        try:
            from prometheus_math.databases import lmfdb as _lmfdb
            _conn = _lmfdb.connect()
            own_conn = True
        except Exception:
            _conn = None

    try:
        for i, label in enumerate(label_iter):
            ec = _fetch_ec(label, conn=_conn)
            if ec is None:
                continue
            ainvs = ec.get("ainvs")
            if not ainvs or len(ainvs) != 5:
                continue
            for kind in kinds:
                try:
                    sig = generate_ec_signature(ainvs, kind=kind, n_terms=n_terms)
                except Exception as e:
                    _log.debug("signature failed for %s/%s: %s", label, kind, e)
                    continue
                if not sig:
                    continue
                hit = _oeis_match(sig, min_match_terms=min_match_terms)
                if hit is None:
                    continue
                rec = {
                    "ec_label": label,
                    "ainvs": list(ainvs),
                    "conductor": ec.get("conductor"),
                    "rank": ec.get("rank"),
                    "signature_kind": kind,
                    "signature": list(sig),
                    "oeis_match": hit.get("number"),
                    "oeis_name": hit.get("name", ""),
                    "surprise_score": surprise_score(
                        {"ec_label": label, "signature": sig},
                        hit,
                    ),
                }
                yield rec
            if progress_every and ((i + 1) % progress_every == 0):
                _log.info("[conjecture_engine] %d ECs scanned (last: %s)",
                          i + 1, label)
    finally:
        if own_conn and _conn is not None:
            try:
                _conn.close()
            except Exception:
                pass

def _polredabs_str(poly: str) -> Optional[str]:
    """Return the polredabs-canonical form of ``poly`` or None on failure.

    Both LMFDB's ``coeffs`` arrays and our shape-field ``poly`` strings
    flow through PARI's ``polredabs`` to produce the same canonical
    presentation (LMFDB stores its polynomials already polredabs'd).
    """
    if poly is None:
        return None
    try:
        from prometheus_math.topology import polredabs as _pra
        return str(_pra(poly)).strip()
    except Exception:
        return None

def _coeffs_to_poly_str(coeffs) -> str:
    """LMFDB ``coeffs`` array (constant -> leading) -> PARI poly string.

    LMFDB stores number-field defining polys as ``coeffs = [a0, a1, ..., an]``
    where ``f(x) = a0 + a1*x + ... + an*x^n``. PARI/our shape-field tool
    works with ``"x^n + ... + a0"`` strings.
    """
    if not coeffs:
        return ""
    terms: list[str] = []
    for i, c in enumerate(coeffs):
        c_int = int(c)
        if c_int == 0:
            continue
        if i == 0:
            terms.append(f"({c_int})")
        elif i == 1:
            terms.append(f"({c_int})*x")
        else:
            terms.append(f"({c_int})*x^{i}")
    return "+".join(terms) if terms else "0"

def _signature_from_lmfdb(nf_row: dict) -> Optional[tuple[int, int]]:
    """LMFDB row -> ``(r1, r2)`` signature, if degree and r2 are present."""
    deg = nf_row.get("degree")
    r2 = nf_row.get("r2")
    if deg is None or r2 is None:
        return None
    return (int(deg) - 2 * int(r2), int(r2))

def _signature_from_disc_degree(degree: int, disc: int) -> Optional[tuple[int, int]]:
    """Best-effort ``(r1, r2)`` from degree + disc sign.

    For degree 2: sign(disc) determines signature exactly:
        disc > 0 -> (2, 0) (real), disc < 0 -> (0, 1) (imaginary).
    For degree 3: sign(disc) is also exact (cubic has either 3 real or
    1 real + 1 complex pair):
        disc > 0 -> (3, 0), disc < 0 -> (1, 1).
    For degree >= 4: sign(disc) only constrains parity of ``r2``
        (sign = (-1)^r2), so we return None — caller treats signature
        as "unknown" and skips the +0.1 contribution either way.
    """
    if degree == 2:
        return (2, 0) if disc > 0 else (0, 1)
    if degree == 3:
        return (3, 0) if disc > 0 else (1, 1)
    return None

def _shape_field_for_knot(
    knot_name: str, bits_prec: int, max_deg: int
) -> tuple[Optional[dict], Optional[str]]:
    """Compute shape field for ``knot_name`` or return (None, error_string).

    Imports :mod:`prometheus_math.topology` lazily so the module loads even
    when SnapPy isn't installed (e.g. test runners with mocking).
    """
    try:
        from prometheus_math.topology import knot_shape_field
    except Exception as e:  # pragma: no cover — env-only path
        return None, f"knot_shape_field import failed: {e}"
    try:
        sf = knot_shape_field(knot_name, bits_prec=bits_prec, max_deg=max_deg)
        # Strip the heavy caveat string before returning to keep memory low.
        return {
            "poly": sf.get("poly"),
            "degree": sf.get("degree"),
            "disc": sf.get("disc"),
            "bits_prec": sf.get("bits_prec"),
            "is_hyperbolic": sf.get("is_hyperbolic", True),
        }, None
    except Exception as e:
        return None, str(e)

def _knot_record(
    knot_name: str,
    bits_prec: int,
    max_deg: int,
    abs_disc_tol: int,
    candidate_limit: int,
    conn=None,
) -> dict:
    """Compute shape field + LMFDB candidates for a single knot."""
    sf, err = _shape_field_for_knot(knot_name, bits_prec, max_deg)
    if sf is None:
        return {
            "knot_name": knot_name,
            "shape_field": None,
            "candidates": [],
            "best_match": None,
            "status": "shape_field_failed",
            "error": err,
        }
    try:
        candidates = _build_candidates(
            sf, abs_disc_tol=abs_disc_tol,
            candidate_limit=candidate_limit, conn=conn,
        )
    except Exception as e:
        return {
            "knot_name": knot_name,
            "shape_field": sf,
            "candidates": [],
            "best_match": None,
            "status": "shape_field_failed",
            "error": f"LMFDB query failed: {e}",
        }
    if not candidates:
        return {
            "knot_name": knot_name,
            "shape_field": sf,
            "candidates": [],
            "best_match": None,
            "status": "no_candidate",
        }
    best = candidates[0]
    return {
        "knot_name": knot_name,
        "shape_field": sf,
        "candidates": candidates,
        "best_match": best,
        "status": "matched",
    }

def sort_key(r):
    s = r.get("status", "shape_field_failed")
    c = (r.get("best_match") or {}).get("confidence", 0.0)
    return (status_order.get(s, 99), -c)

def _strip_trailing_zeros(coeffs: list[int]) -> list[int]:
    out = list(coeffs)
    while len(out) > 1 and out[-1] == 0:
        out.pop()
    return out

def _coerce_rng(rng):
    """Return a numpy Generator from any of: None, int seed, Generator."""
    if rng is None:
        return np.random.default_rng()
    if isinstance(rng, np.random.Generator):
        return rng
    return np.random.default_rng(int(rng))

def _divisors(n: int) -> list[int]:
    n = abs(int(n))
    if n == 0:
        return []
    out = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            out.append(i)
            if i != n // i:
                out.append(n // i)
        i += 1
    return out

def _parse_zeros(raw: Any) -> Optional[list[float]]:
    """Parse a Postgres-encoded zero list to a Python list of floats.

    LMFDB stores zeros as either JSON arrays (text/jsonb) or Postgres
    arrays. The wrapper in
    :func:`prometheus_math.databases.lmfdb.lfunctions` already converts
    most cases to ``list``; this helper handles the residual stringy
    cases for safety.
    """
    if raw is None:
        return None
    if isinstance(raw, list):
        try:
            return [float(z) for z in raw]
        except (TypeError, ValueError):
            return None
    s = str(raw).strip()
    if s in ("", "[]", "{}", "None"):
        return None
    s = s.replace("{", "[").replace("}", "]")
    try:
        return [float(z) for z in json.loads(s)]
    except Exception:
        return None

def _goe_eigvals(n: int, rng: np.random.Generator) -> np.ndarray:
    """Sorted eigenvalues of a single GOE matrix of size n."""
    A = rng.standard_normal((n, n))
    H = (A + A.T) / math.sqrt(2.0)
    return np.sort(np.linalg.eigvalsh(H))

def _cue_eigangles(n: int, rng: np.random.Generator) -> np.ndarray:
    """Sorted eigenphases (in [0, 2π)) of a Haar unitary."""
    U = _haar_unitary(n, rng)
    w = np.linalg.eigvals(U)
    angles = np.mod(np.angle(w), 2 * math.pi)
    return np.sort(angles)

def _se_var(v: float, n: int) -> float:
    """Standard error of the variance estimator under normality."""
    if n <= 1:
        return float("inf")
    return math.sqrt(2.0 * v * v / max(1, n - 1))

def _safe_fetch(spec: DomainSpec, n: Optional[int]) -> Sequence[dict]:
    """Call spec.fetch_fn with ``n=n`` if accepted, else without."""
    if n is not None:
        try:
            return list(spec.fetch_fn(n=n))
        except TypeError:
            pass
    return list(spec.fetch_fn())

