def _polygon_area(polygon_points):
    """Shoelace formula for the area of a polygon given by its (ordered) hull."""
    x = polygon_points[:, 0]
    y = polygon_points[:, 1]
    return 0.5 * abs(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1)))

