    """Voronoi adjacency (j in N(i) <=> i in N(j))."""
    pts = np.array(
        [
            [0.0, 0.0], [3.0, 0.0], [3.0, 3.0], [0.0, 3.0], [1.5, 1.5],
            [1.5, 0.0], [3.0, 1.5], [1.5, 3.0], [0.0, 1.5],
