def imag_quad_disc(draw, min_value=-200, max_value=-3):
    """Imaginary quadratic discriminant: D < 0, D ≡ 0 or 1 (mod 4)."""
    D = draw(st.integers(min_value=min_value, max_value=max_value))
    while D % 4 not in (0, 1):
        D -= 1
        if D < min_value:
            D = max_value
            while D % 4 not in (0, 1):
                D -= 1
            break
    return D

