def _eval_cf(coeffs):
    """Evaluate a finite continued fraction back to a Fraction."""
    if not coeffs:
        return Fraction(0)
    f = Fraction(coeffs[-1])
    for a in reversed(coeffs[:-1]):
        f = a + Fraction(1) / f
    return f

