def build_head_to_category() -> dict[str, str]:
    head_to_cat: dict[str, str] = {}
    for cat in PRECEDENCE:
        for head in CATEGORY_MEMBERS.get(cat, []):
            head_to_cat.setdefault(head, cat)
    return head_to_cat

def wilson_ci(k: int, n: int, alpha: float = 0.05) -> Tuple[float, float]:
    """Wilson score interval for a binomial proportion."""
    if n == 0:
        return (0.0, 1.0)
    z = stats.norm.ppf(1 - alpha / 2)
    p = k / n
    denom = 1 + z * z / n
    center = (p + z * z / (2 * n)) / denom
    half = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / denom
    return (max(0.0, center - half), min(1.0, center + half))

def interpret(pi0: float, ci_width: float, thin: bool, special: str = "") -> str:
    if special:
        return special
    if thin:
        return "thin_data"
    if ci_width > 0.5:
        return "undefined_thin_data"
    if pi0 >= 0.9:
        return "high"
    if pi0 >= 0.5:
        return "moderate"
    return "low"

def compute_feature_distribution(
    records: List[Dict[str, Any]], feature_name: str,
    extractor=None,
) -> Dict[str, Any]:
    """Compute distribution stats for a feature across records.

    Returns: n_with, n_missing, distinct_values, top_value_share, dominant.
    """
    if extractor is None:
        extractor = lambda r: r.get(feature_name)
    vals = []
    n_missing = 0
    for r in records:
        v = extractor(r)
        if v is None:
            n_missing += 1
        else:
            try:
                vals.append(v)
            except (TypeError, ValueError):
                n_missing += 1

    n = len(records)
    if not vals:
        return {
            "feature": feature_name, "n": n, "n_with": 0, "n_missing": n_missing,
            "missingness_rate": 1.0, "n_distinct": 0, "top_value_share": 0.0,
            "dominant": None,
        }
    # For discrete features, count
    is_discrete = all(
        isinstance(v, (int, str, bool)) for v in vals[:100]
    )
    if is_discrete:
        cnt = Counter(vals)
        top_val, top_count = cnt.most_common(1)[0]
        return {
            "feature": feature_name, "n": n, "n_with": len(vals),
            "n_missing": n_missing, "missingness_rate": n_missing / n,
            "n_distinct": len(cnt), "top_value_share": top_count / len(vals),
            "dominant": str(top_val),
            "value_distribution": dict(cnt.most_common(8)),
        }
    # Continuous — report range + diversity proxy
    return {
        "feature": feature_name, "n": n, "n_with": len(vals),
        "n_missing": n_missing, "missingness_rate": n_missing / n,
        "n_distinct": len(set(vals)),
        "top_value_share": None,
        "dominant": None,
        "min": min(vals), "max": max(vals),
        "median": statistics.median(vals) if vals else None,
    }

def classify_coverage(
    n_objects: int, missingness: float, top_share: float, distinct: int,
    n_invariants_present: int,
) -> Tuple[str, List[str]]:
    """Apply the coverage tagging rubric."""
    flags = []
    if n_objects == 0:
        return "void", ["no records"]
    if n_objects < 30:
        flags.append("low_n")
        if n_objects < 10:
            return "thin", flags + [f"n={n_objects} < 10"]
        return "thin", flags + [f"n={n_objects} < 30"]
    # Misleading-dense triggers
    if missingness > 0.20:
        flags.append(f"high_missingness ({missingness:.0%})")
    if top_share is not None and top_share > 0.80:
        flags.append(f"dominant_value_share ({top_share:.0%})")
    if n_invariants_present < 3:
        flags.append(f"low_invariant_diversity ({n_invariants_present} invariants)")
    if distinct < 5 and n_objects > 30:
        flags.append(f"low_diversity (distinct={distinct} on n={n_objects})")
    if flags:
        return "misleading_dense", flags
    if n_objects >= 200:
        return "dense", []
    return "moderate", []

def load_bridges_summary() -> Dict[str, Any]:
    """Summarize bridges.jsonl — cross-dataset concept-keyed bridges."""
    if not BRIDGES.exists():
        return {"error": "not found"}
    with BRIDGES.open(encoding="utf-8") as f:
        bridges = [json.loads(l) for l in f if l.strip()]

    by_dataset = Counter()
    by_n_datasets = Counter()
    for b in bridges:
        for ds in b.get("datasets", {}):
            by_dataset[ds] += 1
        by_n_datasets[b.get("n_datasets", 0)] += 1

    return {
        "n_bridges": len(bridges),
        "by_dataset_freq": dict(by_dataset.most_common(15)),
        "by_n_datasets_distribution": dict(by_n_datasets),
        "note": (
            "bridges.jsonl is concept-keyed cross-dataset coverage. Dataset "
            "name → number of bridge-concepts referencing that dataset."
        ),
    }

def parse_step_set(name: str) -> Optional[List[Tuple[int, int, int]]]:
    m = STEP_SET_RE.search(name)
    if not m:
        return None
    body = m.group(1)
    out = []
    for s in STEP_RE.findall(body):
        out.append(tuple(int(x) for x in s))
    return out or None

def correlate_feature_with_outcome(
    records: List[Dict[str, Any]],
    feature_extractor,
    outcome_key: str,
    feature_label: str,
    is_categorical: bool = False,
) -> Dict[str, Any]:
    """Compute correlation of a binary or categorical feature with a binary outcome.

    For binary features: computes (P[outcome|feature=True] - P[outcome|feature=False])
    plus n in each cell + a Wald CI on the difference.
    For continuous features: returns Pearson r + bootstrap CI.
    """
    pairs = []
    for r in records:
        f = feature_extractor(r)
        if f is None:
            continue
        out = outcome_flags(r)[outcome_key]
        pairs.append((f, out))
    if not pairs:
        return {"feature": feature_label, "outcome": outcome_key, "n": 0,
                "result": "no data"}

    n = len(pairs)
    if is_categorical:
        return categorical_outcome_table(pairs, feature_label, outcome_key, n)
    # Treat as binary if all values are 0/1 or True/False
    distinct_vals = {p[0] for p in pairs}
    if distinct_vals.issubset({True, False, 0, 1, 0.0, 1.0}):
        return binary_feature_diff(pairs, feature_label, outcome_key, n)
    # Continuous: bin into above-median / below-median
    return median_split_diff(pairs, feature_label, outcome_key, n)

def categorical_outcome_table(
    pairs: List[Tuple], feature_label: str, outcome_key: str, n: int,
) -> Dict[str, Any]:
    """Per-category outcome rate."""
    by_cat: Dict[Any, List[bool]] = defaultdict(list)
    for f, o in pairs:
        by_cat[f].append(o)
    rows = []
    for cat, outcomes in sorted(by_cat.items(), key=lambda x: -len(x[1])):
        n_cat = len(outcomes)
        n_outcome = sum(outcomes)
        rows.append({
            "category": str(cat),
            "n": n_cat,
            "p_outcome": n_outcome / n_cat if n_cat else 0.0,
            "n_outcome": n_outcome,
        })
    return {
        "feature": feature_label,
        "outcome": outcome_key,
        "n_total": n,
        "categorical_rows": rows,
    }

def classify_finding(
    finding: Dict[str, Any],
    sources: Counter,
    is_single_domain: bool,
) -> Tuple[str, str]:
    """Classify a feature-outcome correlation.

    Returns (classification, rationale).

    Single-domain data (lattice walks only) cannot support productive
    classification — that requires cross-domain evidence we don't have.
    """
    n = finding.get("n_total", 0)
    n_with = finding.get("n_with_feature", 0)
    n_without = finding.get("n_without_feature", 0)

    if n < 30:
        return "thin_data", f"n={n} < 30 — insufficient for statistical inference"
    if n_with < 10 or n_without < 10:
        return "thin_data", f"n_with={n_with} n_without={n_without}; one cell <10"

    # Source dominance — single source triggers overfitting flag
    n_src = len(sources)
    top_src_share = max(sources.values()) / sum(sources.values()) if sources else 1.0
    if top_src_share > 0.95:
        return "overfitting", (
            f"single source dominates corpus ({top_src_share:.1%}); feature "
            f"signal may reflect template structure of that source"
        )

    if is_single_domain:
        return "indeterminate", (
            "single-domain data (A149* lattice walks); cannot distinguish "
            "productive morphology from blind-spot or template-overfitting "
            "without cross-domain evidence (cross-domain rich findings n=3)"
        )

    # Otherwise: substantive enough but still need cross-domain validation
    return "indeterminate", "n>=30 in both cells but cross-domain replication unverified"

