        tests.append({
            "id": "T4_replace_true_succeeds",
            "expected": "replace=True overrides",
            "actual": "succeeds",
            "verdict": "PASS",
        })
    except Exception as exc:  # noqa: BLE001
        tests.append({
            "id": "T4_replace_true_succeeds",
            "expected": "replace=True overrides",
            "actual": f"raised: {type(exc).__name__}: {exc}",
            "verdict": "FAIL",
            "severity": "P1-high",
        })

    # T5: by_id lookup
