def sample_probes(rng: random.Random, corpora):
    """Sample 15 adversarial + 15 real-paper, drawn uniformly across landed corpora."""
    all_adv = []
    all_rp = []
    for cid, d in corpora:
        for p in d.get("adversarial", []):
            all_adv.append((cid, p))
        for p in d.get("real_paper", []):
            all_rp.append((cid, p))
    rng.shuffle(all_adv)
    rng.shuffle(all_rp)
    return all_adv[:N_ADVERSARIAL], all_rp[:N_REAL_PAPER]

def fast_mahler_numpy(coeffs_ascending: List[int]) -> float:
    """Quick Mahler measure via numpy roots — for upfront band-routing only."""
    import numpy as np
    if len(coeffs_ascending) < 2:
        return float("nan")
    roots = np.roots(list(reversed(coeffs_ascending)))
    leading = abs(coeffs_ascending[-1])
    if leading == 0:
        return float("nan")
    prod = float(leading)
    for r in roots:
        m = abs(r)
        if m > 1.0:
            prod *= m
    return prod

def stratified_in_band_sampler(
    n_target: int, half_len: int, coef_range: Tuple[int, int],
    rng: random.Random, max_attempts: int = 50000,
) -> List[Tuple[List[int], float]]:
    """Rejection-sampling on M in (1.001, 1.18). Returns list of (coeffs, M)
    pairs that fall in the Salem band."""
    out: List[Tuple[List[int], float]] = []
    attempts = 0
    while len(out) < n_target and attempts < max_attempts:
        attempts += 1
        half = [rng.randint(coef_range[0], coef_range[1]) for _ in range(half_len)]
        if half[0] == 0:
            half[0] = rng.choice([-1, 1])
        coeffs = palindrome_from_half(half)
        try:
            m = fast_mahler_numpy(coeffs)
        except Exception:
            continue
        if m != m or m == float("inf"):  # nan/inf
            continue
        if 1.001 <= m <= 1.18:
            out.append((coeffs, m))
    return out

def compute_priors(
    threshold: float = 0.5,
    base: float = 0.003,
) -> dict:
    """Return {gid: prior_score} for gens with lifetime_sat < threshold.

    Uses the Fire #62 formula:
        score = base × (1 + 5 × (1 - sat))
    No dup-rate penalty assumed (synthetic priors represent best-case
    new-formula scoring for the gen).
    """
    out: dict = {}
    for gid in sorted(REGISTRY.keys()):
        sat = SIGNATURE_INDEX.saturation_score(gid)
        if sat is None:
            continue
        if sat >= threshold:
            continue
        score = base * (1.0 + 5.0 * (1.0 - sat))
        out[gid] = score
    return out

def _find_candidates(
    days: int,
    holdback_minutes: int = COMPACT_HOLDBACK_MINUTES,
) -> Iterable[Tuple[Path, str]]:
    """Yield (path, description) pairs eligible for compression."""
    age_cutoff = time.time() - (days * 86400)
    holdback_cutoff = time.time() - (holdback_minutes * 60)
    for root, pattern, desc in SCAN_TARGETS:
        if not root.is_dir():
            continue
        for path in root.glob(pattern):
            if not path.is_file():
                continue
            # Already compressed alongside?
            if path.with_suffix(path.suffix + ".gz").exists():
                continue
            try:
                mtime = path.stat().st_mtime
            except OSError:
                continue
            if mtime > age_cutoff:
                continue  # too recent
            if mtime > holdback_cutoff:
                continue  # may be in-flight
            yield path, desc

def _existing_ids(path: Path) -> Set[str]:
    if not path.exists():
