def fetch_one(
    title: str,
    timeout: float = 10.0,
    max_429_attempts: int = 5,
) -> dict | None:
    # Wikipedia's REST API requires URL-encoded paths. Without quoting
    # apostrophes, en-dashes, and non-ASCII (Erdős, Pólya, Cramér...)
    # the request returns 404. Pass safe='' so the / in any sub-paths
    # would be encoded (we don't have any, but defensive).
    url = f"{API}/{urllib.parse.quote(title, safe='')}"
    # 429-aware retry loop. Honor Retry-After header when present.
    for attempt in range(max_429_attempts):
        try:
            r = requests.get(url, headers=HEADERS, timeout=timeout)
        except requests.RequestException:
            return None
        if r.status_code == 200:
            j = r.json()
            extract = j.get("extract", "") or ""
            if not extract:
                return None
            return {
                "title": title,
                "extract": extract,
                "url": j.get("content_urls", {})
                       .get("desktop", {}).get("page", ""),
                "categories": [],
                "fetched_at": datetime.now(timezone.utc).isoformat(),
            }
        if r.status_code in (429, 503):
            retry_after = None
            ra = r.headers.get("Retry-After")
            if ra:
                try:
                    retry_after = float(ra)
                except (TypeError, ValueError):
                    pass
            if attempt + 1 >= max_429_attempts:
                return None
            sleep_for_retry(
                attempt=attempt,
                base_delay=10.0,  # Wikipedia recovers quickly
                cap=120.0,
                retry_after=retry_after,
            )
            continue
        # Other status (404 etc.): give up on this title.
        return None
    return None

def _r2_to_verdict(r2: float) -> str:
    """Replicates h2's verdict mapping exactly."""
    if r2 >= STRONG_R2:
        return Verdict.SHADOW_CATALOG.value
    if r2 >= WEAK_R2:
        return Verdict.INCONCLUSIVE.value
    return Verdict.REJECTED.value

def _load_import_centrality() -> Dict[str, int]:
    """Build incoming-edge count per node from the existing import graph."""
    if not IMPORT_GRAPH_PATH.exists():
        return {}
    try:
        with IMPORT_GRAPH_PATH.open("r", encoding="utf-8") as f:
            g = json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}
    counts: Counter = Counter()
    for edge in g.get("edges", []):
        if len(edge) == 2:
            _, dst = edge
            counts[dst] += 1
    return dict(counts)

def _source_path_to_node(source_path: str) -> str:
    """Convert 'NumberTheory/ADEInequality.lean' to 'Mathlib.NumberTheory.ADEInequality'."""
    if source_path.endswith(".lean"):
        source_path = source_path[: -len(".lean")]
    parts = source_path.replace("\\", "/").split("/")
    return "Mathlib." + ".".join(parts)

def _name_simplicity(name: str) -> float:
    dots = name.count(".")
    return max(0.0, 1.0 - min(dots / 3.0, 1.0))

def _normalize_centrality(counts: Dict[str, int]) -> Dict[str, float]:
    if not counts:
        return {}
    max_c = max(counts.values())
    if max_c == 0:
        return {k: 0.0 for k in counts}
    return {k: v / max_c for k, v in counts.items()}

def _iter_lean_files(root: Path) -> Iterator[Path]:
    """Yield .lean files under target subdirs."""
    for sub in TARGET_SUBDIRS:
        d = root / sub
        if not d.exists():
            continue
        yield from d.rglob("*.lean")

def _extract_one(path: Path) -> List[dict]:
    """Extract all theorem/lemma/def signatures from a single .lean file."""
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return []
    out: List[dict] = []
    seen_names: set[str] = set()
    for pat in DECL_PATTERNS:
        for m in pat.finditer(text):
            name = m.group("name").strip()
            sig = m.group("sig").strip()
            kind = m.group("kind").strip()
            if not name or not sig:
                continue
            if name in seen_names:
                continue
            seen_names.add(name)
            # Cleanup signature
            sig = " ".join(sig.split())
            if len(sig) > MAX_SIG_LEN:
                sig = sig[:MAX_SIG_LEN] + "...(truncated)"
            if len(sig) < MIN_SIG_LEN:
                continue
            try:
                rel = path.relative_to(MATHLIB_DIR).as_posix()
            except ValueError:
                rel = str(path)
            out.append({
                "kind": kind,
                "name": name,
                "signature": sig,
                "source_path": rel,
                "domain": rel.split("/")[0] if "/" in rel else rel,
            })
    return out

def _extract_claims_from_text(
    text: str, source_path: Path, apply_aporia_filters: bool = True,
) -> List[dict]:
    """Extract quantitative claim candidates from a markdown doc.

    apply_aporia_filters (default True): require external anchor and
    not be Prometheus-internal-only. Disable for raw-extract debugging.
    """
    seen = set()
    claims: List[dict] = []
    for pat in QUANTITATIVE_PATTERNS:
        for m in pat.finditer(text):
            raw = m.group(0).strip()
            normalized = " ".join(raw.split())
            if len(normalized) < 30 or len(normalized) > 600:
                continue
            if normalized in seen:
                continue
            if apply_aporia_filters and not _passes_aporia_filters(normalized):
                continue
            seen.add(normalized)
            try:
                source_str = str(
                    source_path.relative_to(REPO_ROOT).as_posix()
                )
            except ValueError:
                # source_path not under REPO_ROOT (e.g. in tests); fall back
                source_str = str(source_path.as_posix())
            claims.append({
                "claim_id": _claim_id(normalized),
                "source_path": source_str,
                "claim_text": normalized,
                "pattern_kind": _classify_pattern(normalized),
            })
    return claims

def _has_external_anchor(claim: str) -> bool:
    """True if the claim references named external math objects, citations,
    or named constants/functions from outside Prometheus."""
    for pat in EXTERNAL_ANCHOR_PATTERNS:
        if pat.search(claim):
            return True
    return False

def _is_prometheus_internal(claim: str) -> bool:
    """True if claim text contains Prometheus-internal markers. Used to
    veto unless the math content survives stripping the markers."""
    lc = claim.lower()
    return any(marker.lower() in lc for marker in PROMETHEUS_INTERNAL_MARKERS)

def _strip_internal_markers(claim: str) -> str:
    """Remove Prometheus-internal markers from claim text."""
    out = claim
    for m in PROMETHEUS_INTERNAL_MARKERS:
        out = re.sub(re.escape(m), " ", out, flags=re.IGNORECASE)
    return " ".join(out.split())

def _classify_pattern(claim: str) -> str:
    """Coarse classification for downstream filtering."""
    low = claim.lower()
    if any(w in low for w in ("conjecture", "predict", "expect", "hypothesize")):
        return "conjecture"
    if any(w in low for w in ("implies", "means", "shows", "suggests")):
        return "implication"
    if "%" in claim:
        return "rate_or_percentage"
    if re.search(r"\d+\s*(?:fold|x|times|×)", claim, re.IGNORECASE):
        return "magnitude_change"
    if re.search(r"[<>≤≥]", claim):
        return "numeric_bound"
    return "other_quantitative"

def _iter_synthesis_files() -> Iterator[Path]:
    seen: set[Path] = set()
    for g in SYNTHESIS_GLOBS:
        for p in REPO_ROOT.glob(g):
            if p in seen or not p.is_file():
                continue
            seen.add(p)
            # Skip meta-analysis docs that are about Techne work, not Techne claims
            if p.name.startswith("meta_analysis_"):
                continue
            if p.name.startswith("feedback_"):
                continue
            yield p

def scan(output_path: Path) -> dict:
    """Scan all synthesis docs; write JSONL output; return summary."""
    output_path.parent.mkdir(parents=True, exist_ok=True)
    n_files = 0
    n_claims = 0
    by_kind: dict[str, int] = {}
    with output_path.open("w", encoding="utf-8") as f:
        for p in _iter_synthesis_files():
            n_files += 1
            try:
                text = p.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            for claim in _extract_claims_from_text(text, p):
                f.write(json.dumps(claim, sort_keys=True) + "\n")
                n_claims += 1
                by_kind[claim["pattern_kind"]] = by_kind.get(claim["pattern_kind"], 0) + 1
    return {
        "output_path": str(output_path),
        "n_files_scanned": n_files,
        "n_claims_extracted": n_claims,
        "by_pattern_kind": by_kind,
        "scanned_at": datetime.now(timezone.utc).isoformat(),
    }

def _load_json(path: Path) -> Optional[Dict[str, Any]]:
    if not path.exists():
        return None
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except (OSError, json.JSONDecodeError):
        return None

def _count_jsonl_lines(path: Path) -> int:
    if not path.exists():
        return 0
    n = 0
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                n += 1
    return n

def _recent_batches(n: int) -> List[Dict[str, Any]]:
    if not BATCHES_JSONL_PATH.exists():
        return []
    lines: List[Dict[str, Any]] = []
    with BATCHES_JSONL_PATH.open("r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                lines.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return lines[-n:]

def collect_summary(recent_n: int = 3) -> Dict[str, Any]:
    """Build the structured summary."""
    lifetime = _load_json(LIFETIME_PATH) or {}
    bandit = _load_json(BANDIT_HISTORY_PATH) or {}
    yield_history = bandit.get("yield_scores", {}) if bandit else {}

    # Per-generator: lifetime records + bandit-observed yield-score mean
    gen_summary: Dict[str, Dict[str, Any]] = {}
    per_gen_life = lifetime.get("per_generator_lifetime", {}) if lifetime else {}
    all_gids = set(per_gen_life.keys()) | set(yield_history.keys())
    for gid in all_gids:
        scores = yield_history.get(gid, [])
        gen_summary[gid] = {
            "lifetime_records": int(per_gen_life.get(gid, 0)),
            "fires": len(scores),
            "yield_score_mean": (
                sum(scores) / len(scores) if scores else None
            ),
        }

    # Caches
    cache_sizes = {
        "arxiv": _count_jsonl_lines(CACHE_DIR / "arxiv" / "abstracts.jsonl"),
        "lmfdb": _count_jsonl_lines(CACHE_DIR / "lmfdb" / "knowls.jsonl"),
        "wiki": _count_jsonl_lines(
            CACHE_DIR / "conjectures" / "wiki_conjectures.jsonl"
        ),
    }

    return {
        "lifetime": lifetime,
        "generators": gen_summary,
        "recent_batches": _recent_batches(recent_n),
        "caches": cache_sizes,
    }

def _fmt_int(n: int) -> str:
    if n >= 1_000_000:
        return f"{n / 1_000_000:.2f}M"
    if n >= 1_000:
        return f"{n / 1_000:.1f}k"
    return str(n)

def _iter_records(
    path: Path, max_records: int = DEFAULT_SAMPLE_PER_BATCH,
) -> Iterator[Dict[str, Any]]:
    """Stream JSONL line-by-line; cap at max_records to bound runtime."""
    n = 0
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            if n >= max_records:
                break
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError:
                continue
            n += 1

def _select_batch_files(
    corpus_dir: Path = CORPUS_DIR,
    n_files: int = DEFAULT_BATCH_FILES,
) -> List[Path]:
    """Return the N most-recent corpus batch JSONL files (by mtime)."""
    if not corpus_dir.exists():
        return []
    files = [p for p in corpus_dir.glob("*.jsonl") if p.is_file()]
    files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return files[:n_files]

def is_rate_limited(exc: BaseException) -> tuple[bool, float | None]:
    """Detect whether an exception represents a rate-limit response.

    Returns (is_429, retry_after_seconds_or_None).

    Supports:
      - arxiv.HTTPError with status_code 429
      - requests.HTTPError / requests.Response with status_code 429
      - generic exceptions with a `.status_code` attribute
    """
    # arxiv.HTTPError carries .status_code directly
    code = getattr(exc, "status_code", None)
    if code is None:
        # Some libs wrap the response on .response
        resp = getattr(exc, "response", None)
        if resp is not None:
            code = getattr(resp, "status_code", None)

    if code != 429 and code != 503:
        return False, None

    # Try to extract Retry-After
    retry_after = None
    resp = getattr(exc, "response", None)
    if resp is not None:
        headers = getattr(resp, "headers", None)
        if headers is not None:
            ra = headers.get("Retry-After") or headers.get("retry-after")
            if ra:
                try:
                    retry_after = float(ra)
                except (TypeError, ValueError):
                    retry_after = None

    return True, retry_after

def with_429_retry(
    max_attempts: int = 6,
    base_delay: float = 30.0,
    cap: float = 600.0,
) -> Callable[[Callable[..., T]], Callable[..., T]]:
    """Decorator: catch 429/503 exceptions, sleep with backoff, retry.

    Non-rate-limit exceptions propagate immediately. After `max_attempts`
    rate-limit hits, the last exception propagates.
    """
    def deco(fn: Callable[..., T]) -> Callable[..., T]:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last_exc: BaseException | None = None
            for attempt in range(max_attempts):
                try:
                    return fn(*args, **kwargs)
                except Exception as exc:
                    is_rl, retry_after = is_rate_limited(exc)
                    if not is_rl:
                        raise
                    last_exc = exc
                    if attempt + 1 >= max_attempts:
                        break
                    sleep_for_retry(
                        attempt=attempt,
                        base_delay=base_delay,
                        cap=cap,
                        retry_after=retry_after,
                    )
            # Exhausted retries
            if last_exc is not None:
                raise last_exc
            # Unreachable; max_attempts >= 1 always returns or raises
            return None  # type: ignore[return-value]
        return wrapper
    return deco

def deco(fn: Callable[..., T]) -> Callable[..., T]:
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        last_exc: BaseException | None = None
        for attempt in range(max_attempts):
            try:
