def _load_batches() -> List[Dict[str, Any]]:
    """Load all per-batch journal entries."""
    out = []
    with BATCHES_JSONL_PATH.open("r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                out.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return out

def _load_signature_index() -> Dict[str, Any]:
    """Aggregate signature_index data: per-gen counts + verdicts."""
    if not SIGNATURE_INDEX_PATH.exists():
        return {"total_unique": 0, "by_gen": {}, "by_verdict": {}}
    with sqlite3.connect(SIGNATURE_INDEX_PATH) as c:
        cur = c.execute("SELECT COUNT(*), SUM(seen_count) FROM signatures")
        total_unique, total_seen = cur.fetchone()
        cur = c.execute(
            "SELECT generator_id, COUNT(*), SUM(seen_count) "
            "FROM signatures GROUP BY generator_id ORDER BY COUNT(*) DESC"
        )
        by_gen = {
            gid: {"unique": n, "total_seen": tot}
            for gid, n, tot in cur.fetchall()
        }
        cur = c.execute(
            "SELECT verdict_class, COUNT(*), SUM(seen_count) "
            "FROM signatures GROUP BY verdict_class"
        )
        by_verdict = {
            vc: {"unique": n, "total_seen": tot}
            for vc, n, tot in cur.fetchall()
        }
    return {
        "total_unique": total_unique,
        "total_seen": total_seen,
        "by_gen": by_gen,
        "by_verdict": by_verdict,
    }

def metric_per_gen_contribution(batches: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Per-gen: total records emitted across all fires, fire-count, dup-rate."""
    by_gen = defaultdict(lambda: {
        "fire_count": 0,
        "total_records": 0,
        "total_kills": 0,
        "total_confirms": 0,
        "dup_sum": 0.0,
    })
    for b in batches:
        for gid, m in b["per_generator"].items():
            by_gen[gid]["fire_count"] += 1
            by_gen[gid]["total_records"] += m["records_emitted"]
            by_gen[gid]["total_kills"] += m["kills"]
            by_gen[gid]["total_confirms"] += m["confirmations"]
            by_gen[gid]["dup_sum"] += m.get("dup_rate", 0.0)
    out = {}
    for gid, d in by_gen.items():
        n = d["fire_count"]
        out[gid] = {
            "fire_count": n,
            "total_records": d["total_records"],
            "mean_dup_rate": round(d["dup_sum"] / max(n, 1), 3),
            "kill_share": round(d["total_kills"] / max(d["total_records"], 1), 3),
            "records_per_fire": d["total_records"] // max(n, 1),
        }
    return out

def metric_promote_to_record_ratio(
    batches: List[Dict[str, Any]],
    lifetime_stats_path: Path,
) -> Dict[str, Any]:
    """Promote rate (records passing info-density filter / total records)."""
    # `discoveries_emitted` is the promote count
    cum_records = sum(b["total_records"] for b in batches)
    if lifetime_stats_path.exists():
        ls = json.loads(lifetime_stats_path.read_text())
        lifetime_promoted = ls.get("lifetime_discoveries_emitted", 0)
    else:
        lifetime_promoted = 0
    return {
        "lifetime_promoted_records": lifetime_promoted,
        "lifetime_records": cum_records,
        "promote_rate_per_million": round(
            lifetime_promoted / max(cum_records, 1) * 1_000_000, 2
        ),
    }

def metric_demand_signal_trajectory() -> Dict[str, Any]:
    """Aggregate demand signal events across all batches."""
    journal_dir = THESEUS_ROOT / "journals"
    if not journal_dir.is_dir():
        return {}
    total = 0
    by_signature: Dict[str, int] = defaultdict(int)
    n_files = 0
    for f in journal_dir.glob("demand_*.jsonl"):
        n_files += 1
        try:
            with f.open("r", encoding="utf-8") as fp:
                for line in fp:
                    rec = json.loads(line)
                    sig = "/".join(rec["signature"]) if rec["signature"] else "?"
                    n = rec["count"]
                    total += n
                    by_signature[sig] += n
        except (OSError, json.JSONDecodeError):
            continue
    top10 = sorted(by_signature.items(), key=lambda x: -x[1])[:10]
    return {
        "n_demand_files": n_files,
        "total_demand_events": total,
        "distinct_signatures": len(by_signature),
        "top_10": top10,
    }

def old_base(rec: dict) -> float:
    p = rec.get("claim_payload") or {}
    rel = p.get("relation", "")
    if rel in PER_RELATION_OLD:
        return PER_RELATION_OLD[rel]
    if rel.startswith("abs_diff_le_"):
        try:
            return abs_diff_K_weight(int(rel.rsplit("_", 1)[-1]))
        except ValueError:
            return 0.25
    return KIND_DEFAULT.get(rec.get("claim_kind", ""), 0.25)

def old_verdict_mult(rec: dict) -> float:
    v = rec.get("verdict", "")
    if v == "PROMOTED": return 1.5
    if v == "SHADOW_CATALOG": return 1.0
    if v == "INCONCLUSIVE": return 0.6
    if v == "REJECTED":
        kp = rec.get("kill_pattern") or ""
        return 1.0 if any(s in kp for s in (
            "specific", "violated", "boundary",
            "F1_triggered", "F6_triggered", "F9_triggered", "F11_triggered"
        )) else 0.6
    if v == "UNVERIFIED": return 0.1
    return 0.3

def old_weight(rec: dict) -> float:
    base = old_base(rec)
    v = old_verdict_mult(rec)
    t = 1.3 if rec.get("step_trace") else 1.0
    return max(0.0, min(1.0, base * v * t))

def template_key(rec: dict) -> str:
    """Stable identifier for a record's template shape."""
    p = rec.get("claim_payload") or {}
    return f"{rec.get('generator_id')}:{rec.get('claim_kind')}:{p.get('relation', '?')}"

def trim_record(rec: dict) -> dict:
    """Strip large fields to keep the sample compact."""
    keep_keys = {
        "record_id", "batch_id", "generator_id", "claim_kind",
        "verdict", "kill_pattern", "claim_payload",
        "canonical_claim_text", "step_trace",
    }
    out = {k: rec[k] for k in keep_keys if k in rec}
    # truncate text fields
    if "canonical_claim_text" in out:
        out["canonical_claim_text"] = (out["canonical_claim_text"] or "")[:300]
    return out

def _load_axis_values(domain: str, axis_field: str) -> list[float]:
    """Load the primary axis values for a domain.

    Currently wired for "mahler" via prometheus_math.databases.mahler.
    BSD / OEIS / NF stubs raise UnknownDomainError until the per-domain
    accessors land in v3 Phase 1.
    """
    if domain == "mahler":
        from prometheus_math.databases.mahler import all_below
        entries = all_below(2.0)
        out: list[float] = []
        for e in entries:
            m = e.get("mahler_measure")
            if m is None or m <= 1.0 + 1e-9:
                continue
            out.append(float(m))
        return out
    elif domain in ("bsd", "oeis", "number_field"):
        raise UnknownDomainError(
            f"Domain {domain!r} accessor not yet installed (Phase 1 work)"
        )
    else:
        raise UnknownDomainError(
            f"Domain {domain!r} unknown. Registered: mahler"
        )

def _median_pairwise_gap(values: list[float]) -> float:
    """Median of consecutive-sorted-gap distribution. Natural scale
    for epsilon-band thresholds."""
    if len(values) < 2:
        return 0.0
    sorted_v = sorted(values)
    gaps = [sorted_v[i + 1] - sorted_v[i] for i in range(len(sorted_v) - 1)]
    return statistics.median(gaps)

def _percentiles(values: list[float]) -> dict[str, float]:
    """Compute {p05, p25, p50, p75, p95, p99} via statistics.quantiles."""
    if not values:
        return {k: 0.0 for k in ("p05", "p25", "p50", "p75", "p95", "p99")}
    sorted_v = sorted(values)
    n = len(sorted_v)

    def pct(p: float) -> float:
        # Linear interpolation; matches numpy's default percentile behavior
        idx = p * (n - 1)
        lo = int(math.floor(idx))
        hi = int(math.ceil(idx))
        if lo == hi:
            return sorted_v[lo]
        frac = idx - lo
        return sorted_v[lo] * (1 - frac) + sorted_v[hi] * frac

    return {
        "p05": pct(0.05),
        "p25": pct(0.25),
        "p50": pct(0.50),
        "p75": pct(0.75),
        "p95": pct(0.95),
        "p99": pct(0.99),
    }

def _silverman_bandwidth(values: list[float]) -> float:
    """Silverman's rule of thumb for Gaussian KDE bandwidth."""
    n = len(values)
    if n < 2:
        return 0.1
    std = statistics.stdev(values)
    if std == 0:
        return 0.1
    return 1.06 * std * (n ** (-0.2))

def catalog_profile(
    domain: str, *, refresh: bool = False
) -> CatalogProfile:
    """Return cached profile for domain. Recompute if refresh=True or
    cache miss / stale."""
    if not refresh and domain in _runtime_cache:
        return _runtime_cache[domain]

    cache_path = _cache_path_for(domain)
    if not refresh and cache_path.exists():
        try:
            with cache_path.open("rb") as f:
                profile: CatalogProfile = pickle.load(f)
            if profile.domain == domain:
                _runtime_cache[domain] = profile
                return profile
        except Exception:
            pass  # fall through to recompute

    # Compute fresh
    profile = _compute_profile(domain)
    try:
        with cache_path.open("wb") as f:
            pickle.dump(profile, f)
    except Exception:
        pass  # cache is best-effort
    _runtime_cache[domain] = profile
    return profile

def bootstrap_ci_for(
    domain: str, parameter_name: str
) -> tuple[float, float]:
    """Return the bootstrap 95% CI (lo, hi) for a parameter. Used as
    data-driven tolerance / boundary in loaders that fit parameters."""
    ci = catalog_profile(domain).bootstrap_ci
    if parameter_name not in ci:
        raise ValueError(
            f"bootstrap_ci_for: parameter {parameter_name!r} not in "
            f"{sorted(ci.keys())} for domain {domain!r}"
        )
    return ci[parameter_name]

def known_domains() -> list[str]:
    """Return sorted list of registered catalog domains."""
    return sorted(_KNOWN_DOMAINS.keys())

def clear_runtime_cache() -> None:
    """Test helper — clear in-memory cache only (pickle stays)."""
    _runtime_cache.clear()

def density_kde(self, x: float, *, values: Optional[list[float]] = None) -> float:
    """Gaussian KDE evaluated at x. If values is supplied, use it;
    otherwise reconstruct from the catalog (slower)."""
    if values is None:
        values = _load_axis_values(self.domain, self.primary_axis_field)
    h = self.kde_bandwidth if self.kde_bandwidth > 0 else 0.1
    n = len(values)
    if n == 0:
        return 0.0
    coeff = 1.0 / (n * h * math.sqrt(2 * math.pi))
    return coeff * sum(
        math.exp(-0.5 * ((x - v) / h) ** 2) for v in values
    )

def classify_mechanism(kill_pattern: str | None) -> str:
    if not kill_pattern:
        return "unnamed"
    for rx, mech in _MECHANISM_PATTERNS:
        if rx.match(kill_pattern):
            return mech
    return "other"

def extract_objects(rec: dict) -> Tuple[str | None, str | None]:
    """Pull the first (knot, ec) labels referenced anywhere in the record."""
    blob = rec.get("canonical_claim_text", "")
    payload = rec.get("claim_payload") or {}
    for k in ("subject_left_label", "subject_right_label", "object_a", "object_b",
              "source_object", "witness", "object", "subject_record_summary"):
        v = payload.get(k)
        if isinstance(v, str):
            blob += " " + v
    km = KNOT_RE.search(blob)
    em = EC_RE.search(blob)
    return (km.group(1) if km else None, em.group(1) if em else None)

def ec_conductor_band(ec_label: str | None) -> str | None:
    """Band an EC by conductor magnitude — coarse bucketing."""
    if not ec_label:
        return None
    m = re.match(r"^(\d+)", ec_label)
    if not m:
        return None
    n = int(m.group(1))
    for bound, name in [
        (50, "cond<50"), (100, "cond<100"), (500, "cond<500"),
        (1000, "cond<1K"), (5000, "cond<5K"), (10000, "cond<10K"),
        (50000, "cond<50K"), (10**6, "cond<1M"),
    ]:
        if n < bound:
            return name
    return "cond>=1M"

def co_occurrence_matrix(obj_to_mechs: Dict[str, set], min_obj: int = 50) -> Tuple[List[str], Dict[Tuple[str, str], int]]:
    """For each pair of mechanism classes, count how many shared objects
    have both. Restrict to objects that appear in ≥ min_obj kills (already
    a set, so ≥ 1 mech per object — use object_count itself as filter)."""
    mech_counter = Counter()
    pair_counter = Counter()
    for obj, mechs in obj_to_mechs.items():
        ms = sorted(mechs)
        for m in ms:
            mech_counter[m] += 1
        for i in range(len(ms)):
            for j in range(i + 1, len(ms)):
                pair_counter[(ms[i], ms[j])] += 1
    mechs = sorted(mech_counter.keys())
    return mechs, pair_counter

def fmt_int(n) -> str:
    try:
        return f"{int(n):,}"
    except Exception:
        return str(n)

def _codomain_bounded_trivial(f, g, rel):
    """abs_diff_le_K with bounded-codomain operator: max |f-g| <= sum of codomain bounds."""
    if not rel.startswith("abs_diff_le_"):
        return False, ""
    try:
        K = int(rel.split("_")[-1])
    except ValueError:
        return False, ""
    f_b = _BOUNDED_CODOMAIN.get(f)
    g_b = _BOUNDED_CODOMAIN.get(g)
    if f_b is not None and g_b is not None:
        if f_b + g_b <= K:
            return True, f"both ops bounded ({f}<={f_b}, {g}<={g_b}); max diff <={f_b+g_b}<=K={K}"
    if f_b is not None and f_b <= K:
        # if g unbounded but f bounded, holds when g(x) is in [-K, f_b+K]
        # which is most catalog values — not always trivial, mark as weak
        return False, ""
    return False, ""

def classify_cell(cell):
    """Return (category, is_trivial, reason)."""
    f, g, rel = cell["f"], cell["g"], cell["rel"]
    rate = cell["hold_rate"]

    # Strong-identity (rate >= 0.95)
    if rate >= 0.95:
        cb_trivial, cb_reason = _codomain_bounded_trivial(f, g, rel)
        if cb_trivial:
            return ("strong_identity", True, cb_reason)
        # 1. equal_mod_2 with neg or identity-equivalent ops: a ≡ -a (mod 2)
        if rel == "equal_mod_2":
            return ("strong_identity", True,
                    "equal_mod_2 is parity — many op pairs preserve parity trivially")
        # 2. divides with sq_mod_100 or mod_3 (small range → 0 divides 0 often)
        if rel == "divides" and (f in ("mod_3", "sq_mod_100") or g in ("mod_3", "sq_mod_100")):
            return ("strong_identity", True,
                    "small-range modular operators produce many 0s; 0 divides 0")
        # 3. abs_diff_le_K with one bounded-codomain op + identity/abs/neg: shape-bounded
        if rel.startswith("abs_diff_le_"):
            if f in _BOUNDED_CODOMAIN or g in _BOUNDED_CODOMAIN:
                return ("strong_identity", True,
                        "one operator has bounded codomain; difference bounded by catalog scale, not algebra")
        return ("strong_identity", False, "candidate non-trivial identity")

    # Anti-identity (rate <= 0.05)
    if rate <= 0.05:
        if rel == "equal" and (f != g or f == "identity"):
            return ("anti_identity", True,
                    "equal across cross-catalog values is rare; expected")
        return ("anti_identity", False, "candidate structural incompatibility")

    return ("mid_band", False, "")

def signature_half(k) -> Optional[int]:
    sig = _get_int(k, "signature")
    if sig is None:
        return None
    return abs(sig) // 2

def F1_promotes(r: TheseusRecord) -> bool:
    w = training_weight(r)
    return w >= F1_THRESHOLD

def _value_from_invariant(k, invariant: str) -> Optional[int]:
    if invariant == "signature_half":
        return signature_half(k)
    return _get_int(k, invariant)

def _is_self_tautology(records: List[TheseusRecord]) -> bool:
    """Detect claims of form 'X RELATION X' where X is the same value
    on both sides (same object + same invariant). Such claims are
    structurally trivial regardless of relation."""
    n_self = 0
    for r in records:
        p = r.claim_payload
        if (p.get("object_a") == p.get("object_b")
            and p.get("invariant_a") == p.get("invariant_b")
            and p.get("value_a_raw") == p.get("value_b_raw")):
            n_self += 1
    return n_self >= 0.95 * len(records)

def load_existing_promoted_sample(n: int, rng) -> List[TheseusRecord]:
    """Load up to n records from recent batches that meet the existing
    promote filter. These represent the substrate's current 2351
    promoted-record cohort."""
    import glob
    batches = sorted(
        glob.glob(str(Path(__file__).resolve().parents[2] / "theseus" / "corpus" / "batch-*.jsonl")),
        reverse=True,
    )[:30]
    out: List[TheseusRecord] = []
    seen = 0
    target_seen = 2_000_000  # scan budget
    for bp in batches:
        if len(out) >= n or seen >= target_seen:
            break
        with open(bp, encoding="utf-8") as f:
            for line in f:
                seen += 1
                if seen > target_seen:
                    break
                try:
                    rec = json.loads(line)
                except Exception:
                    continue
                try:
                    r = TheseusRecord(**rec)
                except (TypeError, ValueError):
                    continue
                # Only keep records that pass F1 (i.e. would have been promoted)
                try:
                    if training_weight(r) >= F1_THRESHOLD:
                        out.append(r)
                        if len(out) >= n:
                            break
                except Exception:
                    continue
    rng.shuffle(out)
    return out[:n]

def ap_at(e, prime_idx: int) -> Optional[int]:
    ap_list = (e.get("base") or {}).get("a_p")
    if not isinstance(ap_list, list) or prime_idx >= len(ap_list):
        return None
    v = ap_list[prime_idx]
    if isinstance(v, int):
        return v
    return None

def gen_random_marginal(ecs, rng, n: int) -> List[TheseusRecord]:
    """torsion sampled from torsion marginal; n_pts sampled from n_pts marginal."""
    nontrivial = [e for e in ecs if (torsion(e) or 1) >= 2]
    tor_pool = [torsion(e) for e in nontrivial]
    npts_pool = []
    for e in nontrivial:
        for p_idx in range(len(PRIMES)):
            if is_good_prime(e, p_idx):
                ap = ap_at(e, p_idx)
                if ap is not None:
                    npts_pool.append(PRIMES[p_idx] + 1 - ap)
    out = []
    while len(out) < n:
        t = rng.choice(tor_pool)
        n_pts = rng.choice(npts_pool)
        out.append(build_record(
            "RANDOM_MARGINAL", "synthetic", t,
            PRIMES[0], n_pts, "divides",
        ))
    return out

def _is_self_tautology(records: List[TheseusRecord]) -> bool:
    n_self = 0
    for r in records:
        p = r.claim_payload
        if (p.get("object_a") == p.get("object_b")
            and p.get("invariant_a") == p.get("invariant_b")
            and p.get("value_a_raw") == p.get("value_b_raw")):
            n_self += 1
    return n_self >= 0.95 * len(records)

def F2_score_source(records, rng) -> Tuple[float, float, float, bool]:
    if not records:
        return (0.0, 0.0, 0.0, False)
    if _is_self_tautology(records):
        return (1.0, 1.0, 0.0, False)
    rel = records[0].claim_payload["relation"]
    n_hold = 0
    for r in records:
        a = r.claim_payload["value_a_raw"]
        b = r.claim_payload["value_b_raw"]
        if _evaluate_relation(a, b, rel):
            n_hold += 1
    obs = n_hold / len(records)
    null = F2_null_hold_rate(records, rng)
    contrast = abs(obs - null)
    return (obs, null, contrast, contrast >= F2_THRESHOLD)
